class MiniMaxH3TaggedReferenceToVideo:
    @classmethod
    def INPUT_TYPES(cls):
        scheduled = MiniMaxH3ScheduledReferenceToVideo.INPUT_TYPES()
        required = dict(scheduled["required"])
        required.pop("reference_schedule")
        required["prompt"] = ("STRING", {
            "default": "", "multiline": True, "dynamicPrompts": True,
            "tooltip": "Resolved current-scene prompt. Mention a registered "
                       "@tag to activate that asset for this scene. Only "
                       "registered reference tags are replaced with native "
                       "H3 labels; unrelated @syntax remains unchanged. For "
                       "a Tagged Picture, bare #tag adds an untimed Qwen-only "
                       "visual. #tag[2.50s] creates either a "
                       "timestamped semantic checkpoint or an approximate "
                       "Picture storyboard cue at 2.50 seconds into this "
                       "scene. Neither is a hard frame or spatial lock."})
        required["references"] = (TAGGED_REFERENCE_TYPE, {
            "tooltip": "Final Tagged Picture/Video/Audio reference line, "
                       "normally from Semantic Anchor Bundle when semantic "
                       "pictures are registered. A source "
                       "is active when its registered @tag occurs in the "
                       "resolved prompt. Tagged Pictures can additionally be "
                       "used through bare #tag semantic pictures, or through "
                       "#tag[timestamp] checkpoints/storyboard cues."})
        # Preserve the natural graph order: model inputs, references, current
        # scene metadata, prompt, and generation settings.
        ordered = {}
        for name in (
                "clip", "vae", "audio_vae", "references", "clip_index",
                "clip_count", "prompt", "width", "height", "length",
                "ref_image_size"):
            ordered[name] = required[name]
        optional = {
            "state": (STATE_TYPE, {
                "tooltip": "Current Shot state. Required by tagged video "
                           "sequential mode and tagged audio source_timeline. "
                           "It supplies exact scene timing; masked sequential "
                           "motion skips the repeated continuation prefix. "
                           "Dynamic media does not route back through the "
                           "Plan fingerprint."}),
            "reference_policy": (list(REFERENCE_COMPLIANCE_MODES), {
                "default": "strict",
                "tooltip": "strict validates sources and stock H3 reference "
                           "capacity. soft retains those structural checks. "
                           "disabled makes pack-authored validation warning-only, "
                           "skips missing/invalid tagged media, and passes @tags "
                           "unchanged. Unregistered @syntax is always preserved "
                           "because it may represent a subject or dialogue tag."}),
            "semantic_anchor_size": (list(SEMANTIC_ANCHOR_SIZES), {
                "default": "512",
                "tooltip": "Qwen-only #tag and #tag[timestamp] image "
                           "resolution. "
                           "512 is the balanced default; 1024 and 1280 retain "
                           "more visual detail but increase Qwen token cost. "
                           "This affects only semantic visual tokens, never "
                           "native Ref2VA VAE reference latents."}),
            # Keep this after semantic_anchor_size so older serialized
            # widgets_values continue to deserialize positionally.
            "semantic_anchor_mode": (list(SEMANTIC_ANCHOR_MODES), {
                "default": "timestamped_video",
                "tooltip": "Bare #tag always presents an untimed Qwen "
                           "Picture. timestamped_video presents #tag[time] "
                           "as a scene-local Qwen Video checkpoint. "
                           "picture_storyboard keeps each tagged image as a "
                           "separate Qwen-only <Picture N> and writes its "
                           "timestamps as approximate prompt instructions. "
                               "Neither mode creates a VAE reference."}),
            "cache_for_upscale": ("BOOLEAN", {
                "default": True,
                "tooltip": "Automatically save native H3 reference latents, "
                           "compact Qwen presentation frames, and original "
                           "picture masters for target-resolution pass 2. "
                           "Deferred upscale discovers the cache from the "
                           "source checkpoint fingerprint."}),
            # Append new widgets so existing serialized positional values keep
            # their original meaning.
            "conditioning_backend": (list(TAGGED_CONDITIONING_BACKENDS), {
                "default": "native_ref2va",
                "tooltip": "native_ref2va preserves the existing stock H3 "
                           "reference path. external_refmod emits text-only "
                           "conditioning plus the active scene pictures/videos "
                           "through refmod_sources; connect that output to "
                           "Extract H3 RefMod, then apply the resulting mod to "
                           "positive before Chain Context. Active #semantic "
                           "anchors use a hybrid path: only those timed images "
                           "are presented to Qwen, while ordinary @visuals "
                           "remain RefMods."}),
        }
        return {"required": ordered, "optional": optional}

    @classmethod
    def VALIDATE_INPUTS(
            cls, reference_policy="strict",
            semantic_anchor_mode="timestamped_video",
            semantic_anchor_size="512",
            conditioning_backend="native_ref2va"):
        try:
            _reference_compliance_mode(reference_policy)
            _semantic_anchor_mode(semantic_anchor_mode)
            _tagged_conditioning_backend(conditioning_backend)
            if str(semantic_anchor_size) not in SEMANTIC_ANCHOR_SIZES:
                raise ValueError(
                    "Semantic anchor size must be one of %s." %
                    (SEMANTIC_ANCHOR_SIZES,))
        except ValueError as exc:
            return str(exc)
        return True

    RETURN_TYPES = (
        "CONDITIONING", "LATENT", "STRING", "STRING", "STRING",
        REFMOD_SOURCE_LIST_TYPE)
    RETURN_NAMES = (
        "positive", "latent", "compiled_prompt", "active_references",
        "reference_fingerprint", "refmod_sources")
    OUTPUT_TOOLTIPS = (
        "Native Ref2VA conditioning, or text-only H3 conditioning when the "
        "external_refmod backend is selected.",
        "Matching empty MiniMax H3 AV latent for the selected backend.",
        "Exact prompt sent to H3 after native @tags and semantic #anchors compile.",
        "Scene-local mapping of native references, RefMods, and Qwen-only "
        "semantic anchors.",
        "Fingerprint of the complete registered source set for Plan checkpoint safety.",
        "Active scene pictures and resolved video slices as H3_REF_LIST. "
        "Connect to Extract H3 RefMod refs_bundle; audio and semantic-only "
        "anchors are excluded.",
    )
    FUNCTION = "apply"
    CATEGORY = "conditioning/minimax/context_loop/references/prompt_driven"
    DESCRIPTION = ("Prompt-driven H3 references with no numeric schedule. "
                   "Each scene activates only registered @tags present in its "
                   "resolved prompt, compactly renumbers those assets to native "
                   "H3 labels, and leaves unrelated @syntax untouched. A "
                   "Tagged Picture can also be written as bare #tag for an "
                   "untimed Qwen-only Picture, or #tag[2.50s] for either a "
                   "timestamped Qwen semantic checkpoint or an "
                   "approximate Qwen-only Picture storyboard cue without a "
                   "VAE reference. The optional external_refmod backend exposes "
                   "the active @visual tensors while producing text-only base "
                   "conditioning for ComfyUI-MiniMaxH3Mod; active #anchors "
                   "retain their optional timing through an anchor-only Qwen "
                   "hybrid pass.")

    def apply(self, clip, vae, audio_vae, references, clip_index,
              clip_count, prompt, width, height, length,
              ref_image_size="match", state=None,
              reference_policy="strict", semantic_anchor_size="512",
              semantic_anchor_mode="timestamped_video",
              cache_for_upscale=True,
              conditioning_backend="native_ref2va"):
        if GraphBuilder is None:
            raise RuntimeError(
                "Tagged H3 Ref2VA requires ComfyUI GraphBuilder.")
        backend = _tagged_conditioning_backend(conditioning_backend)
        anchor_bundle = _reference_semantic_anchor_bundle(references)
        if anchor_bundle is not None:
            if (anchor_bundle["semantic_anchor_size"] !=
                    SEMANTIC_ANCHOR_INHERIT):
                semantic_anchor_size = anchor_bundle["semantic_anchor_size"]
            if (anchor_bundle["semantic_anchor_mode"] !=
                    SEMANTIC_ANCHOR_INHERIT):
                semantic_anchor_mode = anchor_bundle["semantic_anchor_mode"]
        inherited_anchor_presentation = bool(
            anchor_bundle is not None and (
                anchor_bundle["semantic_anchor_size"] ==
                SEMANTIC_ANCHOR_INHERIT or
                anchor_bundle["semantic_anchor_mode"] ==
                SEMANTIC_ANCHOR_INHERIT))
        compiled, summary, bindings = _compile_tagged_reference_prompt(
            references, clip_index, clip_count, prompt, reference_policy,
            semantic_anchor_mode, anchor_bundle)
        # Project assets remain path-backed until their tag is active in this
        # scene.  Materialize only the selected pictures/anchors here; videos
        # and audio retain their existing scene-window lazy decoders.
        bindings["pictures"] = [
            {**entry, "value": _project_asset_image(entry["value"])}
            for entry in bindings["pictures"]
        ]
        bindings["semantic_anchors"] = [{
            **anchor,
            "entry": {
                **anchor["entry"],
                "value": _project_asset_image(anchor["entry"]["value"]),
            },
        } for anchor in (bindings.get("semantic_anchors") or [])]
        semantic_anchors = bindings.get("semantic_anchors") or []
        hybrid_anchors = semantic_anchors
        if backend == "external_refmod":
            unsupported = []
            if bindings["audios"]:
                unsupported.append("standalone tagged audio")
            if any(entry.get("audio") is not None
                   for entry in bindings["videos"]):
                unsupported.append("paired reference-video audio")
            if unsupported:
                raise ValueError(
                    "Tagged Ref2VA external_refmod is visual-only and cannot "
                    "preserve active %s. Remove those tags for this test or "
                    "switch conditioning_backend to native_ref2va." %
                    ", ".join(unsupported))
            compiled, hybrid_anchors = _compile_refmod_hybrid_prompt(
                prompt, bindings, semantic_anchors, semantic_anchor_mode)
            refmod_tags = [
                "@%s" % entry["tag"]
                for entry in (
                    list(bindings.get("pictures") or ())
                    + list(bindings.get("videos") or ()))
            ]
            anchor_mappings = [
                "#%s -> %s" % (item["tag"], item["hybrid_label"])
                for item in hybrid_anchors
            ]
            summary = "scene %d/%d: %s" % (
                int(clip_index), int(clip_count),
                "; ".join(
                    (["RefMod " + ", ".join(refmod_tags)]
                     if refmod_tags else [])
                    + anchor_mappings)
                or "no tagged references used by prompt")
            if bindings.get("compliance_warnings"):
                summary += "; warning-only: %s" % " ".join(
                    bindings["compliance_warnings"])
            elif bindings.get("compliance_mode") == "disabled":
                summary += "; reference policy disabled; @tags passed unchanged"

        graph = GraphBuilder()
        slice_details = []
        presentation_videos = []
        resolved_videos = []
        for entry in bindings["videos"]:
            video, paired_audio, detail = _scheduled_video_reference_slice(
                entry, state, clip_index, clip_count, length)
            presentation_videos.append({
                "video": video,
                "paired_audio": paired_audio is not None,
            })
            resolved_videos.append({"video": video, "audio": paired_audio})
            if detail:
                slice_details.append(detail)
        resolved_audios = []
        if backend == "native_ref2va":
            for entry in bindings["audios"]:
                audio, detail = _tagged_audio_reference_value(
                    entry, state, clip_index, clip_count, length)
                resolved_audios.append(audio)
                if detail:
                    slice_details.append(detail)

        refmod_sources = [
            entry["value"] for entry in bindings["pictures"]
        ] + [item["video"] for item in resolved_videos]
        if backend == "native_ref2va":
            conditioner = graph.node(
                "MiniMaxH3ReferenceToVideo", "TaggedRef2VA")
            for key, value in (
                    ("clip", clip), ("vae", vae),
                    ("audio_vae", audio_vae), ("prompt", compiled),
                    ("width", int(width)), ("height", int(height)),
                    ("length", int(length)),
                    ("ref_image_size", ref_image_size)):
                conditioner.set_input(key, value)
            for index, entry in enumerate(bindings["pictures"]):
                conditioner.set_input(
                    "ref_images.ref_image_%d" % index, entry["value"])
            for index, item in enumerate(resolved_videos):
                conditioner.set_input(
                    "ref_videos.ref_video_%d" % index, item["video"])
                if item.get("audio") is not None:
                    conditioner.set_input(
                        "ref_video_audios.ref_video_audio_%d" % index,
                        item["audio"])
            for index, audio in enumerate(resolved_audios):
                conditioner.set_input(
                    "ref_audios.ref_audio_%d" % index, audio)
        else:
            if not refmod_sources:
                raise ValueError(
                    "Tagged Ref2VA external_refmod needs at least one active "
                    "visual @tag in the current scene prompt.")
            conditioner = graph.node(
                "MiniMaxH3ImageToVideo", "TaggedRefModBase")
            for key, value in (
                    ("clip", clip), ("vae", vae), ("prompt", compiled),
                    ("width", int(width)), ("height", int(height)),
                    ("length", int(length))):
                conditioner.set_input(key, value)
            summary += (
                "; external RefMod base: %d visual source(s), text-only "
                "conditioning; Extract/Apply settings are external to the "
                "Plan fingerprint" % len(refmod_sources))
        if isinstance(references, dict) and references.get("fingerprint"):
            fingerprint_registry = _combined_reference_registry(
                references, anchor_bundle)
            fingerprint = str(fingerprint_registry["fingerprint"])
            fingerprint_output = _reference_fingerprint_output(
                fingerprint_registry,
                wrapper_key=(
                    "tagged_reference_fingerprint"
                    if backend == "external_refmod" else ""),
                wrapper_contract=(
                    {
                        "conditioning_backend": backend,
                        "external_refmod_contract": (
                            EXTERNAL_REFMOD_CONTRACT_VERSION),
                    }
                    if backend == "external_refmod" else None))
            if backend == "external_refmod":
                fingerprint = _fingerprint({
                    "tagged_reference_fingerprint": fingerprint,
                    "conditioning_backend": backend,
                    "external_refmod_contract": (
                        EXTERNAL_REFMOD_CONTRACT_VERSION),
                })
        elif _reference_compliance_mode(reference_policy) == "disabled":
            fingerprint = _fingerprint({
                "tagged_references": "ignored",
                "reference_policy": "disabled",
                **({
                    "conditioning_backend": backend,
                    "external_refmod_contract": (
                        EXTERNAL_REFMOD_CONTRACT_VERSION),
                }
                   if backend == "external_refmod" else {}),
            })
            fingerprint_output = fingerprint
        else:
            raise ValueError(
                "Tagged references have no valid reference fingerprint.")
        positive = conditioner.out(0)
        latent = conditioner.out(1)
        presentation = None
        if semantic_anchors:
            anchor_mode = _semantic_anchor_mode(semantic_anchor_mode)
            anchor_size = str(semantic_anchor_size)
            presentation = {
                "version": SEMANTIC_PRESENTATION_VERSION,
                "width": int(width),
                "height": int(height),
                "length": int(length),
                "ref_image_size": str(ref_image_size),
                "semantic_anchor_size": anchor_size,
                "semantic_anchor_mode": anchor_mode,
                # The external hybrid deliberately omits ordinary @media:
                # Extract/Apply carries those as RefMods.  Qwen sees only the
                # semantic pictures/checkpoints and retains the speed win.
                "pictures": ([] if backend == "external_refmod" else [
                    entry["value"] for entry in bindings["pictures"]]),
                "videos": ([] if backend == "external_refmod"
                           else presentation_videos),
                "standalone_audio_count": (
                    0 if backend == "external_refmod"
                    else len(bindings["audios"])),
                "anchors": [{
                    "tag": anchor["tag"],
                    "image": anchor["entry"]["value"],
                    "timestamps": tuple(anchor["timestamps"]),
                    **({"untimed": True}
                       if anchor.get("untimed") else {}),
                } for anchor in hybrid_anchors],
            }
            semantic = graph.node(
                "MiniMaxH3SemanticAnchorConditioning", "SemanticAnchors")
            semantic.set_input("positive", positive)
            semantic.set_input("clip", clip)
            semantic.set_input("prompt", compiled)
            semantic.set_input("presentation", presentation)
            positive = semantic.out(0)
            if backend == "external_refmod":
                summary += (
                    "; hybrid Qwen: %d semantic anchor source(s) only" %
                    len(hybrid_anchors))
            fingerprint = _fingerprint({
                "tagged_reference_fingerprint": fingerprint,
                "semantic_anchor_mode": anchor_mode,
                "semantic_anchor_size": anchor_size,
            })
            if anchor_bundle is None or inherited_anchor_presentation:
                fingerprint_registry = (
                    _combined_reference_registry(references, anchor_bundle)
                    if anchor_bundle is not None else references)
                fingerprint_output = _reference_fingerprint_output(
                    fingerprint_registry,
                    wrapper_key="tagged_reference_fingerprint",
                    wrapper_contract={
                        "semantic_anchor_mode": anchor_mode,
                        "semantic_anchor_size": anchor_size,
                        **({
                            "conditioning_backend": backend,
                            "external_refmod_contract": (
                                EXTERNAL_REFMOD_CONTRACT_VERSION),
                        } if backend == "external_refmod" else {}),
                    })
        cache_fingerprint = _generation_fingerprint_value(
            fingerprint_output)[0]
        cache_runtime_ready = (
            callable(getattr(vae, "encode", None))
            and not isinstance(vae, (str, bytes))
            and (not resolved_audios and not any(
                item.get("audio") is not None for item in resolved_videos)
                 or (callable(getattr(audio_vae, "encode", None))
                     and not isinstance(audio_vae, (str, bytes)))))
        if (backend == "native_ref2va" and bool(cache_for_upscale)
                and cache_runtime_ready and (
                bindings["pictures"] or resolved_videos or resolved_audios
                or semantic_anchors)):
            try:
                cache_status = _cache_reference_scene(
                    fingerprint=cache_fingerprint, scene=clip_index,
                    scene_count=clip_count, prompt=prompt,
                    compiled_prompt=compiled, width=width, height=height,
                    length=length, ref_image_size=ref_image_size, vae=vae,
                    audio_vae=audio_vae,
                    pictures=[entry["value"] for entry in bindings["pictures"]],
                    videos=resolved_videos, audios=resolved_audios,
                    semantic_presentation=presentation)
                summary += "; " + cache_status
            except Exception as exc:
                _LOG.warning("H3 tagged reference cache was not saved: %s", exc)
        if slice_details:
            summary += "; " + "; ".join(slice_details)
        return {
            "result": (
                positive, latent, compiled, summary,
                fingerprint_output, refmod_sources),
            "expand": graph.finalize(),
        }


_TAGGED_SCENE_OPTION_DEFAULTS = {
    "ref_image_size": "match",
    "reference_policy": "strict",
    "semantic_anchor_size": "512",
    "semantic_anchor_mode": "timestamped_video",
    "cache_for_upscale": True,
    "conditioning_backend": "native_ref2va",
    "align_audio_reference": False,
}


def _tagged_scene_options(value: Any = None) -> dict[str, Any]:
    """Validate the strict, versioned settings carrier for the merged node."""
    if value is None:
        options = dict(_TAGGED_SCENE_OPTION_DEFAULTS)
    elif not isinstance(value, dict):
        raise ValueError(
            "Tagged Scene Options must come from MiniMax H3 Tagged Scene "
            "Options.")
    else:
        if int(value.get("version", -1)) != TAGGED_SCENE_OPTIONS_VERSION:
            raise ValueError(
                "Tagged Scene Options uses an unsupported contract version.")
        options = {
            key: value.get(key, default)
            for key, default in _TAGGED_SCENE_OPTION_DEFAULTS.items()
        }
    ref_image_size = str(options["ref_image_size"]).strip().lower()
    if ref_image_size not in ("match", "max"):
        raise ValueError("Reference image size must be match or max.")
    reference_policy = _reference_compliance_mode(
        options["reference_policy"])
    semantic_anchor_size = str(options["semantic_anchor_size"])
    if semantic_anchor_size not in SEMANTIC_ANCHOR_SIZES:
        raise ValueError(
            "Semantic anchor size must be one of %s." %
            (SEMANTIC_ANCHOR_SIZES,))
    semantic_anchor_mode = _semantic_anchor_mode(
        options["semantic_anchor_mode"])
    conditioning_backend = _tagged_conditioning_backend(
        options["conditioning_backend"])
    for key in ("cache_for_upscale", "align_audio_reference"):
        if not isinstance(options[key], bool):
            raise ValueError(
                "%s must be a boolean." % key.replace("_", " ").capitalize())
    return {
        "version": TAGGED_SCENE_OPTIONS_VERSION,
        "ref_image_size": ref_image_size,
        "reference_policy": reference_policy,
        "semantic_anchor_size": semantic_anchor_size,
        "semantic_anchor_mode": semantic_anchor_mode,
        "cache_for_upscale": options["cache_for_upscale"],
        "conditioning_backend": conditioning_backend,
        "align_audio_reference": options["align_audio_reference"],
    }


def _modern_current_scene(state: Any) -> tuple[dict[str, Any], int, dict[str, Any]]:
    """Return one current v0.5+ scene and reject legacy public contracts."""
    if not isinstance(state, dict) or not isinstance(state.get("plan"), dict):
        raise ValueError(
            "Current Tagged Ref2VA Scene requires state from the current H3 "
            "Chain Loop Start.")
    plan = state["plan"]
    if int(plan.get("version", -1)) != PLAN_VERSION:
        raise ValueError(
            "Current Tagged Ref2VA Scene does not expose the legacy 0.4 "
            "contract. Keep the separate Current Shot and Tagged Ref2VA "
            "nodes for that workflow.")
    shots = plan.get("shots")
    try:
        index = int(state["index"])
    except (KeyError, TypeError, ValueError) as exc:
        raise ValueError(
            "Current Tagged Ref2VA Scene received a state without a valid "
            "scene index.") from exc
    if (not isinstance(shots, list) or index < 1 or index > len(shots)
            or not isinstance(shots[index - 1], dict)):
        raise ValueError(
            "Current Tagged Ref2VA Scene received a state outside its Plan.")
    return plan, index, shots[index - 1]


class MiniMaxH3TaggedSceneOptions:
    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {
                "ref_image_size": (["match", "max"], {
                    "default": "match",
                    "tooltip": "Native Ref2VA reference-image sizing. This "
                               "is separate from semantic-anchor resolution."}),
                "reference_policy": (list(REFERENCE_COMPLIANCE_MODES), {
                    "default": "strict",
                    "tooltip": "Validation policy for prompt-driven @tags."}),
                "semantic_anchor_size": (list(SEMANTIC_ANCHOR_SIZES), {
                    "default": "512",
                    "tooltip": "Qwen presentation size for bare #tag and "
                               "#tag[timestamp] semantic visuals only."}),
                "semantic_anchor_mode": (list(SEMANTIC_ANCHOR_MODES), {
                    "default": "timestamped_video",
                    "tooltip": "Bare #tag stays an untimed Picture; timed "
                               "anchors become video checkpoints or Picture "
                               "storyboard cues."}),
                "cache_for_upscale": ("BOOLEAN", {
                    "default": True,
                    "tooltip": "Save native Ref2VA reference data for a "
                               "later target-resolution pass."}),
                "conditioning_backend": (list(TAGGED_CONDITIONING_BACKENDS), {
                    "default": "native_ref2va",
                    "tooltip": "Use native Ref2VA, or emit active visuals for "
                               "the external MiniMaxH3Mod RefMod path."}),
                "align_audio_reference": ("BOOLEAN", {
                    "default": False,
                    "tooltip": "Experimental: align only the current tagged "
                               "source-audio reference to H3's target grid."}),
            },
        }

    @classmethod
    def VALIDATE_INPUTS(cls, **kwargs):
        try:
            _tagged_scene_options({
                "version": TAGGED_SCENE_OPTIONS_VERSION,
                **kwargs,
            })
        except ValueError as exc:
            return str(exc)
        return True

    RETURN_TYPES = (TAGGED_SCENE_OPTIONS_TYPE,)
    RETURN_NAMES = ("options",)
    OUTPUT_TOOLTIPS = (
        "Validated modern settings for Current Tagged Ref2VA Scene.",)
    FUNCTION = "options"
    CATEGORY = "conditioning/minimax/context_loop/references/prompt_driven"
    DESCRIPTION = (
        "Reusable modern settings for Current Tagged Ref2VA Scene. The "
        "versioned carrier deliberately has no legacy 0.4 audio socket.")

    def options(self, ref_image_size="match", reference_policy="strict",
                semantic_anchor_size="512",
                semantic_anchor_mode="timestamped_video",
                cache_for_upscale=True,
                conditioning_backend="native_ref2va",
                align_audio_reference=False):
        return (_tagged_scene_options({
            "version": TAGGED_SCENE_OPTIONS_VERSION,
            "ref_image_size": ref_image_size,
            "reference_policy": reference_policy,
            "semantic_anchor_size": semantic_anchor_size,
            "semantic_anchor_mode": semantic_anchor_mode,
            "cache_for_upscale": cache_for_upscale,
            "conditioning_backend": conditioning_backend,
            "align_audio_reference": align_audio_reference,
        }),)


