def _preflight_issue(
        report: dict[str, Any], level: str, code: str, message: str,
        action: str = "", *, solutions: Any = None, triggers: Any = None,
        measurements: Any = None, **context: Any) -> None:
    ranked_solutions = []
    alternatives = ([solutions] if isinstance(solutions, str)
                    else list(solutions or ()))
    for candidate in ([action] + alternatives):
        text = str(candidate or "").strip()
        if text and text not in ranked_solutions:
            ranked_solutions.append(text)
    if level == "errors" and not ranked_solutions:
        ranked_solutions.append(
            "Correct the reported input or setting, then run preflight again.")
    issue = {"code": str(code), "message": str(message),
             "action": ranked_solutions[0] if ranked_solutions else "",
             "solutions": ranked_solutions}
    normalized_triggers = triggers
    if normalized_triggers is None:
        normalized_triggers = context.get("requirements")
    if normalized_triggers:
        issue["triggers"] = [
            dict(value) for value in normalized_triggers
            if isinstance(value, dict)]
    if isinstance(measurements, dict) and measurements:
        issue["measurements"] = dict(measurements)
    issue.update({key: value for key, value in context.items()
                  if value is not None})
    report[level].append(issue)


def _preflight_scene_trigger(
        shot: dict[str, Any], setting: str, value: Any,
        origin: str, *, tag: str = "") -> dict[str, Any]:
    scene = int(shot.get("index", 0))
    trigger = {
        "scope": "scene", "scene": scene,
        "scene_id": str(shot.get("id") or "scene_%d" % scene),
        "setting": str(setting), "value": value,
        "origin": str(origin),
    }
    if tag:
        trigger["tag"] = str(tag)
    return trigger


def _preflight_scene_location(
        plan: dict[str, Any], scene: int) -> dict[str, Any] | None:
    if int(scene) < 1 or int(scene) > len(plan.get("shots") or ()):
        return None
    shot = plan["shots"][int(scene) - 1]
    return {
        "scene": int(shot.get("index", scene)),
        "scene_id": str(shot.get("id") or "scene_%d" % int(scene)),
    }


def _preflight_source_required_frames(
        plan: dict[str, Any], requirements: list[dict[str, Any]]) -> int:
    if any(item.get("scope") == "final output" for item in requirements):
        return int(plan["total_delivered_frames"])
    required = 0
    for item in requirements:
        if item.get("scope") != "scene":
            continue
        scene = int(item["scene"])
        if 1 <= scene <= len(plan.get("shots") or ()):
            shot = plan["shots"][scene - 1]
            required = max(
                required,
                max(0, int(shot["generation_start_frame"]))
                + int(shot["raw_frames"]))
    return required


def _preflight_source_coverage(
        plan: dict[str, Any], available_frames: int,
        requirements: list[dict[str, Any]]) -> dict[str, Any]:
    cumulative = 0
    last_complete = 0
    first_affected = None
    final_output = any(
        item.get("scope") == "final output" for item in requirements)
    required_scenes = {
        int(item["scene"]) for item in requirements
        if item.get("scope") == "scene" and item.get("scene") is not None}
    for shot in plan.get("shots") or ():
        cumulative += int(shot["delivered_frames"])
        scene = int(shot["index"])
        required_end = (
            cumulative if final_output else
            max(0, int(shot["generation_start_frame"]))
            + int(shot["raw_frames"]))
        affected = (
            (final_output or scene in required_scenes)
            and int(available_frames) < required_end)
        if affected and first_affected is None:
            first_affected = int(shot["index"])
        if first_affected is None:
            last_complete = scene
    return {
        "last_complete_scene": _preflight_scene_location(plan, last_complete),
        "first_affected_scene": _preflight_scene_location(
            plan, first_affected) if first_affected is not None else None,
    }


def _format_preflight_trigger(trigger: dict[str, Any]) -> str:
    if trigger.get("scope") == "scene":
        location = 'Scene %d "%s"' % (
            int(trigger["scene"]), str(trigger.get("scene_id") or
                                       "scene_%d" % int(trigger["scene"])))
    else:
        location = str(trigger.get("scope") or "Plan")
    details = []
    if trigger.get("setting"):
        setting = str(trigger["setting"])
        if trigger.get("value") is not None:
            setting += "=%s" % trigger["value"]
        details.append(setting)
    if trigger.get("tag"):
        details.append("tag=%s" % trigger["tag"])
    rendered = "; ".join(details) or "affected"
    if trigger.get("origin"):
        rendered += " (%s)" % trigger["origin"]
    return "%s: %s" % (location, rendered)


def _format_preflight_location(value: Any) -> str:
    if not isinstance(value, dict) or value.get("scene") is None:
        return "none"
    return 'Scene %d "%s"' % (
        int(value["scene"]), str(value.get("scene_id") or
                                 "scene_%d" % int(value["scene"])))


def _preflight_reference_window(
        entry: dict[str, Any], plan: dict[str, Any], scene: int
        ) -> dict[str, Any] | None:
    if entry.get("kind") != "video":
        return None
    shots = plan["shots"]
    shot = shots[int(scene) - 1]
    mode = str(entry.get("timeline_mode") or "restart_each_scene")
    if mode == "restart_each_scene":
        start, length = 0, int(shot["raw_frames"])
    elif mode == "sequential":
        ranges = entry.get("ranges") or ()
        if entry.get("activation") == "prompt":
            aliases = set(_reference_entry_tags(entry))
            origin = next((
                index for index, candidate in enumerate(shots, 1)
                if aliases.intersection(_REFERENCE_ALIAS_RE.findall(
                    str(candidate.get("prompt") or "")))
            ), int(scene))
        else:
            origin = int(ranges[0][0]) if ranges else 1
        current_mode = str(shot.get(
            "continuation_mode",
            plan["compatibility"].get("continuation_mode", "guide")))
        if (entry.get("semantic_role") == "motion"
                and current_mode in MASKED_CONTINUATION_MODES):
            start = sum(int(item["delivered_frames"])
                        for item in shots[origin - 1:int(scene) - 1])
            length = int(shot["delivered_frames"])
        else:
            start = (int(shot["generation_start_frame"])
                     - int(shots[origin - 1]["generation_start_frame"]))
            length = int(shot["raw_frames"])
    else:
        raise ValueError(
            "Reference @%s has unknown timeline mode %r." %
            (entry.get("tag", "video"), mode))
    return {"mode": mode, "start_frame": int(start),
            "end_frame": int(start + length), "frame_count": int(length)}


def _preflight_runtime_compatibility(
        plan: dict[str, Any], report: dict[str, Any]) -> dict[str, Any]:
    try:
        from .patch_layout import compatibility_report, native_guides_available
    except ImportError as exc:
        runtime = {
            "guide": {"ok": None, "mode": "inspection_unavailable",
                      "message": str(exc)},
            "mask": {"needed": False},
        }
        _preflight_issue(
            report, "warnings", "runtime_inspection_unavailable",
            "H3 runtime compatibility could not be inspected in this "
            "model-free process: %s" % exc,
            "Run preflight inside the active ComfyUI process before sampling.",
            solutions=(
                "Restart ComfyUI if this report came from the active server; "
                "the runtime modules may not have finished loading.",),
            triggers=({
                "scope": "runtime", "setting": "compatibility_inspection",
                "value": "unavailable", "origin": "H3 preflight",
            },))
        return runtime

    guide = compatibility_report()
    runtime: dict[str, Any] = {"guide": guide, "mask": {"needed": False}}
    if not guide["ok"]:
        _preflight_issue(
            report, "errors", "guide_layout_conflict", guide["message"],
            guide["action"],
            solutions=(
                "Remove or update the conflicting H3 layout patch, then "
                "restart ComfyUI.",
                "Use a ComfyUI build with the native H3 guide API.",),
            triggers=({
                "scope": "runtime", "setting": "guide_layout_owner",
                "value": str(guide.get("owner") or "unavailable"),
                "origin": str(guide.get("mode") or "compatibility check"),
            },))
    masked_scenes = []
    masked_triggers = []
    default_mode = str(
        plan["compatibility"].get("continuation_mode", "guide"))
    for shot in plan["shots"]:
        mode = str(shot.get("continuation_mode", default_mode))
        if mode in MASKED_CONTINUATION_MODES:
            masked_scenes.append(int(shot["index"]))
            masked_triggers.append(_preflight_scene_trigger(
                shot, "continuation_mode", mode,
                "scene override" if shot.get("continuation_mode") is not None
                else "Plan compatibility"))
    if not masked_scenes:
        return runtime
    mask: dict[str, Any] = {"needed": True, "scenes": masked_scenes}
    runtime["mask"] = mask
    if not native_guides_available():
        mask.update({"ok": False, "mode": "native_guide_required"})
        _preflight_issue(
            report, "errors", "masked_av_requires_native_guides",
            "Masked AV continuation requires ComfyUI's native H3 guide API.",
            "Update ComfyUI to a build containing the native H3 Add Guide "
            "API, then restart ComfyUI.",
            solutions=(
                "Change the reported scenes to a non-masked continuation "
                "mode until the runtime is updated.",),
            triggers=masked_triggers, scenes=masked_scenes)
        return runtime
    try:
        from .h3_mask_compat import capability_status as engine_status
        from .h3_mask_payload_compat import capability_status as payload_status
        engine = engine_status()
        payload = payload_status()
        indicators = engine.get("mask_engine_indicators") or {}
        characteristic = [
            bool(indicators.get("mask_row_values")),
            bool(indicators.get("mod_row")),
            bool(indicators.get("forward_masks")),
            bool(indicators.get("inner_masks")),
        ]
        partial = any(characteristic) and not all(characteristic)
        mask.update({
            "ok": not partial,
            "mode": ("ready" if (
                engine.get("mask_engine_complete")
                and engine.get("velocity_mask_conversion")
                and (payload.get("native_av_mask_payload")
                     or payload.get("wrapper_present")))
                else "runtime_bridge_available"),
            "engine": engine,
            "payload": payload,
        })
        if partial:
            _preflight_issue(
                report, "errors", "partial_mask_runtime",
                "A partially updated H3 AV-mask runtime was detected.",
                "Update ComfyUI and this node pack together, then restart.",
                solutions=(
                    "Use a non-masked continuation mode for the reported "
                    "scenes until both components are matched.",),
                triggers=masked_triggers, scenes=masked_scenes)
    except Exception as exc:
        mask.update({"ok": False, "mode": "inspection_failed",
                     "detail": str(exc)})
        _preflight_issue(
            report, "errors", "mask_runtime_inspection_failed",
            "Could not inspect H3 AV-mask compatibility: %s" % exc,
            "Update ComfyUI and restart before using masked AV transitions.",
            solutions=(
                "Change the reported scenes to a non-masked continuation "
                "mode and run preflight again.",
                "Update this node pack if ComfyUI is already current.",),
            triggers=masked_triggers, scenes=masked_scenes)
    return runtime


def _preflight_source_measurements(
        plan: dict[str, Any], available_frames: int,
        requirements: list[dict[str, Any]]) -> dict[str, Any]:
    required_frames = _preflight_source_required_frames(plan, requirements)
    shortfall_frames = max(0, required_frames - int(available_frames))
    coverage = _preflight_source_coverage(
        plan, int(available_frames), requirements)
    return {
        "required_frames": required_frames,
        "required_seconds": required_frames / float(FPS),
        "available_frames": int(available_frames),
        "available_seconds": int(available_frames) / float(FPS),
        "shortfall_frames": shortfall_frames,
        "shortfall_seconds": shortfall_frames / float(FPS),
        **coverage,
    }


def _preflight_shortfall_solutions(
        measurements: dict[str, Any]) -> tuple[str, tuple[str, ...]]:
    minimum = "%.3fs (%d frames)" % (
        float(measurements["required_seconds"]),
        int(measurements["required_frames"]))
    primary = "Provide a source track at least %s long." % minimum
    alternatives = []
    last_complete = measurements.get("last_complete_scene")
    if isinstance(last_complete, dict):
        alternatives.append(
            "Shorten the Plan through %s, or trim/reposition later scenes "
            "inside the available source duration." %
            _format_preflight_location(last_complete))
    else:
        alternatives.append(
            "Shorten or reposition the first scene inside the available "
            "source duration.")
    alternatives.append(
        "If source audio was not intended, change the reported source-audio "
        "settings instead of supplying a track.")
    return primary, tuple(alternatives)


def _preflight_bind_source(
        plan: dict[str, Any], report: dict[str, Any],
        source_timeline: Any = None, source_audio: Any = None
        ) -> tuple[dict[str, Any], dict[str, Any] | None]:
    if source_timeline is not None and source_audio is not None:
        raise ValueError(
            "Connect Source Timeline or legacy source_audio, not both.")
    if source_timeline is None and isinstance(plan.get("source_timeline"), dict):
        source_timeline = _source_timeline_from_recovery(
            plan["source_timeline"])
    source_requirements = _audio_source_requirements(plan)
    required = bool(source_requirements)
    prepared = dict(plan)
    prepared["base_plan_hash"] = str(
        plan.get("base_plan_hash") or plan["plan_hash"])
    prepared["compatibility"] = dict(plan["compatibility"])
    required_frames = int(plan["total_delivered_frames"])
    source_report: dict[str, Any] = {
        "route": "none", "required_frames": required_frames,
        "required_seconds": required_frames / float(FPS),
        "requirements": source_requirements,
    }
    if source_timeline is not None:
        source = _validate_source_timeline(source_timeline)
        extent = int(source["extent"]["frame_count"])
        audio_frames = _source_timeline_available_audio_frames(source)
        source_report.update({
            "route": "source_timeline",
            "extent_frames": extent,
            "extent_seconds": extent / float(FPS),
            "audio_kind": source["audio"]["kind"],
            "audio_frames": audio_frames,
            "origin": dict(source["origin"]),
            "timeline_fingerprint": source["fingerprints"]["timeline"],
        })
        paths = []
        if source.get("video") is not None:
            paths.append(("video", str(source["video"].get("path") or "")))
        if source["audio"]["kind"] in ("embedded", "external_path"):
            paths.append(("audio", str(source["audio"].get("path") or "")))
        tracks = source.get("audio_tracks") or {}
        if tracks:
            source_report["audio_tracks"] = {
                "mix_mode": tracks["mix_mode"],
                "lip_sync_driver": "vocals" if tracks.get("vocals") else "none",
            }
            locked = [item for item in source_requirements
                      if item["setting"] == "source_audio_target"]
            if locked and not tracks.get("vocals"):
                _preflight_issue(
                    report, "errors", "source_vocals_missing",
                    "Lip-sync is enabled, but the audio group has no vocals.",
                    "Attach aligned vocals or turn Lip-sync off for the "
                    "reported scenes. Instruments are not a vocal substitute.",
                    triggers=locked)
            for role in ("vocals", "instrumental"):
                track = tracks.get(role)
                if track and track["audio"]["kind"] == "external_path":
                    paths.append((role, str(track["audio"].get("path") or "")))
        source_report["paths"] = [
            {"kind": kind, "path": path,
             "available": bool(path and os.path.isfile(path))}
            for kind, path in paths]
        for item in source_report["paths"]:
            if not item["available"]:
                _preflight_issue(
                    report, "errors", "source_path_missing",
                    "Source Timeline %s is unavailable: %s" %
                    (item["kind"], item["path"] or "<empty path>"),
                    "Relink the media in Source Timeline or restore its Run "
                    "Manager archive.",
                    solutions=(
                        "Select a replacement %s source in the Project Asset "
                        "Manager." % item["kind"],
                        "Remove the unavailable Source track if it is no "
                        "longer part of this Plan."),
                    triggers=({
                        "scope": "Source Timeline",
                        "setting": "%s_path" % item["kind"],
                        "value": item["path"] or "<empty path>",
                        "origin": "connected/recovered media",
                    },), kind=item["kind"], path=item["path"])
        if required and source["audio"]["kind"] == "none":
            _preflight_issue(
                report, "errors", "source_audio_missing",
                "Source Timeline has no audio, but the Plan settings listed "
                "below require it.",
                "Choose embedded or external audio for Source Timeline.",
                solutions=(
                    "Connect the legacy source_audio input instead of this "
                    "Source Timeline.",
                    "Change each reported setting at its reported scope if "
                    "source audio was not intended."),
                requirements=source_requirements,
                measurements=_preflight_source_measurements(
                    plan, 0, source_requirements))
        shortfall = max(0, required_frames - audio_frames) if required else 0
        source_report["shortfall_frames"] = shortfall
        source_report["shortfall_seconds"] = shortfall / float(FPS)
        if shortfall:
            measurements = _preflight_source_measurements(
                plan, audio_frames, source_requirements)
            source_report.update({
                "last_complete_scene": (
                    measurements["last_complete_scene"] or {}).get("scene", 0),
                "first_affected_scene": (
                    measurements["first_affected_scene"] or {}).get("scene"),
            })
            deferred = source["audio"].get("value")
            silent = False
            if (not tracks and source["audio"]["kind"] == "deferred_tensor"
                    and deferred is not None):
                waveform, _sample_rate = _validate_audio(
                    deferred, "Preflight Source Timeline audio")
                silent = _audio_is_silent(waveform)
            if silent:
                source_report["silent_padding_frames"] = shortfall
                _preflight_issue(
                    report, "warnings", "silent_source_will_pad",
                    "Silent placeholder audio is %.3f seconds short and will "
                    "be padded." % (shortfall / float(FPS)),
                    "No action is required unless real source audio was intended.",
                    solutions=(
                        "Replace the placeholder with a track at least %.3fs "
                        "long when real source audio is intended." %
                        measurements["required_seconds"],),
                    triggers=source_requirements,
                    measurements=measurements)
            else:
                action, alternatives = _preflight_shortfall_solutions(
                    measurements)
                _preflight_issue(
                    report, "errors", "source_audio_too_short",
                    "Source audio is %d frames (%.3fs) short." %
                    (shortfall, shortfall / float(FPS)),
                    action, solutions=alternatives,
                    triggers=source_requirements,
                    measurements=measurements)
        audio_hash = (str(source["fingerprints"].get("audio") or "none")
                      if required else "none")
        timeline_hash = str(source["fingerprints"]["timeline"])
        prepared["compatibility"].update({
            "source_audio_hash": audio_hash,
            "source_audio_silent_padding": bool(
                source_report.get("silent_padding_frames")),
            "source_timeline_fingerprint": timeline_hash,
        })
        prepared["plan_hash"] = _fingerprint({
            "prepared_plan_hash": plan["plan_hash"],
            "source_audio_hash": audio_hash,
            "source_timeline_fingerprint": timeline_hash,
        })
        report["source"] = source_report
        return prepared, source
    if required and source_audio is None:
        _preflight_issue(
            report, "errors", "source_audio_missing",
            "Loop Start source_timeline and legacy source_audio inputs are "
            "both disconnected, but the Plan settings listed below require "
            "source audio.",
            "Connect one H3 Source Timeline to Loop Start.",
            solutions=(
                "Use the legacy source_audio input instead.",
                "Change each reported setting at its reported scope if "
                "source audio was not intended."),
            requirements=source_requirements,
            measurements=_preflight_source_measurements(
                plan, 0, source_requirements))
        source_hash = "none"
    elif source_audio is not None:
        waveform, sample_rate = _validate_audio(
            source_audio, "Preflight legacy source audio")
        available = int(waveform.shape[-1])
        available_frames = int(math.floor(
            available / float(sample_rate) * FPS + 1e-9))
        shortfall = max(0, required_frames - available_frames) if required else 0
        source_report.update({
            "route": "legacy_audio", "sample_rate": sample_rate,
            "sample_count": available, "audio_frames": available_frames,
            "shortfall_frames": shortfall,
            "shortfall_seconds": shortfall / float(FPS),
        })
        if shortfall and not _audio_is_silent(waveform):
            measurements = _preflight_source_measurements(
                plan, available_frames, source_requirements)
            source_report.update({
                "last_complete_scene": (
                    measurements["last_complete_scene"] or {}).get("scene", 0),
                "first_affected_scene": (
                    measurements["first_affected_scene"] or {}).get("scene"),
            })
            action, alternatives = _preflight_shortfall_solutions(measurements)
            _preflight_issue(
                report, "errors", "source_audio_too_short",
                "Legacy source audio is %d frames (%.3fs) short." %
                (shortfall, shortfall / float(FPS)),
                action, solutions=alternatives,
                triggers=source_requirements,
                measurements=measurements)
        elif shortfall:
            measurements = _preflight_source_measurements(
                plan, available_frames, source_requirements)
            _preflight_issue(
                report, "warnings", "silent_source_will_pad",
                "Silent placeholder audio is %.3f seconds short and will be "
                "padded." % (shortfall / float(FPS)),
                "No action is required unless real source audio was intended.",
                solutions=(
                    "Replace the placeholder with a track at least %.3fs "
                    "long when real source audio is intended." %
                    measurements["required_seconds"],),
                triggers=source_requirements,
                measurements=measurements)
        source_hash = _audio_fingerprint(source_audio) if required else "none"
    else:
        source_hash = "none"
    prepared["compatibility"].update({
        "source_audio_hash": source_hash,
        "source_audio_silent_padding": bool(
            source_report.get("shortfall_frames") and source_audio is not None
            and _audio_is_silent(_validate_audio(
                source_audio, "Preflight legacy source audio")[0])),
    })
    prepared["plan_hash"] = _fingerprint(
        {"prepared_plan_hash": plan["plan_hash"],
         "source_audio_hash": source_hash}
        if plan["compatibility"].get("external_context_hash") else
        {"base_plan_hash": plan["plan_hash"],
         "source_audio_hash": source_hash})
    report["source"] = source_report
    return prepared, None


def _preflight_resume(
        plan: dict[str, Any], start: int, verify_history: bool,
        report: dict[str, Any], source_timeline: Any = None,
        source_audio: Any = None) -> dict[str, Any]:
    result: dict[str, Any] = {
        "requested_start": int(start), "verify_history": bool(verify_history),
        "eligible": True, "predecessors": [],
    }
    if int(start) <= 1:
        return result
    selected_shot = plan["shots"][int(start) - 1]
    selected_video_context = _shot_context_length(
        selected_shot, int(plan["compatibility"].get("context_length", 0)))
    selected_audio_context = _shot_audio_context_length(
        selected_shot,
        int(plan["compatibility"].get("audio_context_length", 0)),
        selected_video_context)
    result["selected_context"] = {
        "scene": int(start),
        "video_frames": int(selected_video_context),
        "audio_frames": int(selected_audio_context),
    }
    context_sources = _resume_context_predecessors(plan, int(start))
    consumed_predecessors = set(context_sources["scenes"])
    result["context_sources"] = context_sources
    result["context_predecessor"] = (
        max(consumed_predecessors) if consumed_predecessors else None)
    for index in range(1, int(start)):
        item: dict[str, Any] = {"scene": index, "ok": False}
        try:
            metadata_path = _artifact_paths(plan, index)["metadata"]
            item["metadata"] = metadata_path
            if not os.path.isfile(metadata_path):
                raise FileNotFoundError(
                    "Predecessor scene %d metadata is missing." % index)
            metadata = _read_json(metadata_path)
            saved_dependency = metadata.get("scene_dependency")
            dependency_diffs = []
            if (bool(verify_history) and index in consumed_predecessors
                    and isinstance(saved_dependency, dict)):
                current_source_dependency = (
                    _canonical_source_reference_dependency(
                        plan, index, source_timeline, source_audio))
                if current_source_dependency is None:
                    saved_compatibility = metadata.get("compatibility") or {}
                    if (str(saved_compatibility.get("source_audio_hash") or "") ==
                            str(plan["compatibility"].get(
                                "source_audio_hash") or "")):
                        current_source_dependency = saved_dependency.get(
                            "scopes", {}).get("scene_generation", {}).get(
                                "source_reference_window")
                current_dependency = _scene_dependency_record(
                    plan, index, current_source_dependency)
                dependency_diffs = _resume_dependency_diffs(
                    saved_dependency, current_dependency, index,
                    context_sources)
                accepted = (str(metadata.get("history_hash") or "") or None)
            else:
                # These clips remain part of final assembly, but the selected
                # sampler does not consume their settings or latent state.
                # Validate their recorded identity and files without comparing
                # them to edits in the current Plan.
                accepted = str(metadata.get("history_hash") or "") or None
            item["mismatches"] = dependency_diffs
            item["consumed_streams"] = list(
                _resume_predecessor_streams(context_sources, index))
            if dependency_diffs:
                raise ValueError(
                    "Predecessor scene %d dependency mismatch: %s" % (
                        index, _format_dependency_mismatches(dependency_diffs)))
            if accepted is None:
                raise ValueError(
                    "Predecessor scene %d does not match the current "
                    "generation history." % index)
            segment = metadata.get("segment")
            if not isinstance(segment, dict):
                raise ValueError(
                    "Predecessor scene %d has no segment record." % index)
            if str(segment.get("history_hash") or "") != accepted:
                raise ValueError(
                    "Predecessor scene %d has inconsistent history metadata."
                    % index)
            _verify_segment_artifacts(segment, index)
            item.update({"ok": True, "history_hash": accepted,
                         "revision": segment.get("revision")})
        except (OSError, TypeError, ValueError) as exc:
            result["eligible"] = False
            item["error"] = str(exc)
            shot = plan["shots"][index - 1]
            _preflight_issue(
                report, "errors", "resume_predecessor_invalid", str(exc),
                "Regenerate the reported predecessor scene.",
                solutions=(
                    "Restore its metadata and segment artifacts from the "
                    "correct Run Manager archive.",
                    "Disable verify_resume_history only when intentionally "
                    "reusing a predecessor that you have independently "
                    "verified."),
                triggers=(_preflight_scene_trigger(
                    shot, "resume_history", "invalid",
                    "saved checkpoint lineage"),),
                measurements={
                    "dependency_mismatch_count": len(
                        item.get("mismatches") or ()),
                    "consumed_streams": ",".join(
                        item.get("consumed_streams") or ()) or "assembly",
                    "selected_scene": int(start),
                    "selected_video_context_frames": int(
                        selected_video_context),
                    "selected_audio_context_frames": int(
                        selected_audio_context),
                }, scene=index, scene_id=str(shot["id"]))
        result["predecessors"].append(item)
    return result


def _preflight_validation_recovery(
        stage: str) -> tuple[str, str, tuple[str, ...]]:
    recoveries = {
        "plan": (
            "invalid_plan",
            "Reconnect a validated H3 Chain Plan.",
            ("Rebuild the Plan in Plan Studio if its saved JSON is malformed.",)),
        "scene_selection": (
            "invalid_scene_selection",
            "Choose a start clip and scene range inside the current Plan.",
            ("Clear scene_range to validate the complete Plan.",)),
        "source": (
            "invalid_source_input",
            "Correct the connected Source Timeline or legacy source_audio input.",
            ("Connect only one source route, not both.",
             "Relink or replace malformed source media in the Project Asset "
             "Manager.")),
        "scene_metadata": (
            "invalid_scene_metadata",
            "Open the reported scene in Plan Studio and correct its settings.",
            ("Rebuild the Plan if its normalized scene metadata was edited "
             "outside Plan Studio.",)),
        "references": (
            "invalid_reference_input",
            "Correct or reconnect the active reference registry.",
            ("Remove malformed @tags/#anchors and add them again through the "
             "Prompt Editor.",
             "Use only the Tagged or Scheduled route expected by Ref2VA.")),
        "generation": (
            "invalid_generation_fingerprint",
            "Reconnect the automatic generation fingerprint source.",
            ("Rebuild the Plan if its compatibility metadata was edited "
             "manually.",)),
        "chapter_resolution": (
            "incompatible_chapter_resolution",
            "Use zero video context at the chapter boundary, or match the chapter resolutions.",
            ("Keep native AV/latent continuation within a single resolution.",)),
        "runtime": (
            "runtime_compatibility_validation_failed",
            "Update ComfyUI and this node pack together, then restart.",
            ("Use non-masked continuation settings until runtime inspection "
             "passes.",)),
        "resume": (
            "resume_validation_failed",
            "Regenerate or restore the reported predecessor lineage.",
            ("Start from Scene 1 to build a fresh verified lineage.",)),
    }
    return recoveries.get(stage, (
        "preflight_internal_validation",
        "Correct the reported Plan or media input and run preflight again.",
        ("Restart ComfyUI and retry once; if it persists, include this full "
         "diagnostic in a bug report.",)))


def _preflight_chain(
        plan: Any, *, source_timeline: Any = None, source_audio: Any = None,
        start_clip: int = 1, scene_range: Any = "",
        verify_resume_history: bool = True, tagged_references: Any = None,
        reference_schedule: Any = None) -> tuple[dict[str, Any], dict[str, Any]]:
    report: dict[str, Any] = {
        "version": PREFLIGHT_VERSION, "ok": False, "status": "error",
        "errors": [], "warnings": [], "info": [], "scenes": [],
        "source": {}, "references": {}, "runtime": {}, "resume": {},
        "generation": {},
    }
    prepared = plan
    stage = "plan"
    try:
        if not isinstance(plan, dict) or not isinstance(plan.get("shots"), list):
            raise ValueError("Preflight requires a validated H3 Chain Plan.")
        stage = "scene_selection"
        start, end = _parse_scene_range(
            scene_range, len(plan["shots"]), start_clip)
        report["selection"] = {"start": start, "end": end}
        stage = "chapter_resolution"
        for scene in range(start, end + 1):
            _validate_scene_resolution_boundary(plan, scene)
        stage = "source"
        prepared, runtime_timeline = _preflight_bind_source(
            plan, report, source_timeline, source_audio)
        if not report.get("source"):
            # Timeline route returns before setting the shared report field.
            source = runtime_timeline
            report["source"] = {
                "route": "source_timeline",
                "required_frames": int(plan["total_delivered_frames"]),
                "required_seconds": int(plan["total_delivered_frames"]) / float(FPS),
                "extent_frames": int(source["extent"]["frame_count"]),
                "extent_seconds": float(source["extent"]["duration_seconds"]),
                "audio_kind": source["audio"]["kind"],
                "audio_frames": _source_timeline_available_audio_frames(source),
                "origin": dict(source["origin"]),
                "timeline_fingerprint": source["fingerprints"]["timeline"],
            }
        stage = "scene_metadata"
        available = int(report["source"].get(
            "audio_frames", report["source"].get("extent_frames", 0)))
        source_coverage = _preflight_source_coverage(
            prepared, available, _audio_source_requirements(prepared))
        last_complete = int((
            source_coverage.get("last_complete_scene") or {}).get("scene", 0))
        for shot in prepared["shots"]:
            context = int(shot["raw_frames"]) - int(shot["delivered_frames"])
            mode = str(shot.get(
                "continuation_mode",
                prepared["compatibility"].get("continuation_mode", "guide")))
            record = {
                "index": int(shot["index"]), "id": str(shot["id"]),
                "selected": start <= int(shot["index"]) <= end,
                "resolution": scene_resolution(prepared, int(shot["index"])),
                "raw_frames": int(shot["raw_frames"]),
                "delivered_frames": int(shot["delivered_frames"]),
                "overlap_trim_frames": context,
                "duration_seconds": int(shot["raw_frames"]) / float(FPS),
                "delivered_seconds": int(shot["delivered_frames"]) / float(FPS),
                "source_start_frame": max(
                    0, int(shot["generation_start_frame"])),
                "source_end_frame": max(
                    0, int(shot["generation_start_frame"]))
                    + int(shot["raw_frames"]),
                "transition": mode,
                "prompt_tags": sorted(set(_REFERENCE_ALIAS_RE.findall(
                    str(shot.get("prompt") or "")))),
                "semantic_anchors": _semantic_anchor_specs(
                    shot.get("prompt")),
                "references": [],
            }
            if (not any(issue["code"].startswith("source_")
                        for issue in report["errors"])):
                source_dependency = _canonical_source_reference_dependency(
                    prepared, int(shot["index"]), runtime_timeline,
                    source_audio)
                record["dependency"] = _scene_dependency_record(
                    prepared, int(shot["index"]), source_dependency)
            report["scenes"].append(record)
        report["source"]["last_complete_scene"] = last_complete
        report["source"]["first_affected_scene"] = (
            source_coverage.get("first_affected_scene") or {}).get("scene")

        stage = "references"
        if tagged_references is not None and reference_schedule is not None:
            _preflight_issue(
                report, "errors", "multiple_reference_routes",
                "Connect tagged_references or reference_schedule, not both.",
                "Keep the reference input used by the active Ref2VA node and "
                "disconnect the other route.",
                solutions=(
                    "Use tagged_references for prompt-activated @tags and "
                    "#semantic anchors.",
                    "Use reference_schedule only for the legacy scheduled "
                    "reference workflow."),
                triggers=(
                    {"scope": "Preflight", "setting": "tagged_references",
                     "value": "connected", "origin": "input socket"},
                    {"scope": "Preflight", "setting": "reference_schedule",
                     "value": "connected", "origin": "input socket"},
                ))
        references = (tagged_references if tagged_references is not None
                      else reference_schedule)
        route = ("tagged" if tagged_references is not None else
                 "scheduled" if reference_schedule is not None else "none")
        semantic_bundle = (
            _reference_semantic_anchor_bundle(tagged_references)
            if tagged_references is not None else None)
        report["references"] = {"route": route, "fingerprint": "",
                                "registered_tags": [],
                                "semantic_route": (
                                    "bundle" if semantic_bundle is not None
                                    else "legacy_tagged"
                                    if tagged_references is not None
                                    else "none"),
                                "registered_semantic_tags": []}
        if references is not None or semantic_bundle is not None:
            entries = (
                _tagged_reference_entries(references)
                if route == "tagged" else
                _reference_schedule_entries(references)
                if route == "scheduled" else [])
            registered = sorted({tag for entry in entries
                                 for tag in _reference_entry_tags(entry)})
            reference_fingerprint = str(
                (references or semantic_bundle or {}).get("fingerprint") or "")
            if route == "tagged" and references is not None:
                reference_fingerprint = str(
                    _combined_reference_registry(
                        references, semantic_bundle)["fingerprint"])
            report["references"].update({
                "fingerprint": reference_fingerprint,
                "registered_tags": registered,
            })
            semantic_entries = (
                _semantic_anchor_draft_entries(semantic_bundle)
                if semantic_bundle is not None
                else entries if route == "tagged" else [])
            report["references"]["registered_semantic_tags"] = sorted(
                str(entry["tag"]) for entry in semantic_entries)
            for scene_record, shot in zip(report["scenes"], prepared["shots"]):
                prompt_tags = set(scene_record["prompt_tags"])
                semantic_anchors = list(scene_record["semantic_anchors"])
                if route == "tagged":
                    # Native H3 capacity is exclusively driven by @tags.
                    # Dedicated or legacy #anchors are Qwen presentation data
                    # and never enter this active native list.
                    native_bindings = _active_reference_bindings(
                        references, int(shot["index"]), len(prepared["shots"]),
                        activation_tags=prompt_tags)
                    active = (
                        native_bindings["pictures"] +
                        native_bindings["videos"] +
                        native_bindings["audios"])
                elif route == "scheduled":
                    native_bindings = _active_reference_bindings(
                        references, int(shot["index"]), len(prepared["shots"]))
                    active = (
                        native_bindings["pictures"] +
                        native_bindings["videos"] +
                        native_bindings["audios"])
                    for anchor in semantic_anchors:
                        timestamp = anchor["timestamp_seconds"]
                        syntax = (
                            "#%s[%.3fs]" % (anchor["tag"], float(timestamp))
                            if timestamp is not None
                            else "#%s" % anchor["tag"])
                        _preflight_issue(
                            report, "errors", "semantic_anchor_requires_tagged",
                            "Scene %d uses %s, but semantic anchors "
                            "require the Tagged reference route." % (
                                int(shot["index"]), syntax),
                            "Use Tagged Picture Ref + Tagged Ref2VA, or remove "
                            "the #anchor from this scheduled workflow.",
                            solutions=(
                                "Replace the #anchor with an @tag only if a "
                                "native visual reference was intended.",),
                            triggers=(_preflight_scene_trigger(
                                shot, "prompt", syntax, "scene prompt",
                                tag=anchor["tag"]),),
                            scene=int(shot["index"]),
                            scene_id=str(shot["id"]), tag=anchor["tag"])
                    unresolved = sorted(prompt_tags - set(registered))
                    for tag in unresolved:
                        _preflight_issue(
                            report, "errors", "unresolved_reference_tag",
                            "Scene %d uses unresolved scheduled reference @%s."
                            % (int(shot["index"]), tag),
                            "Register that tag or remove it from the scene prompt.",
                            solutions=(
                                "Rename the prompt @tag to one of the "
                                "registered scheduled reference tags.",),
                            triggers=(_preflight_scene_trigger(
                                shot, "prompt_reference", "@%s" % tag,
                                "scene prompt", tag=tag),),
                            scene=int(shot["index"]),
                            scene_id=str(shot["id"]), tag=tag)
                else:
                    active = []
                    for tag in sorted(prompt_tags):
                        _preflight_issue(
                            report, "errors", "unresolved_reference_tag",
                            "Scene %d uses native reference @%s, but no native "
                            "Tagged registry is connected." % (
                                int(shot["index"]), tag),
                            "Connect Semantic Anchor Bundle's references "
                            "passthrough or remove the @tag.",
                            solutions=(
                                "Connect the active Tagged reference registry "
                                "directly to preflight.",
                                "Remove the @tag if it is only descriptive "
                                "text and not a visual reference."),
                            triggers=(_preflight_scene_trigger(
                                shot, "prompt_reference", "@%s" % tag,
                                "scene prompt", tag=tag),),
                            scene=int(shot["index"]),
                            scene_id=str(shot["id"]), tag=tag)
                if route != "scheduled":
                    entries_by_tag = {
                        tag: entry for entry in semantic_entries
                        for tag in _reference_entry_tags(entry)
                    }
                    for anchor in semantic_anchors:
                        tag = anchor["tag"]
                        entry = entries_by_tag.get(tag)
                        if entry is None:
                            _preflight_issue(
                                report, "errors", "unresolved_semantic_anchor",
                                "Scene %d uses unresolved semantic anchor #%s." %
                                (int(shot["index"]), tag),
                                "Register a Semantic Picture Anchor with that "
                                "tag or remove the semantic anchor.",
                                solutions=(
                                    "Rename the #anchor to a registered "
                                    "semantic-picture tag.",),
                                triggers=(_preflight_scene_trigger(
                                    shot, "prompt_semantic_anchor",
                                    "#%s" % tag, "scene prompt", tag=tag),),
                                scene=int(shot["index"]),
                                scene_id=str(shot["id"]), tag=tag)
                        elif entry.get("kind") not in (
                                "picture", "semantic_anchor"):
                            _preflight_issue(
                                report, "errors", "invalid_semantic_anchor_kind",
                                "Scene %d semantic anchor #%s resolves to %s, "
                                "not a semantic picture." % (
                                    int(shot["index"]), tag,
                                    str(entry.get("kind") or "unknown")),
                                "Use a Semantic Picture Anchor (or a legacy "
                                "Tagged Picture compatibility source).",
                                solutions=(
                                    "Change this prompt token to an @tag if "
                                    "the registered non-picture reference was "
                                    "intended.",
                                    "Register a semantic picture under a "
                                    "different tag and update the prompt."),
                                triggers=(_preflight_scene_trigger(
                                    shot, "prompt_semantic_anchor",
                                    "#%s" % tag, "scene prompt", tag=tag),),
                                scene=int(shot["index"]),
                                scene_id=str(shot["id"]), tag=tag,
                                resolved_kind=str(
                                    entry.get("kind") or "unknown"))
                        timestamp = anchor["timestamp_seconds"]
                        if (timestamp is not None and float(timestamp) > (
                                int(shot["raw_frames"]) / float(FPS))):
                            _preflight_issue(
                                report, "errors", "semantic_anchor_out_of_range",
                                "Scene %d semantic anchor #%s[%.3fs] exceeds "
                                "the %.3fs scene duration." % (
                                    int(shot["index"]), tag,
                                    float(timestamp),
                                    int(shot["raw_frames"]) / float(FPS)),
                                "Use a scene-local timestamp inside this scene.",
                                solutions=(
                                    "Lengthen the scene so it includes the "
                                    "requested anchor timestamp.",
                                    "Remove the timestamp to use an untimed "
                                    "semantic anchor."),
                                triggers=(_preflight_scene_trigger(
                                    shot, "prompt_semantic_anchor",
                                    "#%s[%.3fs]" % (tag, float(timestamp)),
                                    "scene prompt", tag=tag),),
                                measurements={
                                    "anchor_seconds": float(timestamp),
                                    "scene_duration_seconds": (
                                        int(shot["raw_frames"]) / float(FPS)),
                                },
                                scene=int(shot["index"]),
                                scene_id=str(shot["id"]), tag=tag)
                for entry in active:
                    detail = {"tag": str(entry.get("tag") or ""),
                              "kind": str(entry.get("kind") or ""),
                              "semantic_role": str(
                                  entry.get("semantic_role") or "")}
                    window = _preflight_reference_window(
                        entry, prepared, int(shot["index"]))
                    if window is not None:
                        detail["window"] = window
                        value = entry.get("value")
                        if _is_source_timeline(value):
                            capacity = int(value["extent"]["frame_count"])
                        elif _is_lazy_motion_descriptor(value):
                            capacity = int(value.get("frame_count", 0))
                            path = str(value.get("path") or "")
                            detail["available"] = bool(
                                path and os.path.isfile(path))
                        else:
                            capacity = int(getattr(value, "shape", (0,))[0])
                        detail["available_frames"] = capacity
                        if capacity and int(window["end_frame"]) > capacity:
                            _preflight_issue(
                                report, "errors", "reference_too_short",
                                "Reference @%s needs frames %d:%d for scene %d, "
                                "but has %d." % (
                                    detail["tag"], window["start_frame"],
                                    window["end_frame"], int(shot["index"]),
                                    capacity),
                                "Provide a longer reference or change its timeline mode.",
                                solutions=(
                                    "Reduce the scene duration or reference "
                                    "activation range.",
                                    "Use restart_each_scene when each scene "
                                    "should reuse the reference from frame 0.",
                                    "Remove @%s from this scene if the "
                                    "reference is not required." % detail["tag"],),
                                triggers=(_preflight_scene_trigger(
                                    shot, "prompt_reference",
                                    "@%s" % detail["tag"], "scene prompt",
                                    tag=detail["tag"]),),
                                measurements={
                                    "required_start_frame": int(
                                        window["start_frame"]),
                                    "required_end_frame": int(
                                        window["end_frame"]),
                                    "required_frame_count": int(
                                        window["frame_count"]),
                                    "available_frames": capacity,
                                    "timeline_mode": str(window["mode"]),
                                },
                                scene=int(shot["index"]),
                                scene_id=str(shot["id"]), tag=detail["tag"])
                    scene_record["references"].append(detail)
        elif any(item["prompt_tags"] or item["semantic_anchors"]
                 for item in report["scenes"]):
            unresolved_triggers = []
            for scene_record, shot in zip(
                    report["scenes"], prepared["shots"]):
                unresolved_triggers.extend(
                    _preflight_scene_trigger(
                        shot, "prompt_reference", "@%s" % tag,
                        "scene prompt", tag=tag)
                    for tag in scene_record["prompt_tags"])
                unresolved_triggers.extend(
                    _preflight_scene_trigger(
                        shot, "prompt_semantic_anchor", "#%s" % anchor["tag"],
                        "scene prompt", tag=anchor["tag"])
                    for anchor in scene_record["semantic_anchors"])
            _preflight_issue(
                report, "warnings", "reference_registry_not_connected",
                "Scene prompts contain @tags or #semantic anchors, but no "
                "reference registry is connected to preflight.",
                "Connect the active Tagged or Scheduled reference output to "
                "preflight for scene-window validation.",
                solutions=(
                    "Remove prompt tags that are not intended to resolve to "
                    "project references.",),
                triggers=unresolved_triggers)

        stage = "generation"
        fingerprint = str(
            prepared["compatibility"].get("generation_fingerprint") or "")
        report["generation"] = {
            "fingerprint": fingerprint,
            "covered": bool(fingerprint),
            "scope": "external model/sampler/reference graph",
        }
        if not fingerprint:
            _preflight_issue(
                report, "warnings", "generation_fingerprint_missing",
                "Model, sampler, CFG, scheduler, and reference graph are not "
                "covered by the Plan's generation fingerprint.",
                "Connect an automatic generation fingerprint before relying "
                "on strict resume verification.",
                solutions=(
                    "Disable strict resume verification only when knowingly "
                    "reusing checkpoints across generation-setting changes.",),
                triggers=({
                    "scope": "Plan", "setting": "generation_fingerprint",
                    "value": "missing", "origin": "generation graph",
                },))
        stage = "runtime"
        report["runtime"] = _preflight_runtime_compatibility(prepared, report)
        stage = "resume"
        report["resume"] = _preflight_resume(
            prepared, start, verify_resume_history, report,
            runtime_timeline, source_audio)
    except Exception as exc:
        code, action, alternatives = _preflight_validation_recovery(stage)
        _preflight_issue(
            report, "errors", code,
            "%s validation failed: %s" % (stage.replace("_", " "), exc),
            action, solutions=alternatives,
            triggers=({
                "scope": "Preflight", "setting": "validation_stage",
                "value": stage, "origin": "preflight pipeline",
            },), stage=stage, exception_type=type(exc).__name__)
    report["ok"] = not report["errors"]
    report["status"] = (
        "ready" if report["ok"] and not report["warnings"]
        else "warning" if report["ok"] else "error")
    report["summary"] = (
        "H3 preflight %s: %d error(s), %d warning(s), %d scene(s)." %
        (report["status"], len(report["errors"]), len(report["warnings"]),
         len(report["scenes"])))
    return prepared, report


def _preflight_failure_text(report: dict[str, Any]) -> str:
    lines = [str(report.get("summary") or "H3 preflight failed.")]
    for issue in report.get("errors") or ():
        line = "%s: %s" % (issue.get("code", "error"), issue.get("message", ""))
        lines.append(line)
        triggers = issue.get("triggers") or issue.get("requirements") or ()
        for trigger in triggers:
            if isinstance(trigger, dict):
                lines.append("  Trigger: %s" %
                             _format_preflight_trigger(trigger))
        context = []
        if not triggers and issue.get("scene") is not None:
            scene = "scene=%s" % issue["scene"]
            if issue.get("scene_id"):
                scene += ' "%s"' % issue["scene_id"]
            context.append(scene)
        elif not triggers and issue.get("scenes"):
            context.append(
                "scenes=%s" % ",".join(
                    str(value) for value in issue["scenes"]))
        if not triggers and issue.get("setting"):
            setting = "setting=%s" % issue["setting"]
            if issue.get("value") is not None:
                setting += "=%s" % issue["value"]
            context.append(setting)
        if not triggers and issue.get("origin"):
            context.append("origin=%s" % issue["origin"])
        if not triggers and issue.get("tag"):
            context.append("tag=%s" % issue["tag"])
        if context:
            lines.append("  Context: %s" % "; ".join(context))
        measurements = issue.get("measurements") or {}
        if isinstance(measurements, dict) and measurements:
            details = []
            for key, value in measurements.items():
                if value is None:
                    continue
                if (key in ("last_complete_scene", "first_affected_scene")
                        and isinstance(value, dict)):
                    rendered = _format_preflight_location(value)
                elif isinstance(value, float):
                    rendered = "%.3f" % value
                else:
                    rendered = str(value)
                details.append("%s=%s" % (key, rendered))
            if details:
                lines.append("  Details: %s" % "; ".join(details))
        solutions = issue.get("solutions") or (
            (issue.get("action"),) if issue.get("action") else ())
        for index, solution in enumerate(solutions):
            lines.append("  %s: %s" % (
                "Action" if index == 0 else "Alternative", solution))
    return "\n".join(lines)


def _plan_studio_preview_cleanup() -> None:
    now = time.monotonic()
    expired = [
        token for token, session in _PLAN_STUDIO_SOURCE_PREVIEWS.items()
        if now - float(session.get("created", 0.0)) >
        PLAN_STUDIO_PREVIEW_TTL_SECONDS
    ]
    for token in expired:
        _PLAN_STUDIO_SOURCE_PREVIEWS.pop(token, None)
    overflow = len(_PLAN_STUDIO_SOURCE_PREVIEWS) - (
        PLAN_STUDIO_PREVIEW_MAX_SESSIONS - 1)
    if overflow > 0:
        oldest = sorted(
            _PLAN_STUDIO_SOURCE_PREVIEWS,
            key=lambda item: float(
                _PLAN_STUDIO_SOURCE_PREVIEWS[item].get("created", 0.0)))
        for token in oldest[:overflow]:
            _PLAN_STUDIO_SOURCE_PREVIEWS.pop(token, None)


def _plan_studio_presentation_path(run_name: Any) -> str:
    normalized = _strict_run_name(run_name)
    return os.path.join(_run_dir({"run_name": normalized}), "plan_studio_presentation.json")


def _validated_plan_studio_preview_record(value: Any) -> dict[str, Any]:
    if not isinstance(value, dict):
        raise ValueError("Plan Studio source-preview record is invalid.")
    record = dict(value)
    record["video_path"] = _confined_media_path(
        record.get("video_path"), "Plan Studio source-preview video")
    if str(record.get("audio_path") or "").strip():
        record["audio_path"] = _confined_media_path(
            record.get("audio_path"), "Plan Studio source-preview audio")
    else:
        record["audio_path"] = ""
        record["has_audio"] = False
    return record


def _validated_plan_studio_source_audio_record(value: Any) -> dict[str, Any]:
    if not isinstance(value, dict):
        raise ValueError("Plan Studio source-audio record is invalid.")
    record = dict(value)
    record["audio_path"] = _confined_media_path(
        record.get("audio_path"), "Plan Studio Source Timeline audio")
    return record


def _save_plan_studio_presentation(
        payload: dict[str, Any], records: dict[str, dict[str, Any]],
        source_audio: dict[str, Any] | None,
        ownership_proof: Any = None) -> None:
    """Persist UI-only media discovery without changing the generation plan."""
    run_name = _strict_run_name(payload.get("run_name"))
    public = dict(payload)
    public["run_name"] = run_name
    public["token"] = ""
    safe_records = {
        str(key): _validated_plan_studio_preview_record(value)
        for key, value in records.items()
    }
    safe_source_audio = (
        _validated_plan_studio_source_audio_record(source_audio)
        if source_audio is not None else None)
    document = {
        "version": 1,
        "run_name": run_name,
        "updated_at": datetime.now(timezone.utc).isoformat(
            timespec="seconds").replace("+00:00", "Z"),
        "public": public,
        "records": safe_records,
        "source_audio": safe_source_audio,
    }
    with _project_write_commit_guard(
            run_name, ownership_proof,
            "update the Plan Studio presentation"):
        _atomic_json(_plan_studio_presentation_path(run_name), document)


def _restore_plan_studio_presentation(run_name: Any) -> dict[str, Any]:
    """Restore a saved presentation and issue a fresh in-memory media token."""
    normalized = _strict_run_name(run_name)
    path = _plan_studio_presentation_path(normalized)
    if not os.path.isfile(path):
        raise FileNotFoundError(
            "No saved Plan Studio track exists for run %s." % normalized)
    document = _read_json(path)
    if not isinstance(document, dict) or int(document.get("version", 0)) != 1:
        raise ValueError("Saved Plan Studio presentation is invalid.")
    if str(document.get("run_name") or "").strip() != normalized:
        raise ValueError("Saved Plan Studio presentation belongs to another run.")
    public = document.get("public")
    records = document.get("records")
    source_audio = document.get("source_audio")
    if not isinstance(public, dict) or not isinstance(records, dict):
        raise ValueError("Saved Plan Studio presentation is incomplete.")
    if source_audio is not None and not isinstance(source_audio, dict):
        raise ValueError("Saved Plan Studio source audio record is invalid.")
    clean_records = {}
    for key, value in records.items():
        try:
            clean_records[str(key)] = _validated_plan_studio_preview_record(
                value)
        except (OSError, TypeError, ValueError):
            _LOG.warning(
                "Ignored an unsafe saved Plan Studio source-preview record: %s",
                key)
    if source_audio is not None:
        try:
            source_audio = _validated_plan_studio_source_audio_record(
                source_audio)
        except (OSError, TypeError, ValueError):
            _LOG.warning("Ignored an unsafe saved Plan Studio source-audio record")
            source_audio = None
    token = ""
    if clean_records or source_audio is not None:
        token = secrets.token_urlsafe(24)
        _plan_studio_preview_cleanup()
        _PLAN_STUDIO_SOURCE_PREVIEWS[token] = {
            "created": time.monotonic(),
            "records": clean_records,
            "source_audio": dict(source_audio) if source_audio is not None else None,
        }
    payload = dict(public)
    payload.update({"version": 2, "run_name": normalized, "token": token})
    return payload


def _plan_studio_preview_media(
        value: Any, window: dict[str, Any]) -> dict[str, Any] | None:
    start = int(window["start_frame"])
    end = int(window["end_frame"])
    if _is_source_timeline(value):
        source = _validate_source_timeline(value, require_runtime=True)
        video = source.get("video")
        if video is None:
            return None
        audio = source["audio"]
        audio_kind = str(audio.get("kind") or "none")
        audio_path = ""
        audio_seek = 0.0
        if audio_kind in ("embedded", "external_path"):
            audio_path = _confined_media_path(
                audio.get("path"), "Plan Studio source-preview audio")
            audio_seek = (
                float(audio.get("timeline_offset_seconds", 0.0)) +
                start / float(FPS))
        media_fingerprint = str(source["fingerprints"]["timeline"])
    elif _is_lazy_motion_descriptor(value):
        video = value
        audio_kind = "embedded" if value.get("audio") is not None else "none"
        audio_path = (_confined_media_path(
            value.get("path"), "Plan Studio source-preview audio")
            if audio_kind == "embedded" else "")
        audio_seek = (
            float(value.get("skip_seconds", 0.0)) +
            start / float(FPS))
        media_fingerprint = str(value.get("file_sha256") or "")
        if not media_fingerprint:
            media_fingerprint = _file_sha256(_confined_media_path(
                value.get("path"), "Plan Studio source-preview video"))
    else:
        return None
    video_path = _confined_media_path(
        video.get("path"), "Plan Studio source-preview video")
    video_seek = (
        float(video.get("skip_seconds", 0.0)) +
        start / float(FPS))
    return {
        "video_path": video_path,
        "video_seek_seconds": video_seek,
        "audio_path": audio_path,
        "audio_seek_seconds": audio_seek,
        "audio_kind": audio_kind,
        "has_audio": bool(audio_path),
        "start_frame": start,
        "end_frame": end,
        "frame_count": end - start,
        "media_fingerprint": media_fingerprint,
    }


def _plan_studio_runtime_source_timeline(
        plan: dict[str, Any], source_timeline: Any = None
        ) -> dict[str, Any] | None:
    source = source_timeline
    if source is None and isinstance(plan.get("source_timeline"), dict):
        source = _source_timeline_from_recovery(plan["source_timeline"])
    if source is None:
        return None
    return _validate_source_timeline(source, require_runtime=True)


def _plan_studio_source_audio_media(
        plan: dict[str, Any], source_timeline: Any = None
        ) -> dict[str, Any] | None:
    source = _plan_studio_runtime_source_timeline(plan, source_timeline)
    if source is None:
        return None
    audio = source["audio"]
    if (source.get("audio_tracks") and audio["kind"] == "deferred_tensor"
            and audio.get("value") is not None):
        # Studio needs a seekable full-mix preview even before Loop Start
        # materializes the group. This is only a disposable preview cache,
        # never a replacement for the run's archived source tracks.
        preview_path = os.path.join(
            folder_paths.get_temp_directory(), "h3_audio_track_previews",
            "%s.wav" % _audio_fingerprint(audio["value"]))
        if not os.path.isfile(preview_path):
            _atomic_float_wav(audio["value"], preview_path)
        audio = {**audio, "kind": "external_path", "path": preview_path}
    if str(audio.get("kind") or "none") not in (
            "embedded", "external_path"):
        return None
    path = _confined_media_path(
        audio.get("path"), "Plan Studio Source Timeline audio")
    frame_count = int(plan.get("total_delivered_frames") or sum(
        int(shot.get("delivered_frames", 0))
        for shot in plan.get("shots") or ()))
    if frame_count < 1:
        return None
    available_frame_count = _source_timeline_available_audio_frames(source)
    return {
        "audio_path": path,
        "audio_seek_seconds": float(
            audio.get("timeline_offset_seconds", 0.0)),
        "audio_kind": str(audio["kind"]),
        "frame_count": frame_count,
        "duration_seconds": frame_count / float(FPS),
        "available_frame_count": available_frame_count,
        "available_duration_seconds": available_frame_count / float(FPS),
        "media_fingerprint": str(
            source["fingerprints"].get("audio")
            or source["fingerprints"]["timeline"]),
    }


def _register_plan_studio_source_previews(
        plan: dict[str, Any], report: dict[str, Any],
        tagged_references: Any = None,
        reference_schedule: Any = None,
        source_timeline: Any = None) -> dict[str, Any]:
    references = (tagged_references if tagged_references is not None
                  else reference_schedule)
    route = ("tagged" if tagged_references is not None else
             "scheduled" if reference_schedule is not None else "none")
    payload: dict[str, Any] = {
        "version": 2,
        "run_name": str(plan.get("run_name") or ""),
        **({"_branch_id": plan["_branch_id"]} if plan.get("_branch_id") else {}),
        "route": route,
        "token": "",
        "scenes": [],
        "source_audio": {
            "available": False,
            "timeline_available": False,
            "has_audio": False,
            "kind": "none",
        },
        "status": "No active path-backed motion reference is available.",
    }
    try:
        runtime_source_timeline = _plan_studio_runtime_source_timeline(
            plan, source_timeline)
        source_audio = _plan_studio_source_audio_media(
            plan, runtime_source_timeline)
    except (OSError, TypeError, ValueError) as exc:
        _LOG.warning(
            "Plan Studio could not register Source Timeline audio: %s", exc)
        source_audio = None
        runtime_source_timeline = None
    entries = (
        _tagged_reference_entries(references)
        if references is not None and route == "tagged"
        else _reference_schedule_entries(references)
        if references is not None and route == "scheduled"
        else ())
    motion_entries: dict[str, dict[str, Any]] = {}
    for entry in entries:
        if (str(entry.get("kind") or "") != "video" or
                str(entry.get("semantic_role") or "") != "motion"):
            continue
        for alias in _reference_entry_tags(entry):
            motion_entries[str(alias)] = entry
    token = secrets.token_urlsafe(24)
    records: dict[str, dict[str, Any]] = {}
    public_scenes = []
    shots = {int(shot["index"]): shot for shot in plan["shots"]}
    for scene in report.get("scenes") or ():
        scene_index = int(scene.get("index", 0))
        shot = shots.get(scene_index)
        if shot is None:
            continue
        public_refs = []
        for detail in scene.get("references") or ():
            if (str(detail.get("kind") or "") != "video" or
                    str(detail.get("semantic_role") or "") != "motion" or
                    not isinstance(detail.get("window"), dict)):
                continue
            tag = str(detail.get("tag") or "")
            entry = motion_entries.get(tag)
            if entry is None:
                continue
            try:
                media = _plan_studio_preview_media(
                    entry.get("value"), detail["window"])
            except (OSError, TypeError, ValueError) as exc:
                _LOG.warning(
                    "Plan Studio could not register @%s source preview: %s",
                    tag, exc)
                continue
            if media is None:
                continue
            slot = len(public_refs)
            record_key = "%d:%d" % (scene_index, slot)
            records[record_key] = media
            comparison_offset = max(
                0, int(media["frame_count"]) -
                int(shot["delivered_frames"]))
            public_refs.append({
                "slot": slot,
                "tag": tag,
                "start_frame": int(media["start_frame"]),
                "end_frame": int(media["end_frame"]),
                "frame_count": int(media["frame_count"]),
                "compare_offset_frames": comparison_offset,
                "has_audio": bool(media["has_audio"]),
                "timeline_mode": str(
                    detail["window"].get("mode") or ""),
            })
        if public_refs:
            public_scenes.append({
                "scene": scene_index,
                "scene_id": str(scene.get("id") or shot["id"]),
                "delivered_frames": int(shot["delivered_frames"]),
                "references": public_refs,
            })
    timeline_available = runtime_source_timeline is not None
    source_audio_kind = (
        str(runtime_source_timeline["audio"].get("kind") or "none")
        if timeline_available else "none")
    source_has_audio = source_audio_kind != "none"
    if not records and source_audio is None and not timeline_available:
        try:
            _save_plan_studio_presentation(
                payload, {}, None, plan.get("_project_ownership"))
        except OSError as exc:
            _LOG.warning("Plan Studio could not save its empty track: %s", exc)
        return payload
    if records or source_audio is not None:
        _plan_studio_preview_cleanup()
        _PLAN_STUDIO_SOURCE_PREVIEWS[token] = {
            "created": time.monotonic(),
            "records": records,
            "source_audio": source_audio,
        }
    else:
        token = ""
    source_audio_public = {
        "available": False,
        "timeline_available": timeline_available,
        "has_audio": source_has_audio,
        "kind": source_audio_kind,
    }
    if source_audio is not None:
        source_audio_public = {
            "available": True,
            "timeline_available": True,
            "has_audio": True,
            "kind": str(source_audio["audio_kind"]),
            "seek_seconds": float(source_audio["audio_seek_seconds"]),
            "frame_count": int(source_audio["frame_count"]),
            "duration_seconds": float(source_audio["duration_seconds"]),
            "available_frame_count": int(source_audio.get(
                "available_frame_count", source_audio["frame_count"])),
            "available_duration_seconds": float(source_audio.get(
                "available_duration_seconds", source_audio["duration_seconds"])),
            "points_per_second": PLAN_STUDIO_WAVEFORM_POINTS_PER_SECOND,
        }
    motion_count = len(public_scenes)
    status_parts = []
    if motion_count:
        status_parts.append(
            "%d scene source window(s) ready" % motion_count)
    if source_audio is not None:
        status_parts.append("Source Timeline audio ready")
    elif timeline_available and not source_has_audio:
        status_parts.append("Source Timeline connected without audio")
    elif timeline_available:
        status_parts.append("Source Timeline audio is not path-backed")
    payload.update({
        "token": token,
        "scenes": public_scenes,
        "source_audio": source_audio_public,
        "status": "; ".join(status_parts) + ".",
    })
    try:
        _save_plan_studio_presentation(
            payload, records, source_audio, plan.get("_project_ownership"))
    except OSError as exc:
        _LOG.warning("Plan Studio could not save its track: %s", exc)
    return payload


_PLAN_STUDIO_AUTHORING_FIELDS = (
    "plan_json", "run_name", "generation_fingerprint", "width", "height",
    "context_length", "encode_mode", "anchor_mode", "crop", "audio_mode",
    "audio_context_length", "default_duration_seconds", "default_steps",
    "base_seed", "segment_crf", "video_blend_frames", "continuation_mode",
)


def _plan_studio_preflight_input_types():
    return {
        "source_timeline": (SOURCE_TIMELINE_TYPE, {
            "tooltip": "Optional source media for the shared model-free preflight."}),
        "source_audio": ("AUDIO", {
            "tooltip": "Legacy source route; do not connect with Source Timeline."}),
        "start_clip": ("INT", {"default": 1, "min": 1,
            "max": MAX_SHOTS, "tooltip": "Resume scene to preflight."}),
        "scene_range": ("STRING", {"default": "",
            "tooltip": "Optional contiguous scene selection to preflight."}),
        "verify_resume_history": ("BOOLEAN", {
            "default": True,
            "tooltip": "When resuming after scene 1, compare each saved "
                       "predecessor actually consumed by the selected "
                       "scene with the active Plan. Audio-only carry ignores "
                       "the predecessor's unrelated visual-boundary recipe. "
                       "Disable only for an intentional advanced recovery "
                       "from known artifacts."}),
        "tagged_references": (TAGGED_REFERENCE_TYPE, {
            "tooltip": "Optional active prompt-driven reference registry. "
                       "In standalone Plan Studio it also supplies the "
                       "automatic incremental generation fingerprint, "
                       "including bundled semantic anchors."}),
        "reference_schedule": (REFERENCE_SCHEDULE_TYPE, {
            "tooltip": "Optional legacy scheduled reference registry."}),
    }


class MiniMaxH3ChainPlanStudio:
    @classmethod
    def INPUT_TYPES(cls):
        plan_inputs = MiniMaxH3ChainPlan.INPUT_TYPES()
        optional = {
            # Keep plan first and the established preflight entries in their
            # original order. Existing workflow input slots and widget values
            # therefore survive the required-to-optional migration.
            "plan": (PLAN_TYPE, {
                "tooltip": "Optional H3 Chain Plan. When connected, Plan "
                           "Studio edits and mirrors that Plan. When omitted, "
                           "the Studio builds and outputs its own complete "
                           "validated Plan from the Plan settings tab."}),
            **_plan_studio_preflight_input_types(),
        }
        for name in _PLAN_STUDIO_AUTHORING_FIELDS:
            optional[name] = plan_inputs["required"][name]
        fingerprint_type, fingerprint_options = optional[
            "generation_fingerprint"]
        fingerprint_options = dict(fingerprint_options)
        fingerprint_options["tooltip"] = (
            "Optional external generation contract for model, VAE, LoRA, "
            "CFG, sampler, or scheduler changes. In standalone mode the "
            "connected Tagged reference carrier is fingerprinted "
            "automatically and combined with this value; no separate "
            "reference-fingerprint STRING wire is needed.")
        optional["generation_fingerprint"] = (
            fingerprint_type, fingerprint_options)
        optional["chain_policy"] = plan_inputs["optional"]["chain_policy"]
        optional["project_assets"] = plan_inputs["optional"]["project_assets"]
        optional["alternate_take_json"] = ("STRING", {
            "default": "",
            "multiline": True,
            "tooltip": "Internal serialized Plan Studio alternate draft. "
                       "The frontend keeps this hidden and synchronized so "
                       "queueing cannot race the editorial sidecar save.",
        })
        optional["working_branch_id"] = ("STRING", {
            "default": "main", "tooltip": "Working branch selected in Plan Studio. Queued jobs keep this branch; changing the project default does not redirect them."})
        return {
            "required": {},
            "optional": optional,
        }

    RETURN_TYPES = (
        PLAN_TYPE, PREFLIGHT_TYPE, "BOOLEAN", "STRING", "STRING",
        "STRING", "INT", "INT", "INT", "INT",
    )
    RETURN_NAMES = (
        "plan", "preflight", "ready", "status", "report_json",
        "plan_summary", "clip_count", "width", "height",
        "video_blend_frames",
    )
    OUTPUT_TOOLTIPS = (
        "The connected Plan, or the complete validated standalone Plan "
        "authored by Studio. When an alternate draft is armed, this output "
        "is a temporary one-scene execution Plan; it never mutates the "
        "canonical generation Plan.",
        "Structured model-free preflight report.",
        "True when no blocking preflight error remains.",
        "Concise error/warning count.",
        "JSON serialization of the structured report.",
        "The same normalized timing and compatibility summary as H3 Chain Plan.",
        "Number of scenes in the authored Plan.",
        "Validated generation width; connect to stock H3 conditioning.",
        "Validated generation height; connect to stock H3 conditioning.",
        "Legacy Plan-wide blend default; Current Shot state remains preferred.",
    )
    FUNCTION = "passthrough"
    CATEGORY = "conditioning/minimax/context_loop"
    DESCRIPTION = ("Dual-mode timeline-oriented H3 Plan authoring studio with "
                   "scene navigation, prompt revisions, saved-segment status, "
                   "source-audio waveform, and synchronized preview playback. "
                   "It mirrors an optional connected Plan or works standalone.")

    @classmethod
    def IS_CHANGED(cls, plan=None, plan_json="", **_kwargs):
        run = (plan or {}).get("run_name") or (_kwargs.get("project_assets") or {}).get("project") or _kwargs.get("run_name", "")
        selected = (plan.get("_branch_id", "main") if plan is not None
                    else _kwargs.get("working_branch_id", "main"))
        if not _kwargs.get("_branch_fingerprint_scoped"):
            with branch_scope(run, selected):
                return cls.IS_CHANGED(plan=plan, plan_json=plan_json,
                    **dict(_kwargs, _branch_fingerprint_scoped=True, working_branch_id=selected))
        queued_alternate = str(_kwargs.get("alternate_take_json") or "")
        if plan is not None:
            run_name = str(plan.get("run_name") or "")
            draft = _load_run_editorial(run_name).get("alternate_draft")
            return _fingerprint({
                "plan_hash": str(plan.get("plan_hash") or ""),
                "working_branch_id": _kwargs.get("working_branch_id", "main"),
                "alternate_draft": draft,
                "queued_alternate": queued_alternate,
            })
        run_name = str(_kwargs.get("run_name") or "")
        plan_change = MiniMaxH3ChainPlan.IS_CHANGED(plan_json)
        if isinstance(plan_change, float) and math.isnan(plan_change):
            return plan_change
        return _fingerprint({
            "plan": plan_change,
            "working_branch_id": _kwargs.get("working_branch_id", "main"),
            "alternate_draft": _load_run_editorial(
                run_name).get("alternate_draft"),
            "queued_alternate": queued_alternate,
        })

    def passthrough(self, plan=None, source_timeline=None, source_audio=None,
                    start_clip=1, scene_range="", verify_resume_history=True,
                    tagged_references=None, reference_schedule=None,
                    plan_json='{"shots":[{"id":"intro","prompt":"Describe the opening shot."}]}',
                    run_name="h3_chain", generation_fingerprint="",
                    width=960, height=544, context_length=22,
                    encode_mode="video", anchor_mode="head", crop="disabled",
                    audio_mode="generated_audio", audio_context_length=22,
                    default_duration_seconds=15.0, default_steps=20,
                    base_seed=0, segment_crf=18, video_blend_frames=0,
                    continuation_mode="guide", chain_policy=None,
                    project_assets=None, alternate_take_json=None,
                    working_branch_id="main"):
        if plan is not None:
            working_branch_id = plan.get("_branch_id", "main")
        if project_assets is not None:
            project = _validate_project_assets(project_assets)
            if tagged_references is None:
                tagged_references = project["references"]
            if source_timeline is None:
                source_timeline = project.get("source_timeline")
        if plan is None:
            if project_assets is None:
                generation_fingerprint = _plan_studio_generation_fingerprint(
                    generation_fingerprint, tagged_references)
            plan = MiniMaxH3ChainPlan().build(
                plan_json, run_name, generation_fingerprint, width, height,
                context_length, encode_mode, anchor_mode, crop, audio_mode,
                audio_context_length, default_duration_seconds, default_steps,
                base_seed, segment_crf, video_blend_frames,
                continuation_mode, chain_policy=chain_policy,
                project_assets=project_assets,
            )[0]
        selected_branch = _working_branch_id(working_branch_id)
        WorkingBranches(_output_root(), plan["run_name"]).load(selected_branch)
        if plan.get("_branch_id", "main") != selected_branch:
            plan = dict(plan)
            if selected_branch != "main":
                plan["_branch_id"] = selected_branch
            else:
                plan.pop("_branch_id", None)
        return self._branch_passthrough(
            plan, source_timeline, source_audio, start_clip, scene_range,
            verify_resume_history, tagged_references, reference_schedule,
            alternate_take_json)

    def _branch_passthrough(self, plan, source_timeline, source_audio,
                           start_clip, scene_range, verify_resume_history,
                           tagged_references, reference_schedule, alternate_take_json):
        # Explicit scope here because standalone Studio creates the Plan itself.
        with branch_scope(plan["run_name"], plan.get("_branch_id", "main")):
            return self._present_branch(plan, source_timeline, source_audio,
                start_clip, scene_range, verify_resume_history,
                tagged_references, reference_schedule, alternate_take_json)

    def _present_branch(self, plan, source_timeline, source_audio,
                        start_clip, scene_range, verify_resume_history,
                        tagged_references, reference_schedule, alternate_take_json):
        editorial = _load_run_editorial(plan.get("run_name"))
        if alternate_take_json is None:
            editorial = dict(editorial)
            editorial["alternate_draft"] = None
        queued_alternate_text = str(alternate_take_json or "").strip()
        if queued_alternate_text:
            try:
                queued_alternate = json.loads(queued_alternate_text)
            except json.JSONDecodeError as exc:
                raise ValueError(
                    "Plan Studio alternate draft is not valid JSON.") from exc
            editorial = _merge_queued_alternate_draft(
                editorial, queued_alternate)
            editorial = _normalize_run_editorial(
                editorial, plan.get("run_name"))
        plan = _alternate_take_plan(plan, editorial)
        _require_plan_write(plan, "update the Plan Studio presentation")
        alternate = _alternate_take_descriptor(plan)
        if alternate is not None:
            start_clip = int(alternate["scene"])
            scene_range = str(start_clip)
        prepared, report = _preflight_chain(
            plan, source_timeline=source_timeline, source_audio=source_audio,
            start_clip=start_clip, scene_range=scene_range,
            verify_resume_history=verify_resume_history,
            tagged_references=tagged_references,
            reference_schedule=reference_schedule)
        try:
            source_previews = _register_plan_studio_source_previews(
                prepared, report, tagged_references, reference_schedule,
                source_timeline)
        except Exception as exc:
            _LOG.warning("Plan Studio source-preview registration failed: %s", exc)
            source_previews = {
                "version": 2,
                "run_name": str(plan.get("run_name") or ""),
                "route": "none",
                "token": "",
                "scenes": [],
                "source_audio": {
                    "available": False,
                    "timeline_available": False,
                    "has_audio": False,
                    "kind": "none",
                },
                "status": "Source preview registration failed: %s" % exc,
            }
        result = (
            plan, report, bool(report["ok"]), report["summary"],
            json.dumps(report, ensure_ascii=False, sort_keys=True),
            plan["summary"], len(plan["shots"]),
            int(plan["compatibility"]["width"]),
            int(plan["compatibility"]["height"]),
            int(plan["compatibility"]["video_blend_frames"]),
        )
        return {
            "ui": {"h3_plan_studio_source_timeline": [source_previews]},
            "result": result,
        }


class MiniMaxH3ChainPreflight:
    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {
                "plan": (PLAN_TYPE, {
                    "tooltip": "Connect the validated H3 Chain Plan to inspect."}),
            },
            "optional": _plan_studio_preflight_input_types(),
        }

    RETURN_TYPES = (PLAN_TYPE, PREFLIGHT_TYPE, "BOOLEAN", "STRING", "STRING")
    RETURN_NAMES = ("plan", "preflight", "ready", "status", "report_json")
    OUTPUT_TOOLTIPS = MiniMaxH3ChainPlanStudio.OUTPUT_TOOLTIPS[:5]
    FUNCTION = "check"
    CATEGORY = "conditioning/minimax/context_loop"
    DESCRIPTION = ("Model-free validation of Plan timing, Source Timeline, "
                   "references, runtime compatibility, and resume artifacts.")

    def check(self, plan, **kwargs):
        return MiniMaxH3ChainPlanStudio().passthrough(plan=plan, **kwargs)


def _validate_project_assets(value: Any) -> dict[str, Any]:
    if (not isinstance(value, dict)
            or value.get("format") != PROJECT_ASSET_FORMAT
            or int(value.get("version", -1)) != 1
            or not isinstance(value.get("project"), str)
            or not isinstance(value.get("catalog"), dict)
            or not isinstance(value.get("references"), dict)):
        raise ValueError(
            "Project assets must come from MiniMax H3 Project Asset Manager.")
    _tagged_reference_entries(value["references"])
    if value.get("source_timeline") is not None:
        _validate_source_timeline(value["source_timeline"])
    return value


def _project_assets_generation_fingerprint(
        generation_fingerprint: Any, project_assets: Any) -> str:
    project = _validate_project_assets(project_assets)
    return _plan_studio_generation_fingerprint(
        generation_fingerprint, project["references"])


def _project_asset_reference_templates(references: Any) -> list[dict[str, Any]]:
    """Extract only reference schema; deliberately ignore all media values."""
    templates = []
    for entry in _tagged_reference_entries(references):
        source_kind = str(entry.get("kind") or "")
        if source_kind == "picture":
            kind, role = "image", "picture"
        elif source_kind == "video":
            kind = "video"
            role = ("motion" if entry.get("semantic_role") == "motion"
                    else "video")
        elif source_kind == "audio":
            kind, role = "audio", "audio_reference"
        else:
            continue
        options = {}
        if kind == "video":
            options.update({
                "timeline_mode": str(
                    entry.get("timeline_mode") or "restart_each_scene"),
                "audio_tag": str(entry.get("audio_tag") or ""),
                "use_embedded_audio": entry.get("audio") is not None,
            })
            if role == "motion":
                options.update({
                    "target_subject": str(
                        entry.get("motion_target") or "<Subject 1>"),
                    "motion_description": str(
                        entry.get("motion_description") or
                        "the supplied pose sequence, action, and motion timing"),
                    "reference_short_edge": str(
                        entry.get("motion_short_edge") or "384"),
                })
        elif kind == "audio":
            options.update({
                "timeline_mode": str(
                    entry.get("timeline_mode") or "standalone"),
                "align_audio_reference": bool(
                    entry.get("align_audio_reference", False)),
            })
        templates.append({
            "kind": kind,
            "role": role,
            "tag": str(entry.get("tag") or ""),
            "content_hash": str(entry.get("content_hash") or ""),
            "options": options,
        })
    bundle = _reference_semantic_anchor_bundle(references)
    if bundle is not None:
        for entry in _semantic_anchor_draft_entries(bundle):
            templates.append({
                "kind": "image",
                "role": "semantic_anchor",
                "tag": str(entry.get("tag") or ""),
                "content_hash": str(entry.get("content_hash") or ""),
                "options": {},
            })
    return templates


def _project_asset_pending_operation(value: Any) -> dict[str, Any] | None:
    text = str(value or "").strip()
    if not text:
        return None
    try:
        operation = json.loads(text)
    except json.JSONDecodeError as exc:
        raise ValueError("Project asset operation is not valid JSON.") from exc
    if not isinstance(operation, dict):
        raise ValueError("Project asset operation must be a JSON object.")
    if str(operation.get("mode") or "").strip().lower() != "model":
        raise ValueError("Project asset operation mode must be model.")
    if not str(operation.get("asset_id") or ""):
        raise ValueError("Project asset operation is missing its source asset.")
    if not isinstance(operation.get("crop"), dict):
        raise ValueError("Project asset operation is missing its crop rectangle.")
    if not isinstance(operation.get("target"), dict):
        raise ValueError("Project asset operation is missing its target size.")
    return operation


def _project_asset_model_upscale(image: Any, upscale_model: Any) -> Any:
    """Run the same tiled UPSCALE_MODEL contract as ComfyUI core."""
    if torch is None or np is None or Image is None:
        raise RuntimeError(
            "Torch, NumPy, and Pillow are required for model-upscaled assets.")
    try:
        import comfy.model_management as model_management
        import comfy.utils as comfy_utils
    except ImportError as exc:
        raise RuntimeError(
            "ComfyUI model management is required for UPSCALE_MODEL assets.") from exc
    rgb = image.convert("RGB")
    pixels = np.array(rgb, dtype=np.float32, copy=True) / 255.0
    tensor = torch.from_numpy(pixels).unsqueeze(0)
    device = upscale_model.patcher.load_device
    memory_required = (
        (512 * 512 * 3) * tensor.element_size()
        * max(float(upscale_model.scale), 1.0) * 384.0)
    memory_required += tensor.nelement() * tensor.element_size()
    model_management.load_models_gpu(
        [upscale_model.patcher], memory_required=memory_required,
        force_full_load=True)
    input_image = tensor.movedim(-1, -3).to(device)
    tile = 512
    overlap = 32
    output_device = model_management.intermediate_device()
    while True:
        try:
            steps = (
                input_image.shape[0]
                * comfy_utils.get_tiled_scale_steps(
                    input_image.shape[3], input_image.shape[2],
                    tile_x=tile, tile_y=tile, overlap=overlap))
            progress = comfy_utils.ProgressBar(steps)
            output = comfy_utils.tiled_scale(
                input_image, lambda block: upscale_model(block.float()),
                tile_x=tile, tile_y=tile, overlap=overlap,
                upscale_amount=upscale_model.scale, pbar=progress,
                output_device=output_device)
            break
        except Exception as exc:
            model_management.raise_non_oom(exc)
            tile //= 2
            if tile < 128:
                raise
    output = torch.clamp(output.movedim(-3, -1), 0, 1)
    array = output[0].detach().to("cpu", torch.float32).numpy()
    return Image.fromarray(np.rint(array * 255.0).astype(np.uint8))


def _execute_project_asset_model_operation(
        store: ProjectAssetStore, run_name: str, operation: dict[str, Any],
        upscale_model: Any, ownership_proof: Any = None) -> dict[str, Any]:
    run_name = _strict_run_name(run_name)
    operation_project = str(operation.get("project") or "").strip()
    if operation_project and operation_project != run_name:
        raise ValueError(
            "Pending project asset operation belongs to another Run name.")
    existing = store.operation_asset(
        run_name, operation.get("operation_id", ""))
    if existing is not None:
        return existing
    parent, cropped, geometry = store.prepare_image_crop(
        run_name, operation.get("asset_id"), operation.get("crop"),
        operation.get("target"))
    alpha = None
    if "A" in cropped.getbands() or "transparency" in cropped.info:
        alpha = cropped.convert("RGBA").getchannel("A")
    rendered = _project_asset_model_upscale(cropped, upscale_model)
    target_size = (geometry["target_width"], geometry["target_height"])
    if rendered.size != target_size:
        rendered = rendered.resize(
            target_size, resample=Image.Resampling.LANCZOS)
    if alpha is not None:
        alpha = alpha.resize(
            target_size, resample=Image.Resampling.LANCZOS)
        rendered = rendered.convert("RGBA")
        rendered.putalpha(alpha)
    temporary = store.upload_path(
        run_name, "%s_model_variant.png" % parent.get("tag", "asset"))
    try:
        rendered.save(temporary, format="PNG")
        # Model execution can outlive a browser ownership takeover. Recheck
        # the fencing epoch immediately before publishing the derived asset;
        # a stale workflow may finish compute but cannot alter the catalog.
        with _project_write_commit_guard(
                run_name, ownership_proof,
                "publish an upscaled image variant"):
            return store.register_derived_image(
                run_name, operation.get("asset_id"), temporary,
                tag=operation.get("tag", ""),
                folder_id=(operation.get("folder_id")
                           if "folder_id" in operation else None),
                operation_id=operation.get("operation_id", ""),
                transform={
                    "kind": "model_upscale_crop",
                    "crop": {key: geometry[key]
                             for key in ("x", "y", "width", "height")},
                    "target": {
                        "width": geometry["target_width"],
                        "height": geometry["target_height"],
                    },
                    "source": {
                        "width": geometry["source_width"],
                        "height": geometry["source_height"],
                    },
                    "model_scale": float(
                        getattr(upscale_model, "scale", 1.0)),
                })
    finally:
        _safe_unlink(temporary)


class MiniMaxH3ProjectAssetManager:
    """Project-owned, path-backed references with one compact workflow node."""

    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {
                "run_name": ("STRING", {
                    "default": "",
                    "tooltip": "Authoritative H3 chain Run name. When "
                               "project_assets is connected to Plan, this "
                               "value automatically overrides and synchronizes "
                               "Plan's run_name; enter it here only. Media is "
                               "copied below "
                               "input/h3_projects/<run_name> and mirrored in "
                               "output/h3_chains/<run_name>/project_assets."}),
                "catalog_json": ("STRING", {
                    "default": "", "multiline": False,
                    "dynamicPrompts": False,
                    "tooltip": "Compact catalog metadata maintained by the "
                               "carousel. Media bytes and tensors are never "
                               "serialized into the workflow."}),
                "semantic_anchor_size": (
                    list(SEMANTIC_ANCHOR_BUNDLE_SIZES), {
                    "default": "512",
                    "tooltip": "Qwen presentation size for project assets "
                               "assigned the Semantic anchor role. Select "
                               "inherit to use the setting from the downstream "
                               "Tagged Scene node. Explicit values "
                               "override it for every semantic asset in this "
                               "Carousel."}),
                "semantic_anchor_mode": (
                    list(SEMANTIC_ANCHOR_BUNDLE_MODES), {
                    "default": "timestamped_video",
                    "tooltip": "Presentation mode for project semantic "
                               "anchors. Select inherit to use the setting "
                               "from the downstream Tagged Scene node. Bare "
                               "#tag is untimed; [timestamp] adds explicit "
                               "placement."}),
                "operation_json": ("STRING", {
                    "default": "", "multiline": False,
                    "dynamicPrompts": False,
                    "tooltip": "Internal one-shot image operation maintained "
                               "by the Carousel. It remains blank during normal "
                               "H3 generation."}),
            },
            "optional": {
                "ownership_json": ("STRING", {
                    "default": "", "multiline": False,
                    "dynamicPrompts": False,
                    "tooltip": "Ephemeral workflow ownership proof. The "
                               "Carousel maintains it only in this browser "
                               "session and "
                               "it is deliberately excluded from saved "
                               "workflow and recovery metadata."}),
                "tagged_references": (TAGGED_REFERENCE_TYPE, {
                    "tooltip": "Optional migration/template input. The "
                               "carousel reads tag, media kind, role, and "
                               "reference options into Unassigned cards but "
                               "does not copy, encode, or serialize the media. "
                               "Bind each card explicitly from ComfyUI input, "
                               "upload, another project, or backup."}),
                "upscale_model": ("UPSCALE_MODEL", {
                    "lazy": True,
                    "tooltip": "Optional core upscale model for creating an "
                               "edited image variant. It is evaluated only when "
                               "you press Model upscale in the asset editor; "
                               "normal H3 generation never loads it."}),
            },
        }

    RETURN_TYPES = (
        PROJECT_ASSETS_TYPE, TAGGED_REFERENCE_TYPE, "STRING",
        SOURCE_TIMELINE_TYPE, "STRING")
    RETURN_NAMES = (
        "project_assets", "references", "reference_fingerprint",
        "source_timeline", "status")
    OUTPUT_TOOLTIPS = (
        "Compact project catalog for Plan/Plan Studio synchronization.",
        "Native tagged references plus separate semantic-anchor metadata.",
        "Order-neutral incremental reference lineage for Plan compatibility.",
        "Optional path-backed Source Timeline for specialized direct uses. "
        "Plan already absorbs this automatically through project_assets.",
        "Run name, enabled reference count, source-track state, and revision.",
    )
    FUNCTION = "build"
    OUTPUT_NODE = True
    CATEGORY = "conditioning/minimax/context_loop/project"
    DESCRIPTION = (
        "Large project asset carousel for pictures, semantic anchors, video, "
        "motion, audio references, and one source track. Upload or import "
        "media in the node; files remain ordinary ComfyUI input assets, a "
        "recovery copy is kept with the H3 chain, and only prompt-active "
        "references are decoded during sampling.")

    @classmethod
    def IS_CHANGED(cls, run_name, catalog_json="", operation_json="",
                   ownership_json="", **_kwargs):
        try:
            catalog = ProjectAssetStore(
                _input_root(), _output_root()).load(run_name)
            return "%s:%s:%s" % (
                str(catalog.get("revision") or ""),
                hashlib.sha256(str(operation_json or "").encode(
                    "utf-8")).hexdigest(),
                hashlib.sha256(str(ownership_json or "").encode(
                    "utf-8")).hexdigest())
        except Exception:
            return "%s:%s:%s" % (
                str(catalog_json or ""), operation_json or "",
                ownership_json or "")

    def check_lazy_status(
            self, run_name, catalog_json="",
            semantic_anchor_size="512",
            semantic_anchor_mode="timestamped_video",
            tagged_references=None, operation_json="",
            ownership_json="",
            upscale_model=_LAZY_INPUT_MISSING,
            tagged_scene_options=None):
        del catalog_json, semantic_anchor_size
        del semantic_anchor_mode, tagged_references
        del ownership_json, tagged_scene_options
        operation = _project_asset_pending_operation(operation_json)
        if operation is not None:
            try:
                if ProjectAssetStore(
                        _input_root(), _output_root()).operation_asset(
                            run_name, operation.get("operation_id", "")) is not None:
                    return []
            except (OSError, TypeError, ValueError):
                pass
        if operation is not None and upscale_model is None:
            return ["upscale_model"]
        return []

    def build(
            self, run_name, catalog_json="",
            semantic_anchor_size="512",
            semantic_anchor_mode="timestamped_video",
            tagged_references=None, operation_json="",
            ownership_json="",
            upscale_model=_LAZY_INPUT_MISSING,
            tagged_scene_options=None):
        del tagged_scene_options  # Tolerate prompts saved during 0.6 preview.
        del catalog_json  # Disk catalog is authoritative; widget is UI state.
        # Carousel is an OUTPUT_NODE so it can run asset-only upscale jobs.
        # Its ordinary catalog build must remain readable when another
        # workflow owns the Run; downstream write nodes receive no proof and
        # enforce the lock themselves. Only actual Carousel mutations below
        # require a current fencing proof.
        ownership = None
        can_write = True
        try:
            ownership = _require_project_write(
                run_name, ownership_json, "change project assets")
        except ProjectOwnershipError:
            can_write = False
        store = ProjectAssetStore(_input_root(), _output_root())
        operation = _project_asset_pending_operation(operation_json)
        completed_operation = ""
        if operation is not None:
            result = store.operation_asset(
                run_name, operation.get("operation_id", ""))
            if result is None and not can_write:
                _require_project_write(
                    run_name, ownership_json,
                    "create an upscaled image variant")
            if (result is None and
                    (upscale_model is _LAZY_INPUT_MISSING
                     or upscale_model is None)):
                raise ValueError(
                    "Connect a core UPSCALE_MODEL before using Model upscale.")
            if result is None:
                result = _execute_project_asset_model_operation(
                    store, run_name, operation, upscale_model,
                    ownership_json)
            completed_operation = str(
                (result.get("asset") or {}).get("id") or "")
        if tagged_references is not None and can_write:
            with _project_write_commit_guard(
                    run_name, ownership_json,
                    "synchronize project reference slots"):
                store.sync_reference_slots(
                    run_name,
                    _project_asset_reference_templates(tagged_references))
        catalog = store.public_catalog(run_name)
        references = _make_tagged_references([])
        semantic_entries = []
        enabled = [
            entry for entry in catalog["assets"]
            if bool(entry.get("enabled", True))]
        tags = [str(entry.get("tag") or "") for entry in enabled]
        if len(tags) != len(set(tags)):
            raise ValueError(
                "Every enabled project asset must have a unique tag.")
        source_entries = [
            entry for entry in enabled if entry.get("role") == "source_track"]
        if len(source_entries) > 1:
            raise ValueError(
                "Project Asset Manager permits only one enabled Source track.")

        native_count = 0
        for entry in enabled:
            role = str(entry.get("role") or "")
            if role == "source_track":
                continue
            asset, path = store.asset(run_name, entry.get("id"))
            content_hash = str(asset.get("sha256") or "")
            options = asset.get("options")
            options = options if isinstance(options, dict) else {}
            if role == "semantic_anchor":
                semantic_entries.append({
                    "kind": "semantic_anchor",
                    "tag": _normalize_reference_tag(
                        asset.get("tag"), "Project semantic anchor tag"),
                    "activation": "prompt",
                    "value": _project_asset_descriptor(asset, path),
                    "content_hash": content_hash,
                })
                continue
            if role == "picture":
                references = _append_tagged_reference(
                    references, kind="picture", tag=asset.get("tag"),
                    value=_project_asset_descriptor(asset, path),
                    content_hash=content_hash)
            elif role in ("video", "motion"):
                use_audio = bool(options.get(
                    "use_embedded_audio",
                    bool((asset.get("metadata") or {}).get("has_audio"))))
                short_edge = str(options.get(
                    "reference_short_edge", "384" if role == "motion"
                    else "source"))
                video = _project_asset_video_descriptor(
                    asset, path, embedded_audio=use_audio,
                    short_edge=short_edge)
                audio_marker = video if use_audio else None
                references = _append_tagged_reference(
                    references, kind="video", tag=asset.get("tag"),
                    value=video, content_hash=content_hash,
                    audio=audio_marker,
                    audio_tag=str(options.get("audio_tag") or ""),
                    audio_hash=content_hash if use_audio else "",
                    timeline_mode=str(options.get(
                        "timeline_mode") or "restart_each_scene"),
                    paired_audio_policy=("embedded" if use_audio else "off"))
                if role == "motion":
                    target, description, short_edge = _motion_reference_fields(
                        options.get("target_subject") or "<Subject 1>",
                        options.get("motion_description") or
                        "the supplied pose sequence, action, and motion timing",
                        short_edge)
                    references = _decorate_motion_reference(
                        references, target, description, short_edge)
            elif role == "audio_reference":
                timeline_mode = str(
                    options.get("timeline_mode") or "standalone")
                references = _append_tagged_reference(
                    references, kind="audio", tag=asset.get("tag"),
                    value=_project_asset_descriptor(asset, path),
                    content_hash=content_hash,
                    timeline_mode=timeline_mode,
                    align_audio_reference=(
                        timeline_mode == "source_timeline" and bool(
                            options.get("align_audio_reference", False))))
            else:
                raise ValueError("Unsupported project asset role %r." % role)
            native_count += 1

        if semantic_entries:
            references = dict(references)
            references["semantic_anchors"] = _make_semantic_anchor_bundle(
                semantic_entries, semantic_anchor_size,
                semantic_anchor_mode)
        combined = _combined_reference_registry(references)
        fingerprint = _reference_fingerprint_output(combined)

        source_timeline = None
        if source_entries:
            source, path = store.asset(run_name, source_entries[0]["id"])
            if source.get("kind") == "video":
                source_timeline = _make_source_timeline(
                    video_path=path, embedded_audio="auto",
                    source_route="H3 Project Asset Manager")
            elif source.get("kind") == "audio":
                bindings = (source.get("options") or {}).get("audio_tracks")
                if bindings is None:
                    source_timeline = _make_source_timeline(
                        audio_path=path, embedded_audio="ignore",
                        source_route="H3 Project Asset Manager")
                else:
                    from .audio_track_contract import audio_track_bindings
                    bindings = audio_track_bindings(bindings, catalog["assets"])
                    tracks = {}
                    for role, asset_id in bindings.items():
                        if asset_id:
                            _asset, track_path = store.asset(run_name, asset_id)
                            tracks[role] = _make_source_timeline(
                                audio_path=track_path, embedded_audio="ignore")
                    source_timeline = _make_audio_tracks(**tracks)
            else:
                raise ValueError("A Source track must be video or audio.")

        compact_catalog = {
            **catalog,
            "assets": [{
                key: value for key, value in entry.items()
                if key not in ("absolute_path",)
            } for entry in catalog["assets"]],
        }
        record = {
            "format": PROJECT_ASSET_FORMAT,
            "version": 1,
            "project": str(catalog["project"]),
            "catalog": compact_catalog,
            "references": references,
            "reference_fingerprint": fingerprint,
            "source_timeline": source_timeline,
            "source_timeline_asset_id": (
                str(source_entries[0]["id"]) if source_entries else ""),
        }
        if ownership is not None:
            record["_project_ownership"] = ownership
        unresolved = len(catalog.get("reference_slots", []))
        status = (
            "%s: %d native, %d semantic, %d unassigned, source track %s; %s"
            % (
            catalog["project"], native_count, len(semantic_entries),
            unresolved,
            "on" if source_timeline is not None else "off",
            str(catalog.get("revision") or "")[:12]))
        if completed_operation:
            status += "; created image variant %s" % completed_operation[:8]
        return record, references, fingerprint, source_timeline, status


class MiniMaxH3ChainRunManager:
    @classmethod
    def INPUT_TYPES(cls):
        inputs = {
            "required": {
                "plan": (PLAN_TYPE, {
                    "tooltip": "Connect the active H3 Chain Plan. The Run "
                               "Manager can replace that Plan's prompts and "
                               "settings with a saved run after confirmation; "
                               "execution passes the current Plan through."}),
                "archive_images": ("BOOLEAN", {
                    "default": True,
                    "tooltip": "Keep content-addressed fallback copies of "
                               "connected picture assets in the run folder."}),
                "archive_audio": ("BOOLEAN", {
                    "default": True,
                    "tooltip": "Keep fallback copies of connected audio "
                               "references and source tracks."}),
                "archive_video": ("BOOLEAN", {
                    "default": False,
                    "tooltip": "Keep fallback copies of connected video "
                               "assets. Disabled by default because videos "
                               "can make a run archive very large."}),
                "asset_bindings_json": ("STRING", {
                    "default": "[]", "multiline": False,
                    "dynamicPrompts": False,
                    "tooltip": "Internal loader-binding manifest maintained "
                               "by the Run Manager interface."}),
            },
            "optional": {},
        }
        for index in range(MAX_DIRECT_ASSET_BINDINGS):
            inputs["optional"]["asset_%d" % index] = ("*", {
                "rawLink": True,
                "lazy": True,
                "tooltip": "Connect a loader output to register its source "
                           "file for this run. The manager reads the graph "
                           "link without decoding or retaining the media."})
        inputs["optional"]["source_timeline"] = (SOURCE_TIMELINE_TYPE, {
            "tooltip": "Optional explicit media wire. It takes priority over "
                       "automatic promotion; otherwise exactly one loader "
                       "asset assigned the Source track role becomes the "
                       "recoverable Source Timeline automatically."})
        inputs["optional"]["tagged_references"] = (
            TAGGED_REFERENCE_TYPE, {
                "tooltip": "Final Tagged reference line. Connect it directly "
                           "from the last Tagged Picture, Video, or Audio Ref, "
                           "or from Semantic Anchor Bundle when semantic "
                           "pictures are used. The manager also discovers and "
                           "archives any semantic image loaders carried by "
                           "that optional bundle."})
        return inputs

    # The timeline output is appended so the established Plan output remains
    # positional slot zero for every 0.4 workflow.
    RETURN_TYPES = (PLAN_TYPE, SOURCE_TIMELINE_TYPE)
    RETURN_NAMES = ("plan", "source_timeline")
    OUTPUT_TOOLTIPS = (
        "The connected Plan with JSON-safe Source Timeline recovery metadata "
        "from either the explicit media wire or the promoted Source track "
        "asset.",
        "Path-backed Source Timeline for Loop Start, Tagged Motion, preview, "
        "and final assembly.",
    )
    FUNCTION = "passthrough"
    CATEGORY = "conditioning/minimax/context_loop"
    DESCRIPTION = ("Browse output/h3_chains projects; restore a saved run's "
                   "Plan and loader-backed reference assets; optionally keep "
                   "content-addressed image, audio, and video fallbacks; and "
                   "promote one Source track asset into the Plan's recoverable "
                   "Source Timeline.")

    def passthrough(self, plan, archive_images, archive_audio, archive_video,
                    asset_bindings_json, source_timeline=None,
                    tagged_references=None, **_assets):
        _require_plan_write(plan, "archive Run Manager project assets")
        if tagged_references is not None:
            _tagged_reference_entries(tagged_references)
            _reference_semantic_anchor_bundle(tagged_references)
        bindings = []
        try:
            bindings = json.loads(str(asset_bindings_json or "[]"))
            if not isinstance(bindings, list):
                raise ValueError("asset_bindings_json must contain a list")
        except (TypeError, ValueError, json.JSONDecodeError) as exc:
            _LOG.warning(
                "H3 Run Manager could not read asset bindings: %s", exc)
            bindings = []
        managed_plan = plan
        managed_timeline = source_timeline
        if managed_timeline is None:
            try:
                managed_timeline = _run_manager_source_track_timeline(
                    bindings)
            except (OSError, TypeError, ValueError) as exc:
                _LOG.warning(
                    "H3 Run Manager could not promote source_track to "
                    "Source Timeline: %s", exc)
        if managed_timeline is None and isinstance(
                plan.get("source_timeline"), dict):
            managed_timeline = _source_timeline_from_recovery(
                plan["source_timeline"])
        if managed_timeline is not None:
            managed_timeline = _materialize_source_timeline_audio(
                managed_timeline, plan)
            managed_timeline = _archive_source_timeline_media(
                managed_timeline, plan,
                archive_audio=bool(archive_audio),
                archive_video=bool(archive_video))
            managed_plan = dict(plan)
            managed_plan["source_timeline"] = (
                _source_timeline_recovery_record(managed_timeline))
            with _project_write_commit_guard(
                    plan["run_name"], plan.get("_project_ownership"),
                    "archive Run Manager source media"):
                _atomic_json(
                    os.path.join(_run_dir(plan), "source_timeline.json"),
                    managed_plan["source_timeline"])
        try:
            if bindings:
                with _project_write_commit_guard(
                        plan["run_name"], plan.get("_project_ownership"),
                        "archive Run Manager project assets"):
                    result = RunAssetStore(
                        _output_root(), _input_root()).save(
                            plan["run_name"], bindings, {
                                "images": bool(archive_images),
                                "audio": bool(archive_audio),
                                "video": bool(archive_video),
                            })
                if result.get("warnings"):
                    _LOG.warning(
                        "H3 Run Manager asset archive warnings for %s: %s",
                        plan["run_name"], "; ".join(result["warnings"]))
        except ProjectOwnershipError:
            raise
        except (OSError, TypeError, ValueError) as exc:
            # Recovery metadata is supplementary and must never waste a long
            # H3 generation that already reached this pass-through.
            _LOG.warning("H3 Run Manager could not archive assets: %s", exc)
        return (managed_plan, managed_timeline)


