def _review_batch_kept_revisions(
        state: dict[str, Any], index: int, target: int,
        candidates: list[dict[str, Any]]) -> list[str]:
    """Restore the user's keep marks while an incremental batch continues."""
    batch = state.get("candidate_batch")
    if (not isinstance(batch, dict) or int(batch.get("scene", -1)) != index
            or int(batch.get("target", -1)) != target):
        return []
    available = {
        str(candidate.get("segment", {}).get("revision") or "")
        for candidate in candidates if isinstance(candidate, dict)
    }
    raw = batch.get("kept_revisions")
    if not isinstance(raw, list):
        return []
    return list(dict.fromkeys(
        str(revision) for revision in raw
        if str(revision) in available))


def _review_next_candidate_seed(candidates: list[dict[str, Any]],
                                current_seed: int) -> int:
    used = {int(current_seed)}
    for candidate in candidates:
        try:
            used.add(int(candidate["segment"].get("seed", 0)))
        except (KeyError, TypeError, ValueError):
            continue
    seed = secrets.randbits(64)
    while seed in used:
        seed = secrets.randbits(64)
    return seed


def _review_requested_kept_revisions(
        body: dict[str, Any], candidates: list[dict[str, Any]],
        selected_revision: str = "") -> list[str]:
    """Validate the user's keep marks against this exact pending batch."""
    # Older frontends did not send keep marks at all. Treat omission as
    # preserve-all; an explicit empty list remains the user's instruction to
    # prune every unselected candidate.
    raw = body.get("candidate_revisions")
    if "candidate_revisions" not in body:
        raw = [
            str(candidate.get("segment", {}).get("revision") or "")
            for candidate in candidates if isinstance(candidate, dict)
        ]
    if raw is None:
        raw = []
    if not isinstance(raw, list):
        raise ValueError("Kept H3 candidate revisions must be a list.")
    available = {
        str(candidate.get("segment", {}).get("revision") or "")
        for candidate in candidates if isinstance(candidate, dict)
    }
    kept = []
    for value in raw:
        revision = str(value or "")
        if revision not in available:
            raise ValueError(
                "A kept H3 candidate is not part of this pending review.")
        if revision not in kept:
            kept.append(revision)
    if selected_revision and selected_revision not in kept:
        kept.append(selected_revision)
    return kept


def _prune_review_candidates(
        plan: dict[str, Any], index: int,
        candidates: list[dict[str, Any]],
        kept_revisions: list[str]) -> dict[str, Any]:
    """Delete unkept candidate revisions after the active take is promoted."""
    available = []
    for candidate in candidates:
        segment = candidate.get("segment") if isinstance(candidate, dict) else None
        revision = str(segment.get("revision") or "") if isinstance(
            segment, dict) else ""
        if re.fullmatch(r"[0-9a-f]{32}", revision) and revision not in available:
            available.append(revision)
    kept = [revision for revision in dict.fromkeys(
        str(value) for value in kept_revisions) if revision in available]
    manager = CheckpointGraphManager(_output_root())
    deleted = []
    warnings = []
    reclaimed = 0
    for revision in available:
        if revision in kept:
            continue
        try:
            preview = manager.deletion_preview(
                str(plan["run_name"]), int(index), revision)
            if not preview.get("allowed"):
                warnings.append(
                    "%s: %s" % (revision[:8], " ".join(
                        str(item) for item in preview.get("blockers", ()))))
                continue
            result = manager.delete(
                str(plan["run_name"]), int(index), revision,
                preview.get("snapshot"))
            deleted.append(revision)
            reclaimed += int(result.get("reclaimed_bytes", 0))
        except (CheckpointDeleteBlocked, FileNotFoundError, OSError,
                TypeError, ValueError, json.JSONDecodeError, KeyError) as exc:
            warnings.append("%s: %s" % (revision[:8], exc))
    return {
        "kept": kept,
        "deleted": deleted,
        "reclaimed_bytes": reclaimed,
        "warnings": warnings,
    }


def _select_review_candidate(
        state: dict[str, Any], current_segment: dict[str, Any],
        decision: dict[str, Any]
) -> tuple[dict[str, Any], dict[str, Any]]:
    revision = str(decision.get("candidate_revision") or "")
    if not revision or revision == str(current_segment.get("revision") or ""):
        return current_segment, state
    if _st_load is None:
        raise RuntimeError("safetensors is required to select an H3 candidate.")
    plan = state["plan"]
    index = int(state["index"])
    metadata, _metadata_path = _load_checkpoint_revision(
        str(plan["run_name"]), index, revision)
    if _canonical_json(metadata.get("compatibility")) != _canonical_json(
            plan.get("compatibility")):
        raise ValueError(
            "The selected candidate uses different Plan compatibility settings.")
    selected = metadata["segment"]
    if index > 1:
        predecessors = state.get("segments")
        predecessor = predecessors[-1] if isinstance(
            predecessors, list) and predecessors else None
        expected_revision = str(selected.get("predecessor_revision") or "")
        expected_hash = str(
            selected.get("predecessor_checkpoint_sha256") or "")
        if (not isinstance(predecessor, dict)
                or (expected_revision and expected_revision != str(
                    predecessor.get("revision") or ""))
                or (expected_hash and expected_hash != str(
                    predecessor.get("checkpoint_sha256") or ""))):
            raise ValueError(
                "The selected candidate was generated from a different "
                "predecessor checkpoint.")
    selected_plan = _plan_with_review_revision(
        plan, index, str(selected.get(
            "scene_prompt_template", selected.get("scene_prompt")) or ""),
        int(selected.get("seed", 0)), int(selected.get("raw_frames", 0)))
    expected_history = _history_hash(selected_plan, index)
    if str(selected.get("history_hash") or "") != expected_history:
        raise ValueError(
            "The selected candidate does not match the current scene plan.")
    tensors = _st_load(_absolute_output_path(selected["checkpoint"]))
    missing = sorted({"context_frames", "video", "audio"} - set(tensors))
    if missing:
        raise ValueError(
            "The selected candidate checkpoint is missing tensors: %s" % missing)
    expected_context = min(
        _plan_context_storage_length(selected_plan),
        int(selected.get("delivered_frames", 0)))
    if int(tensors["context_frames"].shape[0]) != expected_context:
        raise ValueError(
            "The selected candidate contains %d context frames; expected %d." %
            (int(tensors["context_frames"].shape[0]), expected_context))
    canonical = _artifact_paths(selected_plan, index)["metadata"]
    with checkpoint_run_lock(_output_root(), str(selected_plan["run_name"])):
        _atomic_json(canonical, metadata)
        # Keep disk recovery aligned with the promoted take even if ComfyUI is
        # interrupted before the following scene reaches Segment Save.
        _promote_checkpoint_run_archives(selected_plan, metadata)
    accepted = dict(_public_segment(selected))
    accepted["_h3_review_decision"] = {
        "action": "candidate_selected",
        "revision": revision,
        "plan": selected_plan,
        "context_frames": tensors["context_frames"],
        "sampled_latent": {
            "samples": [tensors["video"], tensors["audio"]],
        },
    }
    selected_state = dict(state)
    selected_state["plan"] = selected_plan
    selected_state.pop("candidate_batch", None)
    return accepted, selected_state


def _throw_if_review_interrupted() -> None:
    """Honor ComfyUI Stop/Cancel while an async Review Gate is waiting."""
    try:
        import comfy.model_management as model_management
    except ImportError:
        return
    check = getattr(
        model_management, "throw_exception_if_processing_interrupted", None)
    if callable(check):
        check()


def _release_loop_boundary_resources(
        policy: str, scene_index: int) -> dict[str, int | str]:
    """Best-effort model/cache cleanup after a durable scene checkpoint.

    ComfyUI does not expose a supported full PromptExecutor reset while a
    dynamic subgraph is still resolving. ``fresh_scene`` therefore uses the
    public model manager plus the RAM-pressure cache release callback installed
    by PromptExecutor. The recursive carry has already been reduced to CPU
    context/checkpoint state before this runs, so evictable loader and
    intermediate outputs may be rebuilt safely by the following scene.
    """
    resolved = str(policy or "off").strip().lower()
    if resolved not in LOOP_MEMORY_POLICIES:
        raise ValueError(
            "H3 Loop End between_scene_cleanup must be one of %s; got %r." %
            (LOOP_MEMORY_POLICIES, policy))
    result: dict[str, int | str] = {
        "policy": resolved,
        "pinned_bytes": 0,
        "cache_bytes": 0,
        "collected_objects": 0,
    }
    if resolved == "off":
        return result

    try:
        import comfy.model_management as model_management
    except ImportError as exc:
        _LOG.warning(
            "H3 Chain could not run %s cleanup after scene %d: %s",
            resolved, int(scene_index), exc)
        return result

    if resolved == "fresh_scene":
        # Execution outputs can retain complete loader branches, decoded
        # videos, and patched model objects. Evict them before model unload so
        # unloading cannot briefly coexist with all of those allocations in
        # host RAM. This ordering is essential for workflows that switch two
        # large H3 checkpoints inside one recursive scene body.
        try:
            import comfy.memory_management as memory_management
            release = getattr(memory_management, "extra_ram_release", None)
            if callable(release):
                result["cache_bytes"] = int(release(
                    sys.maxsize, free_active=True))
        except Exception as exc:
            _LOG.warning(
                "H3 Chain fresh-scene cleanup could not request execution "
                "cache eviction after scene %d: %s", int(scene_index), exc)
        result["collected_objects"] = int(gc.collect())

    cleanup_models = getattr(model_management, "cleanup_models_gc", None)
    if resolved == "fresh_scene" and callable(cleanup_models):
        try:
            cleanup_models()
        except Exception as exc:
            _LOG.warning(
                "H3 Chain could not prune unreferenced models after scene "
                "%d: %s", int(scene_index), exc)

    if resolved == "fresh_scene":
        # Any DynamicVRAM pins still associated with this now-durable scene
        # can be released after the execution cache and dead model references
        # are gone. This leaves less host state for unload_all_models to walk.
        free_pins = getattr(model_management, "free_pins", None)
        if callable(free_pins):
            try:
                result["pinned_bytes"] = int(free_pins(
                    sys.maxsize, evict_active=True))
            except Exception as exc:
                _LOG.warning(
                    "H3 Chain fresh-scene cleanup could not release pinned "
                    "model pages after scene %d: %s", int(scene_index), exc)

    try:
        model_management.unload_all_models()
    except Exception as exc:
        _LOG.warning(
            "H3 Chain could not unload models after scene %d: %s",
            int(scene_index), exc)

    empty_cache = getattr(model_management, "soft_empty_cache", None)
    if callable(empty_cache):
        try:
            empty_cache(force=True)
        except TypeError:
            empty_cache()
        except Exception as exc:
            _LOG.warning(
                "H3 Chain could not empty the device allocator after scene "
                "%d: %s", int(scene_index), exc)

    _LOG.info(
        "H3 Chain scene %d boundary cleanup=%s: execution cache %.1f MB, "
        "pinned model pages %.1f MB, Python objects %d; the next scene "
        "reloads any evicted model or intermediate outputs.",
        int(scene_index), resolved,
        int(result["cache_bytes"]) / float(1024 ** 2),
        int(result["pinned_bytes"]) / float(1024 ** 2),
        int(result["collected_objects"]))
    return result


async def _await_review_decision(future: asyncio.Future,
                                 timeout_seconds: float) -> dict[str, Any]:
    """Wait with a heartbeat so cross-thread HTTP decisions always wake up.

    ComfyUI executes prompts on a worker thread and serves HTTP on another
    asyncio loop. Some loop/selector combinations queue call_soon_threadsafe
    callbacks without waking an otherwise idle selector. A short shielded wait
    keeps the execution loop responsive without cancelling its decision future,
    and polls ComfyUI's interrupt flag so Stop/Cancel can end an indefinite gate.
    """
    loop = asyncio.get_running_loop()
    deadline = loop.time() + timeout_seconds if timeout_seconds > 0 else None
    while True:
        _throw_if_review_interrupted()
        if future.done():
            return future.result()
        wait_seconds = 0.25
        if deadline is not None:
            remaining = deadline - loop.time()
            if remaining <= 0:
                return {"action": "approve", "timed_out": True}
            wait_seconds = min(wait_seconds, remaining)
        try:
            return await asyncio.wait_for(
                asyncio.shield(future), timeout=wait_seconds)
        except asyncio.TimeoutError:
            if deadline is not None and loop.time() >= deadline:
                return {"action": "approve", "timed_out": True}


class MiniMaxH3ChainReview:
    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {
                "state": (STATE_TYPE, {
                    "tooltip": "Current state from H3 Chain Current Shot. It "
                               "identifies the scene whose saved segment is "
                               "being reviewed."}),
                "segment": (SEGMENT_TYPE, {
                    "tooltip": "Persisted scene output from H3 Chain Segment "
                               "Save. Saving before review makes every accepted "
                               "scene recoverable."}),
                "enabled": ("BOOLEAN", {
                    "default": True,
                    "tooltip": "Pause after every saved segment for approval. "
                               "A connected, enabled Pending Review node "
                               "overrides this toggle so the completed batch "
                               "can be stored and stopped."}),
                "play_notification_sound": ("BOOLEAN", {
                    "default": False,
                    "tooltip": "Play a browser chime when a segment becomes "
                               "ready for review."}),
                "auto_continue_timeout_minutes": ("FLOAT", {
                    "default": 0.0,
                    "min": 0.0,
                    "max": 1440.0,
                    "step": 0.5,
                    "tooltip": "Automatically approve and continue after this "
                               "many minutes. 0 waits indefinitely."}),
                "unload_models_while_waiting": ("BOOLEAN", {
                    "default": False,
                    "tooltip": "Release model weights from VRAM after the review "
                               "appears. Approval remains responsive; continuing "
                               "must reload the model stack."}),
                "assemble_partial_on_stop": ("BOOLEAN", {
                    "default": True,
                    "tooltip": "Approve & stop also joins every accepted segment "
                               "through the current scene into a partial MP4."}),
                "partial_audio_source": (["checkpointed", "source", "none"], {
                    "default": "checkpointed",
                    "tooltip": "Audio for the partial MP4 created by Approve "
                               "& Stop. checkpointed uses each saved generated "
                               "delivered-audio track; source uses the exact "
                               "Source Timeline audio carried in state, or the "
                               "legacy full source_audio input when no Source "
                               "Timeline is available; none creates a silent "
                               "partial."}),
            },
            "optional": {
                "audio": ("AUDIO", {
                    "tooltip": "Wire frame-exact delivered audio from H3 "
                               "MiniMax H3 Context Loop Trim for synchronized "
                               "review."}),
                "source_audio": ("AUDIO", {
                    "tooltip": "Fallback only for runs whose state predates "
                               "recoverable source audio. Both Source Timeline "
                               "and a legacy AUDIO connected at Loop Start are "
                               "now carried path-backed in state. This does not "
                               "affect generation or the per-scene preview."}),
                "candidate_count": ("INT", {
                    "default": 1,
                    "min": 1,
                    "max": MAX_REVIEW_CANDIDATES,
                    "step": 1,
                    "tooltip": "Generate this many different-seed takes in a "
                               "row before Review Gate pauses. Mark one or more "
                               "takes to keep and choose which exact checkpoint "
                               "continues the chain; unkept alternatives are "
                               "deleted. "
                               "Convert this widget to an input to drive it from "
                               "an INT node."}),
                "review_each_candidate": ("BOOLEAN", {
                    "default": False,
                    "tooltip": "Optional inspection mode. Pause after every "
                               "saved take so the candidate run can be accepted "
                               "early or advanced manually. Leave off to generate "
                               "the full candidate_count batch automatically and "
                               "review it once at the end."}),
                "pending_review": (REVIEW_DISPOSITION_TYPE, {
                    "tooltip": "Optional MiniMax H3 Pending Review control. "
                               "When enabled, Review Gate generates the full "
                               "candidate batch, persists it for later review, "
                               "and stops cleanly instead of waiting for a "
                               "browser decision."}),
            },
            "hidden": {
                "dynprompt": "DYNPROMPT",
                "unique_id": "UNIQUE_ID",
            },
        }

    RETURN_TYPES = (SEGMENT_TYPE, "STRING")
    RETURN_NAMES = ("segment", "status")
    OUTPUT_TOOLTIPS = (
        "The approved segment, or the same segment after review is disabled. "
        "Connect to Loop End.",
        "Review decision, retry seed, timeout, stop, or partial-assembly status.",
    )
    FUNCTION = "review"
    OUTPUT_NODE = True
    CATEGORY = "conditioning/minimax/context_loop"
    DESCRIPTION = ("Pause after a checkpointed H3 segment for synchronized "
                   "video/audio review. Approve, stop, retry an edited scene "
                   "prompt/seed/duration, or reroll its seed while applying "
                   "the edited duration from the node UI.")

    @classmethod
    def IS_CHANGED(cls, *args, **kwargs):
        return float("NaN")

    async def review(self, state, segment, enabled, play_notification_sound,
                     auto_continue_timeout_minutes, unload_models_while_waiting,
                     assemble_partial_on_stop, partial_audio_source, audio=None,
                     source_audio=None, candidate_count=1,
                     review_each_candidate=False,
                     pending_review=None,
                     dynprompt=None, unique_id=None):
        plan = state["plan"]
        index = int(state["index"])
        if int(segment.get("index", -1)) != index:
            raise ValueError(
                "H3 Chain Review received the wrong segment for clip %d." % index)
        defer_completed_batch = _deferred_review_enabled(pending_review)
        if not enabled and not defer_completed_batch:
            status = "review bypassed for clip %d" % index
            return {"ui": {"text": [status]}, "result": (segment, status)}
        _require_plan_write(plan, "create or change a scene review")
        if PromptServer is None or web is None:
            raise RuntimeError("H3 Chain Review requires ComfyUI's prompt server.")

        # Publish the persisted video and pending token BEFORE preparing the
        # optional audiovisual preview. Firefox/proxy websocket differences
        # made this ordering bug look like a dead button: a slow or stuck audio
        # mux meant the browser never received a token at all. Review audio is
        # a convenience, not part of checkpoint validity, so it must never hold
        # the gate controls hostage.
        video, _has_audio, no_audio_warning = _review_video(
            plan, segment, None)
        shot = plan["shots"][index - 1]
        candidate_target = _review_candidate_target(candidate_count)
        # A deferred review is useful precisely because it needs no live
        # interaction. Generate the complete batch even if an older workflow
        # left per-candidate inspection enabled on Review Gate.
        inspect_each_candidate = (
            bool(review_each_candidate) and not defer_completed_batch)
        previous_candidates = _review_batch_candidates(
            state, index, candidate_target)
        batch_token = _review_batch_token(state, index, candidate_target)
        candidate_index = len(previous_candidates) + 1
        if candidate_index > candidate_target:
            previous_candidates = []
            batch_token = ""
            candidate_index = 1
        if candidate_index < candidate_target and not inspect_each_candidate:
            try:
                candidate_video, candidate_has_audio, candidate_warning = (
                    _review_video(
                        plan, segment, audio, retain_previous=True))
            except Exception as exc:
                _LOG.exception(
                    "H3 Chain candidate synchronized preview failed")
                candidate_video, candidate_has_audio, candidate_warning = (
                    video, False,
                    "Candidate audio preview is unavailable (%s)." % exc)
            current_candidate = _review_candidate_record(
                segment, candidate_video, candidate_has_audio,
                candidate_warning)
        else:
            current_candidate = _review_candidate_record(
                segment, video, False, no_audio_warning)
        candidates = previous_candidates + [current_candidate]
        kept_revisions = _review_batch_kept_revisions(
            state, index, candidate_target, previous_candidates)

        queued_decision = None
        batch_entry = (_ACTIVE_CANDIDATE_BATCHES.get(batch_token)
                       if batch_token else None)
        if isinstance(batch_entry, dict):
            available_before_current = {
                str(candidate.get("segment", {}).get("revision") or "")
                for candidate in candidates if isinstance(candidate, dict)
            }
            entry_kept = batch_entry.get("kept_revisions")
            if isinstance(entry_kept, list):
                kept_revisions = list(dict.fromkeys(
                    str(revision) for revision in entry_kept
                    if str(revision) in available_before_current))
        batch_command = (batch_entry.get("command")
                         if isinstance(batch_entry, dict) else None)
        if isinstance(batch_command, dict):
            requested_kept = [
                str(value) for value in batch_command.get(
                    "kept_revisions", ())]
            available = {
                str(candidate.get("segment", {}).get("revision") or "")
                for candidate in candidates if isinstance(candidate, dict)
            }
            kept_revisions = list(dict.fromkeys(
                revision for revision in requested_kept
                if revision in available))
            if batch_command.get("action") == "pause":
                inspect_each_candidate = True
            elif batch_command.get("action") == "accept":
                requested_revision = str(
                    batch_command.get("candidate_revision") or "")
                selected_number = next((
                    number for number, candidate in enumerate(
                        candidates, start=1)
                    if str(candidate.get("segment", {}).get(
                        "revision") or "") == requested_revision
                ), 0)
                if selected_number:
                    if requested_revision not in kept_revisions:
                        kept_revisions.append(requested_revision)
                    queued_decision = {
                        "action": "approve",
                        "candidate_revision": requested_revision,
                        "candidate_number": selected_number,
                        "candidate_count": candidate_target,
                        "candidate_generated_count": len(candidates),
                        "kept_candidate_revisions": kept_revisions,
                        "candidate_batch_command": True,
                        "candidate_batch_token": batch_token,
                    }

        # Saving is the safe default. A take is removed only after the user
        # explicitly unchecks it in a review UI and accepts another take.
        current_revision = str(segment.get("revision") or "")
        if current_revision and current_revision not in kept_revisions:
            kept_revisions.append(current_revision)

        if (candidate_index < candidate_target
                and not inspect_each_candidate
                and queued_decision is None):
            if not batch_token:
                _review_candidate_batch_cleanup()
                for stale_token, stale in list(
                        _ACTIVE_CANDIDATE_BATCHES.items()):
                    if (str(stale.get("run_name") or "") == str(
                            plan["run_name"])
                            and stale.get("plan", {}).get("_branch_id", "main") == plan.get("_branch_id", "main")
                            and int(stale.get("scene", -1)) == index):
                        _ACTIVE_CANDIDATE_BATCHES.pop(stale_token, None)
                batch_token = uuid.uuid4().hex
                batch_entry = {}
            elif not isinstance(batch_entry, dict):
                batch_entry = {}

            display_id = _review_display_id(unique_id, dynprompt)
            progress_payload = {
                "token": batch_token,
                "_branch_id": plan.get("_branch_id", "main"),
                "node_id": display_id,
                "execution_id": str(unique_id),
                "run_name": str(plan["run_name"]),
                "clip_index": index,
                "clip_count": len(plan["shots"]),
                "end_clip": int(state.get("range_end", len(plan["shots"]))),
                "shot_id": shot["id"],
                "scene_prompt": shot.get("scene_prompt", shot["prompt"]),
                "prompt_prefix": str(plan.get("prompt_prefix") or ""),
                "seed": str(shot["seed"]),
                "raw_frames": int(shot["raw_frames"]),
                "duration_seconds": int(shot["raw_frames"]) / float(FPS),
                "video": candidate_video,
                "has_audio": candidate_has_audio,
                "warning": candidate_warning,
                "preview_pending": False,
                "preview_revision": candidate_index * 2 + 1,
                "candidate_index": candidate_index,
                "candidate_count": candidate_target,
                "candidate_generation_complete": False,
                "candidate_batch_active": True,
                "pending_decision": False,
                "review_each_candidate": False,
                "candidate_remaining": candidate_target - candidate_index,
                "candidates": _review_public_candidates(candidates),
                "kept_candidate_revisions": kept_revisions,
                "play_notification_sound": bool(play_notification_sound),
                "unload_models_while_waiting": False,
                "assemble_partial_on_stop": bool(assemble_partial_on_stop),
                "timeout_seconds": 0.0,
                "deadline": None,
                "server_now": time.time(),
            }
            batch_entry.update({
                "updated": time.monotonic(),
                "run_name": str(plan["run_name"]),
                "scene": index,
                "target": candidate_target,
                "plan": plan,
                "candidates": candidates,
                "kept_revisions": kept_revisions,
                "public": progress_payload,
            })
            _ACTIVE_CANDIDATE_BATCHES[batch_token] = batch_entry
            PromptServer.instance.send_sync(
                "minimax_h3_context_loop_review", dict(progress_payload),
                PromptServer.instance.client_id)

            next_seed = _review_next_candidate_seed(
                candidates, int(shot["seed"]))
            revised_segment = dict(segment)
            revised_segment["_h3_review_decision"] = {
                "action": "retry",
                "scene_prompt": shot.get(
                    "scene_prompt_template",
                    shot.get("scene_prompt", shot["prompt"])),
                "seed": next_seed,
                "raw_frames": int(shot["raw_frames"]),
                "candidate_batch": {
                    "scene": index,
                    "target": candidate_target,
                    "candidates": candidates,
                    "kept_revisions": kept_revisions,
                    "batch_token": batch_token,
                },
            }
            status = (
                "saved candidate %d/%d for clip %d; automatically generating "
                "candidate %d with seed %d" %
                (candidate_index, candidate_target, index,
                 candidate_index + 1, next_seed))
            return {"ui": {"text": [status]},
                    "result": (revised_segment, status)}

        if batch_token:
            _ACTIVE_CANDIDATE_BATCHES.pop(batch_token, None)
        timeout_seconds = _review_timeout_seconds(
            auto_continue_timeout_minutes)
        server_now = time.time()
        deadline = server_now + timeout_seconds if timeout_seconds > 0 else None
        token = (batch_token if queued_decision is not None
                 else uuid.uuid4().hex)
        loop = asyncio.get_running_loop()
        future = loop.create_future()
        preview_base = candidate_index * 2 if batch_token else 0
        payload = {
            "token": token,
            "_branch_id": plan.get("_branch_id", "main"),
            "node_id": _review_display_id(unique_id, dynprompt),
            "execution_id": str(unique_id),
            "run_name": str(plan["run_name"]),
            "clip_index": index,
            "clip_count": len(plan["shots"]),
            "end_clip": int(state.get("range_end", len(plan["shots"]))),
            "shot_id": shot["id"],
            "scene_prompt": shot.get("scene_prompt", shot["prompt"]),
            "prompt_prefix": str(plan.get("prompt_prefix") or ""),
            "seed": str(shot["seed"]),
            "raw_frames": int(shot["raw_frames"]),
            "duration_seconds": int(shot["raw_frames"]) / float(FPS),
            "video": video,
            "has_audio": False,
            "warning": ("Preparing synchronized audio preview…"
                        if audio is not None else no_audio_warning),
            "preview_pending": audio is not None,
            "preview_revision": preview_base,
            "candidate_index": candidate_index,
            "candidate_count": candidate_target,
            "candidate_generation_complete": (
                candidate_index >= candidate_target),
            "candidate_batch_active": False,
            "pending_decision": queued_decision is None,
            "review_each_candidate": bool(inspect_each_candidate),
            "candidate_remaining": max(
                0, candidate_target - candidate_index),
            "candidates": _review_public_candidates(candidates),
            "kept_candidate_revisions": kept_revisions,
            "play_notification_sound": bool(play_notification_sound),
            "unload_models_while_waiting": bool(unload_models_while_waiting),
            "assemble_partial_on_stop": bool(assemble_partial_on_stop),
            "timeout_seconds": timeout_seconds,
            "deadline": deadline,
            "server_now": server_now,
        }
        defer_now = (
            defer_completed_batch and queued_decision is None
            and candidate_index >= candidate_target)
        if not defer_now:
            _PENDING_REVIEWS[token] = {
                "future": future,
                "loop": loop,
                "public": payload,
                "plan": plan,
                "current_seed": int(shot["seed"]),
                "current_length": int(shot["raw_frames"]),
                "candidates": candidates,
            }
            # M5 durable review: persist a lightweight (tensor-free) snapshot so
            # the batch stays reviewable after a browser refresh or a ComfyUI
            # crash/restart. The snapshot holds identity only (token, run,
            # scene, candidate revision/seed, deadline); previews come from the
            # saved segment/checkpoint inventory, never from live tensors. The
            # Plan JSON is never touched (PLAN_SCHEMA_INVARIANT_SPEC).
            try:
                _write_review_snapshot(
                    _run_dir(plan), token, str(plan.get("run_name") or ""),
                    int(payload.get("clip_index") or index),
                    _review_public_candidates(candidates),
                    deadline, float(server_now))
            except (OSError, TypeError, ValueError) as exc:
                _LOG.warning(
                    "H3 Chain durable review snapshot failed (review stays "
                    "live only): %s", exc)
            PromptServer.instance.send_sync(
                "minimax_h3_context_loop_review", dict(payload),
                PromptServer.instance.client_id)

        if audio is not None:
            # Keep tensor-to-WAV conversion on Comfy's execution thread. Some
            # PyTorch builds can deadlock when their CPU tensor pools are first
            # entered from asyncio.to_thread. The token is already public, and
            # The external ffmpeg path is time-bounded, and either media backend
            # can fail into a silent review instead of an unresolvable workflow
            # hang.
            try:
                if candidate_target > 1 or defer_now:
                    video, has_audio, warning = _review_video(
                        plan, segment, audio, retain_previous=True)
                else:
                    video, has_audio, warning = _review_video(
                        plan, segment, audio)
            except Exception as exc:
                _LOG.exception("H3 Chain synchronized review preview failed")
                has_audio = False
                warning = (
                    "Synchronized review audio is unavailable (%s). The saved "
                    "segment/checkpoint is valid; this review is silent." % exc)
            payload.update({
                "video": video,
                "has_audio": has_audio,
                "warning": warning,
                "preview_pending": False,
                "preview_revision": preview_base + 1,
                "server_now": time.time(),
            })
            candidates[-1] = _review_candidate_record(
                segment, video, has_audio, warning)
            payload["candidates"] = _review_public_candidates(candidates)
            if not defer_now:
                PromptServer.instance.send_sync(
                    "minimax_h3_context_loop_review", dict(payload),
                    PromptServer.instance.client_id)

        if defer_now:
            if ExecutionBlocker is None:
                raise RuntimeError(
                    "This ComfyUI build does not support pending-review "
                    "blocking.")
            payload.update({
                "deferred_review": True,
                "pending_decision": True,
                "warning": (
                    "Candidate batch saved for later review. This execution "
                    "has stopped cleanly; select the pending batch in Review "
                    "Gate when ready."),
                "preview_pending": False,
                "deadline": None,
                "timeout_seconds": 0.0,
                "server_now": time.time(),
            })
            # Preparing/muxing the candidate preview can take long enough for
            # another workflow to force ownership in the meantime. Fence the
            # actual pending-review publication, not only gate entry.
            _require_plan_write(
                plan, "publish a pending scene review")
            _persist_deferred_review(plan, payload, candidates)
            PromptServer.instance.send_sync(
                "minimax_h3_context_loop_review", dict(payload),
                PromptServer.instance.client_id)
            status = (
                "saved %d candidate%s for clip %d as pending review; "
                "execution stopped at the checkpoint" %
                (len(candidates), "" if len(candidates) == 1 else "s", index))
            return {
                "ui": {"text": [status]},
                "result": (ExecutionBlocker(None), status),
            }

        if queued_decision is not None and not future.done():
            future.set_result(queued_decision)

        if unload_models_while_waiting and queued_decision is None:
            try:
                import comfy.model_management as model_management
                model_management.unload_all_models()
            except Exception as exc:
                _LOG.warning("H3 Chain Review could not unload models: %s", exc)

        try:
            try:
                decision = await _await_review_decision(
                    future, timeout_seconds)
            except BaseException:
                # ComfyUI's InterruptProcessingException intentionally derives
                # from BaseException. Resolve the browser gate before letting
                # the executor emit its normal execution_interrupted event.
                status = "review interrupted for clip %d" % index
                try:
                    PromptServer.instance.send_sync(
                        "minimax_h3_context_loop_review_resolved",
                        {"token": token, "node_id": payload["node_id"],
                         "action": "interrupted", "status": status},
                        PromptServer.instance.client_id)
                except Exception as exc:
                    _LOG.warning(
                        "H3 Chain Review could not publish interruption: %s",
                        exc)
                raise
        finally:
            _PENDING_REVIEWS.pop(token, None)
            if not future.done():
                future.cancel()
            # M5 durable review: mark the snapshot decided so a restart does
            # not resurface a resolved gate. Interrupts are marked with
            # action "interrupted": the durable candidate records remain
            # reviewable, the live gate does not.
            try:
                decided_action = "interrupted"
                if isinstance(locals().get("decision"), dict):
                    decided_action = str(
                        locals()["decision"].get("action") or "interrupted")
                run_dir = _run_dir(plan)
                _mark_review_snapshot_decided(
                    run_dir, token, decided_action, time.time())
                if decided_action in ("approve", "stop"):
                    _retire_superseded_review_snapshots(
                        run_dir, str(payload.get("run_name") or ""), index, token)
            except (OSError, TypeError, ValueError) as exc:
                _LOG.warning(
                    "H3 Chain durable review snapshot update failed: %s", exc)

        # A Review Gate may remain open for hours. A forced ownership transfer
        # must invalidate its eventual decision before candidate activation,
        # pruning, Plan archival, or partial assembly can touch the project.
        _require_plan_write(
            plan, "apply a scene review decision")
        action = decision["action"]
        if action == "next_candidate":
            next_seed = int(decision["seed"])
            revised_segment = dict(segment)
            revised_segment["_h3_review_decision"] = {
                "action": "retry",
                "scene_prompt": decision["scene_prompt"],
                "seed": next_seed,
                "raw_frames": int(decision["raw_frames"]),
                "candidate_batch": decision["candidate_batch"],
            }
            status = (
                "kept %d candidate%s; generating candidate %d/%d for clip %d "
                "with seed %d" %
                (len(decision["candidate_batch"].get(
                    "kept_revisions", ())),
                 "" if len(decision["candidate_batch"].get(
                     "kept_revisions", ())) == 1 else "s",
                 candidate_index + 1, candidate_target, index, next_seed))
            return {"ui": {"text": [status]},
                    "result": (revised_segment, status)}

        accepted_segment = segment
        accepted_state = state
        cleanup = None
        if action in ("approve", "stop"):
            with checkpoint_run_lock(
                    _output_root(), plan["run_name"]), project_write_guard(
                        _output_root(), plan["run_name"],
                        plan.get("_project_ownership"),
                        "apply a scene review decision"):
                accepted_segment, accepted_state = _select_review_candidate(
                    state, segment, decision)
                selected_revision = str(
                    accepted_segment.get("revision") or "")
                kept = list(decision.get("kept_candidate_revisions") or ())
                if selected_revision and selected_revision not in kept:
                    kept.append(selected_revision)
                cleanup = _prune_review_candidates(
                    accepted_state["plan"], index, candidates, kept)
        candidate_number = int(decision.get("candidate_number", 0))
        candidate_total = int(decision.get("candidate_count", 0))
        candidate_note = (
            "; selected candidate %d/%d" %
            (candidate_number, candidate_total)
            if candidate_total > 1 and candidate_number > 0 else "")
        if cleanup is not None and candidate_target > 1:
            candidate_note += "; kept %d, deleted %d candidate%s" % (
                len(cleanup["kept"]), len(cleanup["deleted"]),
                "" if len(cleanup["deleted"]) == 1 else "s")
            if cleanup["warnings"]:
                candidate_note += "; cleanup warning: %s" % " | ".join(
                    cleanup["warnings"])
        if action == "approve":
            timed_out = bool(decision.get("timed_out"))
            status = (("review timed out; auto-approved clip %d/%d; continuing")
                      if timed_out else ("approved clip %d/%d; continuing")) % (
                          index, len(plan["shots"]))
            status += candidate_note
            accepted_plan = accepted_state["plan"]
            if index == len(accepted_plan["shots"]):
                _PENDING_FINAL_REVIEW_PREVIEWS[
                    _final_review_preview_key(accepted_plan)
                ] = {
                    "token": token,
                    "node_id": payload["node_id"],
                    "client_id": PromptServer.instance.client_id,
                }
            if timed_out:
                PromptServer.instance.send_sync(
                    "minimax_h3_context_loop_review_resolved",
                    {"token": token, "node_id": payload["node_id"],
                     "action": "timeout_approve", "status": status},
                    PromptServer.instance.client_id)
            elif decision.get("candidate_batch_command"):
                PromptServer.instance.send_sync(
                    "minimax_h3_context_loop_review_resolved",
                    {
                        "token": token,
                        "node_id": payload["node_id"],
                        "action": "candidate_batch_approve",
                        "status": status,
                        "clip_index": index,
                        "scene_prompt": str(accepted_segment.get(
                            "scene_prompt_template",
                            accepted_segment.get("scene_prompt")) or ""),
                        "seed": str(accepted_segment.get("seed") or "0"),
                        "raw_frames": int(accepted_segment.get(
                            "raw_frames", shot["raw_frames"])),
                        "candidate_number": candidate_number,
                        "candidate_count": candidate_total,
                    },
                    PromptServer.instance.client_id)
            return {"ui": {"text": [status]},
                    "result": (accepted_segment, status)}
        if action == "stop":
            if ExecutionBlocker is None:
                raise RuntimeError("This ComfyUI build does not support review blocking.")
            status = ("approved clip %d and stopped at its checkpoint" % index
                      ) + candidate_note
            partial_item = None
            if assemble_partial_on_stop:
                try:
                    partial_path, partial_warning = _assemble_review_partial(
                        accepted_state, accepted_segment,
                        partial_audio_source, source_audio)
                    partial_item = _video_output_item(partial_path)
                    status += "; partial video: %s" % partial_path
                    if partial_warning:
                        status += "; %s" % partial_warning
                except Exception as exc:
                    _LOG.exception("H3 Chain partial stop assembly failed")
                    status += "; partial assembly failed: %s" % exc
            resolved = {
                "token": token,
                "node_id": payload["node_id"],
                "action": "stop",
                "status": status,
            }
            if partial_item is not None:
                resolved["partial_video"] = partial_item
            PromptServer.instance.send_sync(
                "minimax_h3_context_loop_review_resolved", resolved,
                PromptServer.instance.client_id)
            return {
                "ui": {"text": [status]},
                "result": (ExecutionBlocker(None), status),
            }
        if action != "retry":
            raise RuntimeError("Unknown H3 review decision %r." % action)

        revised_segment = dict(segment)
        revised_segment["_h3_review_decision"] = {
            "action": "retry",
            "scene_prompt": decision["scene_prompt"],
            "seed": int(decision["seed"]),
            "raw_frames": int(decision["raw_frames"]),
        }
        status = "retrying clip %d with seed %d at %d frames" % (
            index, int(decision["seed"]), int(decision["raw_frames"]))
        return {"ui": {"text": [status]},
                "result": (revised_segment, status)}


def _manifest_from_segments(plan: dict[str, Any], values: list[dict[str, Any]],
                            complete: bool) -> dict[str, Any]:
    segments = []
    archives = _available_run_archives(plan)
    for item in values:
        segment = _public_segment(item)
        index = int(segment.get("index", -1))
        if 1 <= index <= len(plan["shots"]):
            for key, value in _prompt_fields(plan, index).items():
                segment.setdefault(key, value)
        if archives:
            segment.setdefault("archives", archives)
        segments.append(segment)
    expected_count = len(plan["shots"]) if complete else len(segments)
    if expected_count < 1:
        raise ValueError("H3 chain manifest requires at least one saved clip.")
    if len(segments) != expected_count:
        raise ValueError(
            "H3 chain manifest is incomplete: found %d persisted clips, expected %d."
            % (len(segments), expected_count))
    indexes = [int(item.get("index", -1)) for item in segments]
    if indexes != list(range(1, expected_count + 1)):
        raise ValueError("H3 chain manifest segment indexes are not contiguous.")
    total_frames = int(plan["total_delivered_frames"]) if complete else sum(
        int(item.get(
            "delivered_frames",
            plan["shots"][int(item["index"]) - 1]["delivered_frames"]))
        for item in segments)
    manifest = {
        "format": ("h3_chain_manifest_v3" if complete
                   else "h3_chain_partial_manifest_v3"),
        "run_name": plan["run_name"],
        "plan_hash": plan["plan_hash"],
        "prompt_prefix": str(plan.get("prompt_prefix") or ""),
        "compatibility": plan["compatibility"],
        "clip_count": expected_count,
        "total_delivered_frames": total_frames,
        "duration_seconds": total_frames / float(FPS),
        "segments": segments,
    }
    if plan.get("_branch_id"):
        manifest["_branch_id"] = plan["_branch_id"]
    if archives:
        manifest["archives"] = archives
    if isinstance(plan.get("prelude"), dict):
        manifest["prelude"] = _json_document(plan["prelude"])
    if isinstance(plan.get("source_timeline"), dict):
        manifest["source_timeline"] = _json_document(
            plan["source_timeline"])
    if not complete:
        manifest["planned_clip_count"] = len(plan["shots"])
        manifest["last_completed_clip"] = len(segments)
    return manifest


def _manifest_from_state(state: dict[str, Any]) -> dict[str, Any]:
    return _manifest_from_segments(state["plan"], state["segments"], True)


def _partial_manifest(state: dict[str, Any],
                      segment: dict[str, Any]) -> dict[str, Any]:
    plan = state["plan"]
    index = int(state["index"])
    values = list(state.get("segments", [])) + [_public_segment(segment)]
    if index != len(values):
        raise ValueError(
            "H3 partial manifest expected clip %d after %d predecessors." %
            (index, len(values) - 1))
    return _manifest_from_segments(plan, values, False)


def _manifest_path(plan: dict[str, Any]) -> str:
    return os.path.join(_run_dir(plan), "manifest.json")


def _manifest_editorial(manifest: dict[str, Any]) -> dict[str, Any]:
    """Return the immutable editorial view embedded by a chapter manifest."""
    run_name = _strict_run_name(manifest.get("run_name"))
    embedded = manifest.get("editorial")
    if embedded is None:
        return _load_run_editorial(run_name)
    try:
        return _normalize_run_editorial(embedded, run_name)
    except (TypeError, ValueError) as exc:
        raise ValueError(
            "H3 chapter manifest contains invalid editorial recovery data: %s"
            % exc) from exc


def _manifest_segment_bounds(
        manifest: dict[str, Any], segments: list[dict[str, Any]],
        purpose: str) -> tuple[int, int]:
    """Validate one contiguous manifest without assuming that it starts at 1."""
    if not segments:
        raise ValueError("%s requires at least one scene." % purpose)
    indexes = [int(item.get("index", -1)) for item in segments]
    start = int(manifest.get("scene_start", indexes[0]))
    expected = list(range(start, start + len(segments)))
    if indexes != expected:
        raise ValueError(
            "%s requires contiguous scene indexes; found %s, expected %s." %
            (purpose, indexes, expected))
    end = start + len(segments) - 1
    if int(manifest.get("scene_end", end)) != end:
        raise ValueError("%s has an inconsistent scene_end." % purpose)
    chapter = manifest.get("chapter")
    if isinstance(chapter, dict):
        if (int(chapter.get("start_scene", 0)) != start or
                int(chapter.get("end_scene", 0)) != end):
            raise ValueError(
                "%s chapter range does not match its selected scenes." % purpose)
        planned_end = int(chapter.get("planned_end_scene", end))
        if (planned_end < end or
                chapter.get("complete", True) != (end == planned_end)):
            raise ValueError(
                "%s has inconsistent chapter completion metadata." % purpose)
    return start, end


def _editorial_chapter_ranges(
        editorial: dict[str, Any], maximum_scene: int
) -> list[dict[str, Any]]:
    """Resolve the same implicit ranges displayed by Checkpoint Manager."""
    maximum = max(1, int(maximum_scene))
    chapters = sorted(
        (dict(item) for item in editorial.get("chapters", [])
         if isinstance(item, dict)
         and 1 <= int(item.get("start_scene", 0)) <= maximum),
        key=lambda item: int(item["start_scene"]))
    ranges: list[dict[str, Any]] = []
    if not chapters:
        chapters = [{
            "id": "chapter_01",
            "title": "Chapter 1",
            "text": "",
            "start_scene": 1,
            "start_scene_id": "",
            "implicit": True,
        }]
    elif int(chapters[0]["start_scene"]) > 1:
        chapters.insert(0, {
            "id": "unassigned",
            "title": "Unassigned",
            "text": "",
            "start_scene": 1,
            "start_scene_id": "",
            "implicit": True,
        })
    for offset, chapter in enumerate(chapters):
        start = int(chapter["start_scene"])
        end = (int(chapters[offset + 1]["start_scene"]) - 1
               if offset + 1 < len(chapters) else maximum)
        if end < start:
            continue
        ranges.append({
            "number": len(ranges) + 1,
            "id": _safe_name(
                chapter.get("id"), "chapter_%02d" % (len(ranges) + 1)),
            "title": (str(chapter.get("title") or
                          "Chapter %d" % (len(ranges) + 1)).strip()
                      or "Chapter %d" % (len(ranges) + 1)),
            "text": str(chapter.get("text") or ""),
            "start_scene": start,
            "end_scene": end,
            "start_scene_id": str(chapter.get("start_scene_id") or ""),
            "implicit": bool(chapter.get("implicit", False)),
        })
    return ranges


def _chapter_directory_name(chapter: dict[str, Any]) -> str:
    number = int(chapter.get("number", 0))
    if number < 1 or number > MAX_SHOTS:
        raise ValueError("H3 chapter number is outside the supported range.")
    chapter_id = _safe_name(
        chapter.get("id"), "chapter_%02d" % number)
    return "%02d_%s" % (number, chapter_id)


def _chapter_delivery_root(manifest: dict[str, Any]) -> str:
    root = _run_dir(manifest)
    chapter = manifest.get("chapter")
    if not isinstance(chapter, dict):
        return root
    candidate = os.path.realpath(os.path.join(
        root, "chapters", _chapter_directory_name(chapter)))
    chapter_root = os.path.realpath(os.path.join(root, "chapters"))
    if os.path.commonpath([chapter_root, candidate]) != chapter_root:
        raise ValueError("H3 chapter output path escapes its Run directory.")
    return candidate


def _chapter_scoped_editorial(
        run_name: str, segments: list[dict[str, Any]],
        editorial: dict[str, Any], chapter: dict[str, Any],
        natural_start_frame: int = 0,
        timeline_segments: list[dict[str, Any]] | None = None
) -> tuple[dict[str, Any], int]:
    """Freeze chapter-local placement, trims, alternates, and subtitle origin."""
    _resolved, records, _total = _editorial_timeline_records(
        run_name, timeline_segments if timeline_segments is not None else segments,
        editorial, natural_start_frame)
    selected_scenes = {int(segment["index"]) for segment in segments}
    scene_records = [item for item in records if item.get("kind") == "scene"
                     and int(item["scene"]) in selected_scenes]
    if len(scene_records) != len(segments):
        raise ValueError(
            "H3 chapter editorial scope did not resolve every selected scene.")
    origin = min(int(item.get("start_frame", 0)) for item in scene_records)
    ids = {str(segment.get("id") or "") for segment in segments}
    scene_order = [{
        "scene": int(segment["index"]),
        "scene_id": str(segment.get("id") or
                        "clip_%04d" % int(segment["index"])),
    } for segment in segments]
    placements = [{
        "scene": int(item["scene"]),
        "scene_id": str(item["scene_id"]),
        "start_frame": int(item["start_frame"]) - origin,
    } for item in scene_records]
    start_id = next(
        item["scene_id"] for item in scene_order
        if int(item["scene"]) == int(chapter["start_scene"]))
    scoped = {
        "format": "h3_chain_editorial_v1",
        "run_name": run_name,
        "updated_at": str(
            editorial.get("updated_at") or "1970-01-01T00:00:00Z"),
        "chapters": [{
            "id": chapter["id"],
            "title": chapter["title"],
            "start_scene_id": start_id,
            "start_scene": int(chapter["start_scene"]),
            "text": chapter.get("text", ""),
        }],
        "scene_order": scene_order,
        "placements": placements,
        "trims": [dict(item) for item in editorial.get("trims", [])
                  if isinstance(item, dict)
                  and str(item.get("scene_id") or "") in ids],
        "locked_scene_ids": [
            str(item) for item in editorial.get("locked_scene_ids", [])
            if str(item) in ids],
        "subtitles": dict(editorial.get("subtitles") or {}),
        "alternate_draft": None,
        "replacements": [
            dict(item) for item in editorial.get("replacements", [])
            if isinstance(item, dict)
            and str(item.get("scene_id") or "") in ids],
    }
    return _normalize_run_editorial(scoped, run_name), origin


def _chapter_manifest_identity(manifest: dict[str, Any]) -> dict[str, Any]:
    identity = _json_document(manifest) or {}
    for key in ("sealed_at", "chapter_manifest_id", "chapter_manifest_path"):
        identity.pop(key, None)
    return identity


def _chapter_manifest_digest(manifest: dict[str, Any]) -> str:
    return hashlib.sha256(_canonical_json(
        _chapter_manifest_identity(manifest)).encode("utf-8")).hexdigest()[:32]


def _chapter_manifest_storage_path(
        manifest: dict[str, Any], snapshot_id: str) -> str:
    token = str(snapshot_id or "").strip().lower()
    if re.fullmatch(r"[0-9a-f]{32}", token) is None:
        raise ValueError("H3 chapter manifest id must be 32 hexadecimal digits.")
    root = _chapter_delivery_root(manifest)
    return os.path.join(root, "manifests", token + ".json")


def _persist_chapter_manifest(manifest: dict[str, Any]) -> tuple[
        dict[str, Any], str]:
    # Sealing and checkpoint deletion must be mutually exclusive. Revalidate
    # inside the lock, so a deletion between selection and sealing cannot
    # publish a chapter snapshot whose recovery inputs are already gone.
    with checkpoint_run_lock(_output_root(), manifest.get("run_name")):
        _validate_manifest(manifest)
        _editorial_presentation_segments(
            manifest.get("run_name"), manifest["segments"],
            _manifest_editorial(manifest))
        return _persist_chapter_manifest_locked(manifest)


def _persist_chapter_manifest_locked(manifest: dict[str, Any]) -> tuple[
        dict[str, Any], str]:
    snapshot = _json_document(manifest)
    if not isinstance(snapshot, dict):
        raise ValueError("H3 chapter delivery requires a JSON manifest.")
    snapshot_id = _chapter_manifest_digest(snapshot)
    path = _chapter_manifest_storage_path(snapshot, snapshot_id)
    retired_path = os.path.join(
        os.path.dirname(os.path.dirname(path)), "retired_manifests",
        snapshot_id + ".json")
    if os.path.lexists(retired_path):
        raise ValueError(
            "Chapter snapshot %s was retired for cleanup. It cannot be "
            "republished from a stale selection; select the desired branch "
            "and create an updated snapshot." % snapshot_id[:8])
    snapshot.update({
        "chapter_manifest_id": snapshot_id,
        "chapter_manifest_path": _relative_output_path(path),
        "sealed_at": datetime.now(timezone.utc).isoformat(
            timespec="seconds").replace("+00:00", "Z"),
    })
    if os.path.isfile(path):
        existing = _read_json(path)
        if (not isinstance(existing, dict)
                or _chapter_manifest_digest(existing) != snapshot_id
                or str(existing.get("chapter_manifest_id") or "") !=
                   snapshot_id
                or str(existing.get("chapter_manifest_path") or "") !=
                   _relative_output_path(path)):
            raise ValueError(
                "Stored H3 chapter manifest %s failed its identity check." %
                snapshot_id)
        snapshot = existing
    else:
        _atomic_json(path, snapshot)
    return snapshot, path


def _chapter_manifest_from_manifest(
        manifest: dict[str, Any], chapter_number: int = 0, *, persist: bool = True
) -> tuple[dict[str, Any], str]:
    """Snapshot the available scenes of one explicitly selectable chapter."""
    if not isinstance(manifest, dict):
        raise ValueError("H3 chapter delivery requires a chain manifest.")
    if manifest.get("format") == CHAPTER_MANIFEST_FORMAT:
        chapter = manifest.get("chapter") or {}
        selected = int(chapter.get("number", 0))
        requested = int(chapter_number)
        if requested not in (0, selected):
            raise ValueError(
                "This input contains only Chapter %d. Connect the full Run "
                "manifest to select Chapter %d." % (selected, requested))
        _validate_manifest(manifest)
        if not persist:
            return _json_document(manifest), ""
        snapshot, path = _persist_chapter_manifest(manifest)
        return snapshot, path
    if manifest.get("format") not in (
            "h3_chain_manifest_v3", "h3_chain_partial_manifest_v3"):
        raise ValueError(
            "H3 chapter delivery requires a generated or partial H3 manifest.")
    segments = list(manifest.get("segments") or [])
    start, last_completed = _manifest_segment_bounds(
        manifest, segments, "H3 chapter delivery")
    if start != 1:
        raise ValueError(
            "Select another chapter from the original full Run manifest.")
    editorial = _manifest_editorial(manifest)
    planned = max(
        last_completed,
        int(manifest.get("planned_clip_count", 0) or 0),
        *(int(item.get("scene", 0))
          for item in editorial.get("scene_order", [])
          if isinstance(item, dict)))
    ranges = _editorial_chapter_ranges(editorial, planned)
    requested = int(chapter_number)
    if requested == 0:
        chapter = next((item for item in ranges
                        if int(item["start_scene"]) <= last_completed
                        <= int(item["end_scene"])), None)
        if chapter is None:
            raise ValueError(
                "No chapter contains the last generated scene %d."
                % last_completed)
    else:
        chapter = next((item for item in ranges
                        if int(item["number"]) == requested), None)
        if chapter is None:
            raise ValueError(
                "Chapter %d does not exist; this Plan defines %d chapter(s)." %
                (requested, len(ranges)))
    chapter_start = int(chapter["start_scene"])
    planned_end = int(chapter["end_scene"])
    chapter_end = min(planned_end, last_completed)
    if chapter_start > last_completed:
        raise ValueError(
            "Chapter %d has no generated scenes yet: it starts at scene %d, "
            "but the manifest contains scenes only through %d." %
            (int(chapter["number"]), chapter_start, last_completed))
    by_index = {int(item["index"]): item for item in segments}
    selected = [by_index[index] for index in range(chapter_start, chapter_end + 1)
                if index in by_index]
    if len(selected) != chapter_end - chapter_start + 1:
        raise ValueError(
            "Chapter %d is missing one or more saved scenes." %
            int(chapter["number"]))
    source_start = sum(
        int(item.get("delivered_frames", 0)) for item in segments
        if int(item.get("index", 0)) < chapter_start)
    scoped_editorial, editorial_origin = _chapter_scoped_editorial(
        _strict_run_name(manifest.get("run_name")), selected, editorial,
        chapter, timeline_segments=segments)
    total_frames = sum(int(item.get("delivered_frames", 0))
                       for item in selected)
    chapter_record = dict(chapter)
    chapter_record.update({
        "end_scene": chapter_end,
        "planned_end_scene": planned_end,
        "complete": chapter_end == planned_end,
        "editorial_origin_frame": editorial_origin,
        "source_start_frame": source_start,
        "source_editorial_revision": str(editorial.get("revision") or ""),
    })
    resolution = common_saved_resolution(selected, "Chapter export")
    if resolution:
        chapter_record["resolution"] = resolution
    scoped = {
        "format": CHAPTER_MANIFEST_FORMAT,
        "run_name": _strict_run_name(manifest.get("run_name")),
        "plan_hash": manifest.get("plan_hash"),
        "prompt_prefix": str(manifest.get("prompt_prefix") or ""),
        "compatibility": _json_document(manifest.get("compatibility")) or {},
        "clip_count": len(selected),
        "source_scene_count": int(manifest.get("source_scene_count") or
                                  manifest.get("planned_clip_count") or planned),
        "scene_start": chapter_start,
        "scene_end": chapter_end,
        "total_delivered_frames": total_frames,
        "duration_seconds": total_frames / float(FPS),
        "segments": [_json_document(item) for item in selected],
        "chapter": chapter_record,
        "editorial": scoped_editorial,
        "source_manifest_format": manifest.get("format"),
        "source_plan_hash": manifest.get("plan_hash"),
        "source_manifest_hash": _fingerprint(manifest),
        "archives": _json_document(manifest.get("archives")) or {},
    }
    if resolution:
        scoped["compatibility"].update(resolution)
    if chapter_start == 1 and isinstance(manifest.get("prelude"), dict):
        scoped["prelude"] = _json_document(manifest["prelude"])
    if isinstance(manifest.get("source_timeline"), dict):
        scoped["source_timeline"] = _json_document(
            manifest["source_timeline"])
    _validate_manifest(scoped)
    if not persist:
        return scoped, ""
    snapshot, path = _persist_chapter_manifest(scoped)
    return snapshot, path


def _load_chapter_manifest(
        run_name: Any, chapter_number: int,
        snapshot_id: str = "") -> tuple[dict[str, Any], str]:
    """Load one immutable chapter snapshot without requiring the old workflow."""
    normalized = _strict_run_name(run_name)
    number = int(chapter_number)
    if number < 1 or number > MAX_SHOTS:
        raise ValueError("Choose a chapter number between 1 and %d." % MAX_SHOTS)
    requested = str(snapshot_id or "").strip().lower()
    if requested and re.fullmatch(r"[0-9a-f]{32}", requested) is None:
        raise ValueError("Chapter manifest id must be blank or 32 hexadecimal digits.")
    chapters_root = os.path.realpath(os.path.join(
        _run_dir({"run_name": normalized}), "chapters"))
    candidates: list[tuple[int, str]] = []
    if os.path.isdir(chapters_root):
        prefix = "%02d_" % number
        for directory_name in os.listdir(chapters_root):
            if not directory_name.startswith(prefix):
                continue
            manifest_root = os.path.realpath(os.path.join(
                chapters_root, directory_name, "manifests"))
            if (not os.path.isdir(manifest_root)
                    or os.path.commonpath([
                        chapters_root, manifest_root
                    ]) != chapters_root):
                continue
            for filename in os.listdir(manifest_root):
                match = re.fullmatch(r"([0-9a-f]{32})\.json", filename)
                if match is None or (requested and match.group(1) != requested):
                    continue
                path = os.path.realpath(os.path.join(manifest_root, filename))
                if (os.path.commonpath([manifest_root, path]) != manifest_root
                        or not os.path.isfile(path)):
                    continue
                candidates.append((os.stat(path).st_mtime_ns, path))
    if not candidates:
        suffix = " snapshot %s" % requested if requested else ""
        raise FileNotFoundError(
            "No sealed Chapter %d%s exists for Run %s." %
            (number, suffix, normalized))
    _mtime, path = max(candidates, key=lambda item: (item[0], item[1]))
    manifest = _read_json(path)
    file_snapshot_id = os.path.splitext(os.path.basename(path))[0]
    if (not isinstance(manifest, dict)
            or manifest.get("format") != CHAPTER_MANIFEST_FORMAT
            or str(manifest.get("run_name") or "") != normalized
            or int((manifest.get("chapter") or {}).get("number", 0)) != number
            or _chapter_manifest_digest(manifest) !=
               str(manifest.get("chapter_manifest_id") or "")
            or str(manifest.get("chapter_manifest_id") or "") !=
               file_snapshot_id
            or str(manifest.get("chapter_manifest_path") or "") !=
               _relative_output_path(path)):
        raise ValueError("Sealed H3 chapter manifest failed its identity check.")
    _validate_manifest(manifest)
    return manifest, path


def _saved_scene_prefix_length(plan: dict[str, Any]) -> int:
    """Return the contiguous active checkpoint prefix available for recovery.

    Segment Save publishes one canonical metadata pointer only after all of a
    scene's immutable artifacts are durable.  Recovery can therefore discover
    an interrupted run without opening every large checkpoint up front.  The
    selected prefix is still passed through ``_load_resume_state`` below,
    which performs the authoritative history, artifact, and SHA-256 checks.
    """
    active, _stale = CheckpointGraphManager(_output_root()).active_selection(
        plan["run_name"])
    saved = 0
    for index in range(1, len(plan["shots"]) + 1):
        if index not in active:
            break
        saved = index
    return saved


def _write_next_scene_handoff(plan: dict[str, Any], index: int,
                              end_clip: int,
                              next_segment: dict[str, Any]) -> dict[str, Any]:
    """Write the lightweight durable next-scene handoff for requeue mode.

    Called after the scene N checkpoint/segment transaction has completed
    (Segment Save), immediately before Loop End stops instead of recursively
    expanding scene N+1.  The record carries only identity values (run name,
    scene numbers, seed, revision/checkpoint SHA, Plan fingerprint) so the
    frontend can later claim it and queue the SAME workflow as a new
    top-level prompt.  The Plan JSON is never touched.

    Idempotent per committed transition, not merely per destination scene.
    A rerender with a new predecessor revision/checkpoint/range gets a new
    record; an exact Loop End retry gets the same record.  Terminal history
    is never reset or reused as new work.
    """
    run_name = str(plan.get("run_name") or "")
    next_scene = int(index) + 1
    paths = _artifact_paths(plan, index)
    checkpoint_sha = None
    if os.path.isfile(paths["metadata"]):
        try:
            checkpoint_sha = _file_sha256(paths["metadata"])
        except OSError:
            checkpoint_sha = None

    shot = plan["shots"][next_scene - 1]
    revision = str(next_segment.get("revision")
                   or checkpoint_revision_token(index, next_segment) or "")
    # The digest is a durable transition identity.  It includes every value
    # that can make a continuation semantically different while avoiding any
    # Plan/tensor payload in the handoff itself.
    transition_key = hashlib.sha256(json.dumps({
        "predecessor": int(index), "next": next_scene,
        "revision": revision, "checkpoint": checkpoint_sha,
        "workflow": str(plan.get("plan_hash") or ""),
        "end": int(end_clip),
        **({"working_branch_id": plan["_branch_id"]} if plan.get("_branch_id") else {}),
    }, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()
    handoff_id = "next_scene_%04d_%s" % (next_scene, transition_key[:16])
    store = _HandoffStore(_output_root())
    try:
        return store.load(run_name, handoff_id)
    except _HandoffNotFoundError:
        pass
    return store.create(
        run_name, action="next_scene",
        scene=next_scene, start_clip=next_scene, end_clip=int(end_clip),
        seed=int(shot["seed"]),
        source_revision=revision,
        source_checkpoint_sha256=checkpoint_sha,
        workflow_fingerprint=str(plan.get("plan_hash") or ""),
        predecessor_scene=int(index), transition_key=transition_key,
        handoff_id=handoff_id, working_branch_id=plan.get("_branch_id", "main"))


class MiniMaxH3ChainLoopEnd:
    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {
                "flow": (FLOW_TYPE, {
                    "rawLink": True,
                    "tooltip": "Connect DIRECTLY from Loop Start's flow "
                               "output. This raw link defines the recursive body "
                               "that Loop End clones for later scenes."}),
                "state": (STATE_TYPE, {
                    "tooltip": "Current state from Current Shot. Loop End adds "
                               "the accepted segment and advances its scene "
                               "index."}),
                "images": ("IMAGE", {
                    "tooltip": "Delivered current-scene images after Motion "
                               "Context Trim. Their tail becomes the next "
                               "scene's visual context."}),
                "sampled_latent": ("LATENT", {
                    "tooltip": "Current sampler output. Its AV streams become "
                               "the next scene's generated-audio context when "
                               "the selected audio mode requires it."}),
                "segment": (SEGMENT_TYPE, {
                    "tooltip": "Approved persisted segment from Review Gate, "
                               "or directly from Segment Save when no review is "
                               "wanted."}),
            },
            "optional": {
                "between_scene_cleanup": (list(LOOP_MEMORY_POLICIES), {
                    "default": "off",
                    "tooltip": "Runtime-only memory policy applied after a "
                               "scene is safely checkpointed and before the "
                               "next scene or retry starts. off keeps ComfyUI "
                               "caches; unload_models releases loaded weights "
                               "from VRAM; fresh_scene first requests active "
                               "RAM-pressure-cache eviction and Python garbage "
                               "collection, then releases remaining pinned "
                               "model pages, unloads models, and empties the "
                               "CUDA allocator. fresh_scene may "
                               "reload model/reference nodes and is best for "
                               "model-switching chains. ComfyUI has no safe "
                               "full executor reset inside a running recursive "
                               "prompt, so the small live loop carry remains."}),
                "execution_mode": (list(LOOP_EXECUTION_MODES), {
                    "default": "recursive",
                    "tooltip": "How the next scene is scheduled. "
                               "recursive expands the next scene inside "
                               "the same top-level prompt. top_level_requeue "
                               "ends the loop iteration after the accepted "
                               "scene is checkpointed and writes a durable "
                               "handoff. With frontend auto-requeue enabled, "
                               "the next scene starts in a new top-level "
                               "prompt after the current prompt succeeds and "
                               "the queue/cleanup checks pass. Loop Start "
                               "resumes from the accepted checkpoint lineage. "
                               "Errors and interruptions do not auto-queue; "
                               "pending handoffs can be resumed or cancelled "
                               "manually. Stored on this node, not in Plan JSON."}),
            },
            "hidden": {
                "dynprompt": "DYNPROMPT",
                "unique_id": "UNIQUE_ID",
            },
        }

    @classmethod
    def VALIDATE_INPUTS(cls, execution_mode="recursive"):
        # Accept old API/workflow values without listing the old label in the UI.
        if execution_mode not in (*LOOP_EXECUTION_MODES, "recursive_legacy"):
            return "execution_mode must be recursive or top_level_requeue."
        return True

    RETURN_TYPES = (MANIFEST_TYPE, "STRING", "IMAGE", "LATENT")
    RETURN_NAMES = ("manifest", "manifest_json", "last_context_frames",
                    "last_context_latent")
    OUTPUT_TOOLTIPS = (
        "Completed chain manifest for H3 Chain Assemble. Produced only when "
        "the final scene is accepted.",
        "Human-readable JSON form of the completed manifest.",
        "Delivered tail frames from the final scene for optional chaining into "
        "another workflow.",
        "Final sampled H3 AV latent for optional continuation outside this loop.",
    )
    FUNCTION = "end"
    CATEGORY = "conditioning/minimax/context_loop"
    DESCRIPTION = ("Finish one persisted clip, carry only its context tail and "
                   "AV latent, then continue within the same prompt or write "
                   "a handoff for the next top-level prompt.")

    def _explore_dependencies(self, node_id: str, dynprompt: Any,
                              upstream: dict[str, list[str]],
                              parent_ids: list[str]) -> None:
        node_info = dynprompt.get_node(node_id)
        for value in node_info.get("inputs", {}).values():
            if not is_link(value):
                continue
            parent_id = value[0]
            display_id = dynprompt.get_display_node_id(parent_id)
            display_node = dynprompt.get_node(display_id)
            if display_node["class_type"] != "MiniMaxH3ChainLoopEnd":
                parent_ids.append(display_id)
            if parent_id not in upstream:
                upstream[parent_id] = []
                self._explore_dependencies(parent_id, dynprompt, upstream,
                                           parent_ids)
            upstream[parent_id].append(node_id)

    def _explore_output_nodes(self, dynprompt: Any,
                              upstream: dict[str, list[str]],
                              parent_ids: list[str]) -> None:
        try:
            import nodes as comfy_nodes
            mappings = comfy_nodes.NODE_CLASS_MAPPINGS
        except Exception:
            return
        output_nodes: dict[str, Any] = {}
        for node_id, node in dynprompt.get_original_prompt().items():
            class_def = mappings.get(node.get("class_type"))
            if not class_def or not getattr(class_def, "OUTPUT_NODE", False):
                continue
            for value in node.get("inputs", {}).values():
                if is_link(value):
                    output_nodes[node_id] = value
        for parent_id in list(upstream):
            display_id = dynprompt.get_display_node_id(parent_id)
            for output_id, link in output_nodes.items():
                linked_id = link[0]
                if (linked_id in parent_ids and display_id == linked_id and
                        output_id not in upstream[parent_id]):
                    if "." in parent_id:
                        parts = parent_id.split(".")
                        parts[-1] = output_id
                        upstream[parent_id].append(".".join(parts))
                    else:
                        upstream[parent_id].append(output_id)

    def _collect_contained(self, node_id: str,
                           upstream: dict[str, list[str]],
                           contained: dict[str, bool]) -> None:
        for child_id in upstream.get(node_id, []):
            if child_id in contained:
                continue
            contained[child_id] = True
            self._collect_contained(child_id, upstream, contained)

    def _recurse(self, flow, next_state, dynprompt, unique_id):
        if GraphBuilder is None:
            raise RuntimeError("H3 Chain Loop requires ComfyUI GraphBuilder.")
        unique_id = str(unique_id)
        upstream: dict[str, list[str]] = {}
        parent_ids: list[str] = []
        self._explore_dependencies(unique_id, dynprompt, upstream, parent_ids)
        parent_ids = list(set(parent_ids))
        self._explore_output_nodes(dynprompt, upstream, parent_ids)

        open_node = str(flow[0])
        start_info = dynprompt.get_node(open_node)
        if start_info["class_type"] != "MiniMaxH3ChainLoopStart":
            raise ValueError("H3 Chain Loop End must receive flow from H3 Chain Loop Start.")
        contained: dict[str, bool] = {unique_id: True, open_node: True}
        self._collect_contained(open_node, upstream, contained)

        graph = GraphBuilder()
        for node_id in contained:
            original = dynprompt.get_node(node_id)
            clone_id = "Recurse" if node_id == unique_id else node_id
            node = graph.node(original["class_type"], clone_id)
            node.set_override_display_id(node_id)
        for node_id in contained:
            original = dynprompt.get_node(node_id)
            clone_id = "Recurse" if node_id == unique_id else node_id
            node = graph.lookup_node(clone_id)
            for key, value in original.get("inputs", {}).items():
                if is_link(value) and value[0] in contained:
                    parent = graph.lookup_node(value[0])
                    node.set_input(key, parent.out(value[1]))
                else:
                    node.set_input(key, value)
        graph.lookup_node(open_node).set_input("initial_state", next_state)
        # The imported source may contain thousands of decoded frames. Once
        # Loop Start has reduced it to typed state, recursive iterations must
        # not keep the adapter dependency alive or prepare the prelude again.
        if "external_context" in start_info.get("inputs", {}):
            graph.lookup_node(open_node).set_input("external_context", None)
        if "source_timeline" in start_info.get("inputs", {}):
            graph.lookup_node(open_node).set_input("source_timeline", None)
        recurse = graph.lookup_node("Recurse")
        return {
            "result": tuple(recurse.out(index)
                            for index in range(len(self.RETURN_TYPES))),
            "expand": graph.finalize(),
        }

    def end(self, flow, state, images, sampled_latent, segment,
            between_scene_cleanup="off", execution_mode="recursive",
            dynprompt=None, unique_id=None):
        validation = self.VALIDATE_INPUTS(execution_mode)
        if validation is not True:
            raise ValueError(validation)
        if execution_mode == "recursive_legacy":
            execution_mode = "recursive"
        plan = state["plan"]
        _require_plan_write(plan, "advance or finish the scene loop")
        index = int(state["index"])
        if int(segment.get("index", -1)) != index:
            raise ValueError("H3 Chain End received the wrong segment for clip %d."
                             % index)
        review = segment.get("_h3_review_decision")
        if isinstance(review, dict) and review.get("action") == "retry":
            revised_plan = _plan_with_review_revision(
                plan, index, review.get("scene_prompt", ""),
                int(review.get("seed", plan["shots"][index - 1]["seed"])),
                int(review.get(
                    "raw_frames", plan["shots"][index - 1]["raw_frames"])))
            retry_state = dict(state)
            retry_state["plan"] = revised_plan
            candidate_batch = review.get("candidate_batch")
            if isinstance(candidate_batch, dict):
                retry_state["candidate_batch"] = candidate_batch
            else:
                retry_state.pop("candidate_batch", None)
            # Keep the predecessor context and accepted segment list unchanged.
            # Segment Save makes the new take active when this index completes
            # again while retaining the rejected take as an immutable revision.
            expansion = self._recurse(
                flow, retry_state, dynprompt, unique_id)
            # Drop the rejected scene's live tensors before cache eviction so
            # soft_empty_cache can release their allocator blocks as well.
            del images, sampled_latent, segment, state
            _release_loop_boundary_resources(
                between_scene_cleanup, index)
            return expansion
        selected_frames = images
        selected_latent = sampled_latent
        if (isinstance(review, dict)
                and review.get("action") == "candidate_selected"):
            selected_plan = review.get("plan")
            selected_frames = review.get("context_frames")
            selected_latent = review.get("sampled_latent")
            if (not isinstance(selected_plan, dict) or selected_frames is None
                    or not isinstance(selected_latent, dict)):
                raise ValueError(
                    "Selected H3 candidate is missing its continuation state.")
            plan = selected_plan
        alternate_take = _alternate_take_descriptor(plan)
        if alternate_take is not None:
            public_alternate = _public_segment(segment)
            # Publishing the alternate updates final-cut state. Recheck at
            # that commit boundary in case ownership changed after this Loop
            # End invocation began.
            with checkpoint_run_lock(
                    _output_root(), plan["run_name"]), project_write_guard(
                        _output_root(), plan["run_name"],
                        plan.get("_project_ownership"),
                        "publish an accepted alternate take"):
                editorial = _select_editorial_alternate(plan, public_alternate)
                values = list(state.get("segments", [])) + [public_alternate]
                manifest = _manifest_from_segments(plan, values, complete=False)
                manifest["format"] = "h3_chain_alternate_manifest_v1"
                manifest["alternate_take"] = _json_document(alternate_take)
                manifest["editorial_replacement"] = next(
                    item for item in editorial["replacements"]
                    if int(item["scene"]) == index)
                alternate_dir = os.path.join(_run_dir(plan), "alternates")
                os.makedirs(alternate_dir, exist_ok=True)
                manifest_path = os.path.join(
                    alternate_dir, "scene_%04d.%s.manifest.json" %
                    (index, str(segment["revision"])))
                _atomic_json(manifest_path, manifest)
            manifest_json = json.dumps(
                manifest, ensure_ascii=False, indent=2, sort_keys=True)
            context_length = min(
                _plan_context_storage_length(plan), int(selected_frames.shape[0]))
            return (
                manifest, manifest_json,
                _tensor_cpu_clone(
                    selected_frames[:0] if context_length == 0 else
                    selected_frames[-context_length:]),
                _compact_latent(selected_latent),
            )
        editorial = _load_run_editorial(plan.get("run_name"))
        next_segment = _editorial_trimmed_segment(
            _public_segment(segment), editorial)
        if "_editorial_out_frames" in next_segment:
            selected_frames = selected_frames[
                :int(next_segment["_editorial_out_frames"])]
            selected_latent = _editorial_trim_latent(
                selected_latent, next_segment)
            _LOG.info(
                "H3 Chain scene %d continuation now ends at latent-safe "
                "editorial frame %d/%d; the complete checkpoint remains "
                "unchanged.", index,
                int(next_segment["_editorial_out_frames"]),
                int(next_segment["delivered_frames"]))
        context_length = min(
            _plan_context_storage_length(plan), int(selected_frames.shape[0]))
        next_state = {
            "plan": plan,
            "index": index + 1,
            "range_start": int(state.get("range_start", 1)),
            "end_clip": int(state.get("end_clip", len(plan["shots"]))),
            # clone: a tensor view would retain the entire decoded clip
            "previous_frames": _tensor_cpu_clone(
                selected_frames[-context_length:]),
            "previous_latent": _compact_latent(selected_latent),
            "segments": list(state.get("segments", [])) +
                        [next_segment],
            "resumed_from": state.get("resumed_from", 0),
        }
        if state.get("source_timeline") is not None:
            next_state["source_timeline"] = state["source_timeline"]
        end_clip = int(next_state["end_clip"])
        if index < end_clip:
            if execution_mode == "top_level_requeue":
                # Scene N is checkpointed; do NOT expand the next H3 scene
                # inside this top-level prompt. Persist the lightweight
                # durable handoff first (the checkpoint transaction already
                # completed in Segment Save), then stop with a partial
                # manifest so this prompt can reach terminal success. The
                # frontend later queues the SAME workflow as a new top-level
                # prompt and Loop Start resumes the same Plan at scene
                # N+1 from the accepted checkpoint lineage.
                handoff = _write_next_scene_handoff(
                    plan, index, end_clip, next_segment)
                del selected_frames, selected_latent
                del images, sampled_latent, segment, state
                _release_loop_boundary_resources(
                    between_scene_cleanup, index)
                manifest = _manifest_from_segments(
                    plan, next_state["segments"], complete=False)
                if os.path.isdir(_run_dir(plan)):
                    manifest_path = os.path.join(
                        _run_dir(plan), "partial",
                        "through_clip_%04d.manifest.json" % index)
                    _atomic_json(manifest_path, manifest)
                manifest_json = json.dumps(
                    manifest, ensure_ascii=False, indent=2, sort_keys=True)
                _LOG.info(
                    "H3 Chain %s scene %d checkpointed in top-level "
                    "requeue mode; next scene deferred to handoff %s "
                    "(new top-level prompt required).",
                    plan["run_name"], index, handoff["handoff_id"])
                result = (manifest, manifest_json,
                          next_state["previous_frames"],
                          next_state["previous_latent"])
                completion = {key: handoff[key] for key in (
                    "run_name", "predecessor_scene", "scene", "end_clip",
                    "workflow_fingerprint", "handoff_id", "source_revision",
                    "source_checkpoint_sha256", "transition_key")}
                return {"result": result, "ui": {
                    "h3_chain_top_level_requeue": [completion]}}

            expansion = self._recurse(
                flow, next_state, dynprompt, unique_id)
            # The recursive state owns independent CPU clones. Release this
            # iteration's full-resolution arguments before emptying caches.
            del selected_frames, selected_latent
            del images, sampled_latent, segment, state
            _release_loop_boundary_resources(
                between_scene_cleanup, index)
            return expansion

        complete = end_clip == len(plan["shots"])
        manifest = _manifest_from_segments(
            plan, next_state["segments"], complete=complete)
        # A normal chain has already created its run directory in Segment Save.
        # Keeping this conditional also permits lightweight/custom segment sinks
        # that deliberately do not use the disk-backed saver.
        if os.path.isdir(_run_dir(plan)):
            if complete:
                manifest_path = _manifest_path(plan)
            else:
                manifest_path = os.path.join(
                    _run_dir(plan), "partial",
                    "through_clip_%04d.manifest.json" % end_clip)
            # Recursive execution and cleanup can leave a sizeable interval
            # between the entry check and final manifest publication.
            with _project_write_commit_guard(
                    plan["run_name"], plan.get("_project_ownership"),
                    "publish the scene-loop manifest"):
                _atomic_json(manifest_path, manifest)
        manifest_json = json.dumps(manifest, ensure_ascii=False, indent=2,
                                   sort_keys=True)
        return (manifest, manifest_json, next_state["previous_frames"],
                next_state["previous_latent"])


class MiniMaxH3ChainManifestLoad:
    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {
                "plan": (PLAN_TYPE, {
                    "tooltip": "The same validated H3 Chain Plan used for the "
                               "original render. Plan and generation "
                               "fingerprints are checked against every saved "
                               "scene."}),
            },
            "optional": {
                "source_audio": ("AUDIO", {
                    "tooltip": "The original full source track when the plan "
                               "selects final source audio or enables Source "
                               "reference. Its "
                               "fingerprint must match the saved checkpoints."}),
                "external_context": (EXTERNAL_CONTEXT_TYPE, {
                    "tooltip": "Reconnect the same Existing Video Context used "
                               "for scene 1. Its tail fingerprint restores the "
                               "correct resume contract and its persisted "
                               "prelude remains available to Assemble."}),
                "source_timeline": (SOURCE_TIMELINE_TYPE, {
                    "tooltip": "Primary 0.5 recovery route. Reconnect the "
                               "same Source Timeline, or leave blank when its "
                               "path-backed descriptor is already stored on "
                               "the managed Plan."}),
            },
        }

    RETURN_TYPES = (MANIFEST_TYPE, "STRING", "STRING")
    RETURN_NAMES = ("manifest", "manifest_json", "status")
    OUTPUT_TOOLTIPS = (
        "Verified completed or partial manifest reconstructed from the "
        "longest contiguous saved scene prefix; connect to H3 Chain Assemble.",
        "Human-readable JSON form of the reconstructed manifest.",
        "Number of verified scenes and checkpoint directory used.",
    )
    FUNCTION = "load"
    CATEGORY = "conditioning/minimax/context_loop"
    DESCRIPTION = ("Validate the longest contiguous saved scene prefix and "
                   "rebuild a completed or partial chain manifest without "
                   "rerendering.")

    @classmethod
    def IS_CHANGED(cls, *args, **kwargs):
        return float("NaN")

    def load(self, plan, source_audio=None, external_context=None,
             source_timeline=None):
        prepared_plan = _plan_with_external_context(plan, external_context)
        runtime_timeline = None
        if source_timeline is None and isinstance(
                plan.get("source_timeline"), dict):
            source_timeline = _source_timeline_from_recovery(
                plan["source_timeline"])
        if source_timeline is not None and source_audio is not None:
            raise ValueError(
                "H3 Chain Manifest Load accepts Source Timeline or legacy "
                "source_audio, not both.")
        if source_timeline is not None:
            prepared_plan, runtime_timeline = _plan_with_source_timeline(
                prepared_plan, source_timeline)
        else:
            prepared_plan, runtime_timeline = (
                _plan_with_recoverable_legacy_source_audio(
                    prepared_plan, source_audio))
        saved_count = _saved_scene_prefix_length(prepared_plan)
        if saved_count < 1:
            raise FileNotFoundError(
                "H3 Chain Manifest Load found no saved scenes for run %s in %s."
                % (prepared_plan["run_name"], _run_dir(prepared_plan)))
        recovered = _load_resume_state(
            prepared_plan, saved_count + 1,
            source_timeline=runtime_timeline,
            source_audio=source_audio if runtime_timeline is None else None)
        complete = saved_count == len(prepared_plan["shots"])
        manifest = _manifest_from_segments(
            prepared_plan, recovered["segments"], complete=complete)
        if complete:
            manifest_path = _manifest_path(prepared_plan)
            kind = "completed"
        else:
            manifest_path = os.path.join(
                _run_dir(prepared_plan), "partial",
                "through_clip_%04d.manifest.json" % saved_count)
            kind = "partial"
        manifest_persisted = True
        try:
            with _project_write_commit_guard(
                    prepared_plan["run_name"],
                    prepared_plan.get("_project_ownership"),
                    "rewrite a reconstructed recovery manifest"):
                _atomic_json(manifest_path, manifest)
        except ProjectOwnershipError:
            # Recovery inspection and export remain safe from a non-owner.
            # Return the verified in-memory manifest without letting a stale
            # workflow change even this derived project file.
            manifest_persisted = False
        manifest_json = json.dumps(
            manifest, ensure_ascii=False, indent=2, sort_keys=True)
        status = "loaded and verified %s manifest through clip %d/%d from %s" % (
            kind, saved_count, len(prepared_plan["shots"]),
            _run_dir(prepared_plan))
        if not manifest_persisted:
            status += "; read-only workflow, disk manifest left unchanged"
        return (manifest, manifest_json, status)


class MiniMaxH3ChainChapterDelivery:
    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {
                "manifest": (MANIFEST_TYPE, {
                    "tooltip": "Full or partial manifest from Loop End, "
                               "Manifest Load, or Checkpoint Manager."}),
                "enabled": ("BOOLEAN", {
                    "default": True,
                    "tooltip": "On seals and outputs one chapter. Off passes "
                               "the complete incoming Run manifest through for "
                               "the traditional ever-growing final."}),
                "chapter_number": ("INT", {
                    "default": 0, "min": 0, "max": MAX_SHOTS,
                    "tooltip": "0 selects the chapter containing the last "
                               "generated scene. Use 1, 2, 3, and so on to "
                               "export a particular chapter. Unfinished "
                               "chapters export their generated scenes now; "
                               "later exports can include new scenes."}),
            },
        }

    RETURN_TYPES = (MANIFEST_TYPE, "STRING", "INT", "STRING", "STRING")
    RETURN_NAMES = ("delivery_manifest", "manifest_json", "chapter_number",
                    "chapter_manifest_path", "status")
    OUTPUT_TOOLTIPS = (
        "Selected immutable chapter manifest, or the full input when disabled.",
        "Human-readable delivery manifest JSON.",
        "Resolved chapter number; zero when chapter delivery is disabled.",
        "Immutable recovery manifest path for the sealed chapter.",
        "Selected chapter range, snapshot id, and recovery location.",
    )
    FUNCTION = "select"
    CATEGORY = "conditioning/minimax/context_loop"
    DESCRIPTION = (
        "Turn Plan Studio chapter markers into immutable delivery units. Each "
        "snapshot includes the available scenes, even before the chapter is "
        "finished, with their exact checkpoint lineage and editorial state, and "
        "routes every downstream MP4, PNG/WAV, or full-chain upscale export "
        "into a separate chapter folder. Disable it for a whole-Run final.")

    @classmethod
    def IS_CHANGED(cls, *args, **kwargs):
        return float("NaN")

    def select(self, manifest, enabled=True, chapter_number=0):
        if not bool(enabled):
            document = _json_document(manifest)
            if not isinstance(document, dict):
                raise ValueError("H3 Chapter Delivery requires a manifest.")
            status = "chapter delivery disabled; passing through the full Run"
            return (document, json.dumps(
                document, ensure_ascii=False, indent=2, sort_keys=True),
                0, "", status)
        chapter_manifest, path = _chapter_manifest_from_manifest(
            manifest, int(chapter_number))
        chapter = chapter_manifest["chapter"]
        status = (
            "saved Chapter %d %r, scenes %d:%d, snapshot %s -> %s" %
            (int(chapter["number"]), str(chapter["title"]),
             int(chapter["start_scene"]), int(chapter["end_scene"]),
             str(chapter_manifest["chapter_manifest_id"])[:8], path))
        if not chapter.get("complete", True):
            status += "; partial chapter, planned through scene %d" % int(
                chapter["planned_end_scene"])
        return (
            chapter_manifest,
            json.dumps(chapter_manifest, ensure_ascii=False, indent=2,
                       sort_keys=True),
            int(chapter["number"]), path, status)


class MiniMaxH3ChainChapterLoad:
    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {
                "run_name": ("STRING", {
                    "default": "h3_chain",
                    "tooltip": "Exact Run name containing the sealed chapter."}),
                "chapter_number": ("INT", {
                    "default": 1, "min": 1, "max": MAX_SHOTS,
                    "tooltip": "Chapter to recover independently."}),
                "chapter_manifest_id": ("STRING", {
                    "default": "",
                    "tooltip": "Blank loads the newest immutable snapshot for "
                               "this chapter. Paste a complete 32-character id "
                               "to recover a particular older chapter final."}),
            },
        }

    RETURN_TYPES = (MANIFEST_TYPE, "STRING", "STRING", "STRING")
    RETURN_NAMES = ("chapter_manifest", "manifest_json",
                    "chapter_manifest_path", "status")
    OUTPUT_TOOLTIPS = (
        "Verified immutable chapter manifest for any finishing node.",
        "Human-readable recovered chapter manifest JSON.",
        "Absolute path of the selected immutable chapter snapshot.",
        "Recovered chapter range and snapshot id.",
    )
    FUNCTION = "load"
    CATEGORY = "conditioning/minimax/context_loop"
    DESCRIPTION = (
        "Recover one sealed chapter without loading or extending the rest of "
        "the Run. Blank snapshot id selects the newest saved version; an exact "
        "id restores an older chapter delivery non-destructively.")

    @classmethod
    def IS_CHANGED(cls, *args, **kwargs):
        return float("NaN")

    def load(self, run_name, chapter_number, chapter_manifest_id=""):
        manifest, path = _load_chapter_manifest(
            run_name, int(chapter_number), chapter_manifest_id)
