def _run_ffmpeg_capture(
        command: list[str], timeout_seconds: float | None = None) -> bytes:
    try:
        result = subprocess.run(
            command, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
            timeout=timeout_seconds)
    except subprocess.TimeoutExpired as exc:
        raise RuntimeError(
            "ffmpeg timed out after %.1f seconds" %
            float(timeout_seconds)) from exc
    except OSError as exc:
        executable = str(command[0]) if command else "ffmpeg"
        raise RuntimeError(
            "ffmpeg could not start (%s): %s" % (executable, exc)) from exc
    if result.returncode:
        detail = result.stderr.decode(
            "utf-8", errors="replace").splitlines()[-20:]
        raise RuntimeError(
            "ffmpeg failed (%d):\n%s" %
            (int(result.returncode), "\n".join(detail)))
    return bytes(result.stdout)


def _build_plan_studio_source_waveform(
        record: dict[str, Any]) -> str:
    record = _validated_plan_studio_source_audio_record(record)
    output_path = _plan_studio_source_waveform_path(record)
    if os.path.isfile(output_path) and os.path.getsize(output_path) > 0:
        return output_path
    ffmpeg = _usable_ffmpeg()
    if ffmpeg is None:
        raise RuntimeError(
            "Plan Studio source waveform requires a working ffmpeg.")
    duration = int(record["frame_count"]) / float(FPS)
    command = [
        ffmpeg, "-hide_banner", "-loglevel", "error",
        "-ss", "%.9f" % float(record["audio_seek_seconds"]),
        "-i", str(record["audio_path"]),
        "-t", "%.9f" % duration,
        "-map", "0:a:0", "-vn",
        "-af", (
            "aformat=sample_fmts=flt:channel_layouts=mono,"
            "aeval=abs(val(0)),aresample=%d" %
            PLAN_STUDIO_WAVEFORM_SAMPLE_RATE),
        "-f", "f32le", "pipe:1",
    ]
    raw = _run_ffmpeg_capture(
        command, timeout_seconds=max(60.0, duration * 3.0))
    usable = len(raw) - len(raw) % 4
    values = (
        struct.unpack("<%df" % (usable // 4), raw[:usable])
        if usable else ())
    point_count = max(
        1, int(math.ceil(
            duration * PLAN_STUDIO_WAVEFORM_POINTS_PER_SECOND)))
    samples = []
    for index in range(point_count):
        start = int(math.floor(
            index * PLAN_STUDIO_WAVEFORM_SAMPLE_RATE /
            PLAN_STUDIO_WAVEFORM_POINTS_PER_SECOND))
        end = int(math.floor(
            (index + 1) * PLAN_STUDIO_WAVEFORM_SAMPLE_RATE /
            PLAN_STUDIO_WAVEFORM_POINTS_PER_SECOND))
        samples.append(max(values[start:min(end, len(values))], default=0.0))
    nonzero = sorted(value for value in samples if value > 1e-8)
    reference = (
        nonzero[min(len(nonzero) - 1, int(len(nonzero) * 0.98))]
        if nonzero else 1.0)
    normalized = [
        round(min(1.0, max(0.0, value / reference)), 4)
        for value in samples]
    payload = {
        "version": 1,
        "points_per_second": PLAN_STUDIO_WAVEFORM_POINTS_PER_SECOND,
        "frame_count": int(record["frame_count"]),
        "duration_seconds": duration,
        "samples": normalized,
    }
    temporary = "%s.%s.tmp" % (output_path, uuid.uuid4().hex)
    try:
        with open(temporary, "w", encoding="utf-8") as handle:
            handle.write(json.dumps(
                payload, ensure_ascii=False, separators=(",", ":")))
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, output_path)
    finally:
        _safe_unlink(temporary)
    return output_path


def _build_plan_studio_source_preview(record: dict[str, Any]) -> str:
    return _build_plan_studio_source_preview_unlocked(record)


def _build_plan_studio_source_preview_unlocked(
        record: dict[str, Any]) -> str:
    record = _validated_plan_studio_preview_record(record)
    output_path = _plan_studio_source_preview_path(record)
    if os.path.isfile(output_path) and os.path.getsize(output_path) > 0:
        return output_path
    ffmpeg = _usable_ffmpeg()
    if ffmpeg is None:
        raise RuntimeError(
            "Plan Studio source comparison requires a working ffmpeg.")
    temporary = "%s.%s.tmp.mp4" % (output_path, uuid.uuid4().hex)
    duration = int(record["frame_count"]) / float(FPS)
    command = [
        ffmpeg, "-hide_banner", "-loglevel", "error", "-y",
        "-ss", "%.9f" % float(record["video_seek_seconds"]),
        "-i", str(record["video_path"]),
    ]
    external_audio = (
        bool(record.get("audio_path")) and
        os.path.realpath(str(record["audio_path"])) !=
        os.path.realpath(str(record["video_path"])))
    if external_audio:
        command.extend([
            "-ss", "%.9f" % float(record["audio_seek_seconds"]),
            "-i", str(record["audio_path"]),
        ])
    command.extend([
        "-t", "%.9f" % duration,
        "-map", "0:v:0",
        "-vf", "fps=%d,scale=854:%d:force_original_aspect_ratio=decrease:"
               "force_divisible_by=2" % (FPS, PLAN_STUDIO_PREVIEW_MAX_HEIGHT),
        "-c:v", "libx264", "-preset", "veryfast", "-crf", "29",
        "-pix_fmt", "yuv420p", "-fps_mode", "cfr",
    ])
    if record.get("has_audio"):
        command.extend([
            "-map", "1:a:0?" if external_audio else "0:a:0?",
            "-af", "aresample=async=1:first_pts=0,apad",
            "-c:a", "aac", "-b:a", "64k", "-ac", "2",
        ])
    else:
        command.append("-an")
    command.extend(["-movflags", "+faststart", temporary])
    try:
        _run_ffmpeg(command, timeout_seconds=max(60.0, duration * 8.0))
        if not os.path.isfile(temporary) or os.path.getsize(temporary) < 1:
            raise RuntimeError("ffmpeg produced an empty source preview.")
        os.replace(temporary, output_path)
    finally:
        _safe_unlink(temporary)
    return output_path


def _plan_studio_preview_async_state(
        ) -> tuple[asyncio.Semaphore, dict[str, asyncio.Task[str]]]:
    """Return build coordination bound to ComfyUI's current event loop."""
    global _PLAN_STUDIO_PREVIEW_BUILD_LOOP
    global _PLAN_STUDIO_PREVIEW_BUILD_GATE
    global _PLAN_STUDIO_PREVIEW_BUILD_TASKS
    loop = asyncio.get_running_loop()
    if (_PLAN_STUDIO_PREVIEW_BUILD_LOOP is not loop or
            _PLAN_STUDIO_PREVIEW_BUILD_GATE is None):
        _PLAN_STUDIO_PREVIEW_BUILD_LOOP = loop
        _PLAN_STUDIO_PREVIEW_BUILD_GATE = asyncio.Semaphore(1)
        _PLAN_STUDIO_PREVIEW_BUILD_TASKS = {}
    gate = _PLAN_STUDIO_PREVIEW_BUILD_GATE
    assert gate is not None
    return gate, _PLAN_STUDIO_PREVIEW_BUILD_TASKS


async def _ensure_plan_studio_source_preview(
        record: dict[str, Any]) -> str:
    """Deduplicate preview work without parking worker threads on a lock."""
    path = _plan_studio_source_preview_path(record)
    if os.path.isfile(path) and os.path.getsize(path) > 0:
        return path
    gate, tasks = _plan_studio_preview_async_state()
    task = tasks.get(path)
    if task is None:
        async def build() -> str:
            async with gate:
                if os.path.isfile(path) and os.path.getsize(path) > 0:
                    return path
                started = time.monotonic()
                result = await asyncio.to_thread(
                    _build_plan_studio_source_preview_unlocked, dict(record))
                elapsed = time.monotonic() - started
                if elapsed >= 2.0:
                    _LOG.warning(
                        "Plan Studio source preview build took %.2fs (%d frames)",
                        elapsed, int(record.get("frame_count", 0)))
                return result

        task = asyncio.create_task(build())
        tasks[path] = task

        def finished(completed: asyncio.Task[str]) -> None:
            if tasks.get(path) is completed:
                tasks.pop(path, None)
            if completed.cancelled():
                return
            # Retrieve failures even when the initiating browser request was
            # canceled; other concurrent waiters still receive the exception.
            try:
                completed.exception()
            except Exception:
                pass

        task.add_done_callback(finished)
    # A browser abandoning one media element must not cancel the shared cache
    # fill still needed by the timeline or comparison player.
    return await asyncio.shield(task)


async def _ensure_plan_studio_source_waveform(
        record: dict[str, Any]) -> str:
    path = _plan_studio_source_waveform_path(record)
    if os.path.isfile(path) and os.path.getsize(path) > 0:
        return path
    gate, tasks = _plan_studio_preview_async_state()
    task = tasks.get(path)
    if task is None:
        async def build() -> str:
            async with gate:
                if os.path.isfile(path) and os.path.getsize(path) > 0:
                    return path
                return await asyncio.to_thread(
                    _build_plan_studio_source_waveform, dict(record))

        task = asyncio.create_task(build())
        tasks[path] = task

        def finished(completed: asyncio.Task[str]) -> None:
            if tasks.get(path) is completed:
                tasks.pop(path, None)
            if completed.cancelled():
                return
            try:
                completed.exception()
            except Exception:
                pass

        task.add_done_callback(finished)
    return await asyncio.shield(task)


def _plan_studio_source_audio_record(
        token: str) -> tuple[dict[str, Any] | None, str | None]:
    if not re.fullmatch(r"[A-Za-z0-9_-]{24,64}", token):
        return None, "Source audio token is invalid."
    _plan_studio_preview_cleanup()
    session = _PLAN_STUDIO_SOURCE_PREVIEWS.get(token)
    if session is None:
        return None, (
            "Source audio preview expired. Queue Plan Studio once to refresh it.")
    record = session.get("source_audio")
    if not isinstance(record, dict):
        return None, "No path-backed Source Timeline audio is available."
    try:
        record = _validated_plan_studio_source_audio_record(record)
    except (OSError, TypeError, ValueError):
        return None, "Source audio preview is outside ComfyUI media storage."
    session["created"] = time.monotonic()
    return record, None


async def _plan_studio_source_audio(request):
    token = str(request.query.get("token") or "")
    record, error = _plan_studio_source_audio_record(token)
    if record is None:
        return web.json_response(
            {"error": error}, status=400 if "invalid" in str(error) else 410)
    path = str(record["audio_path"])
    return web.FileResponse(path, headers={
        "Cache-Control": "private, max-age=21600, immutable",
    })


async def _plan_studio_source_waveform(request):
    token = str(request.query.get("token") or "")
    record, error = _plan_studio_source_audio_record(token)
    if record is None:
        return web.json_response(
            {"error": error}, status=400 if "invalid" in str(error) else 410)
    requested = request.query.get("frame_count")
    if requested not in (None, ""):
        try:
            requested_frames = int(requested)
        except (TypeError, ValueError):
            return web.json_response(
                {"error": "Source waveform frame_count must be an integer."},
                status=400)
        if requested_frames < 1 or requested_frames > 864000:
            return web.json_response({
                "error": (
                    "Source waveform frame_count must be between 1 and "
                    "864000.")}, status=400)
        # The registered source file is served whole. Let the editor request
        # waveform coverage for its longer editorial arrangement without
        # requiring Plan Studio to be queued again after every clip move.
        record = dict(record)
        available_frames = int(record.get(
            "available_frame_count", requested_frames))
        record["frame_count"] = max(
            int(record.get("frame_count", 0)),
            min(requested_frames, available_frames),
        )
    try:
        path = await _ensure_plan_studio_source_waveform(record)
    except asyncio.CancelledError:
        raise
    except (OSError, RuntimeError, TypeError, ValueError) as exc:
        _LOG.warning("Plan Studio source waveform failed: %s", exc)
        return web.json_response({"error": str(exc)}, status=500)
    return web.FileResponse(path, headers={
        "Cache-Control": "private, max-age=21600, immutable",
        "Content-Type": "application/json; charset=utf-8",
    })


async def _plan_studio_source_preview(request):
    token = str(request.query.get("token") or "")
    try:
        scene = int(request.query.get("scene", 0))
        slot = int(request.query.get("slot", 0))
    except (TypeError, ValueError):
        return web.json_response(
            {"error": "Source preview scene and slot must be integers."},
            status=400)
    if not re.fullmatch(r"[A-Za-z0-9_-]{24,64}", token):
        return web.json_response(
            {"error": "Source preview token is invalid."}, status=400)
    _plan_studio_preview_cleanup()
    session = _PLAN_STUDIO_SOURCE_PREVIEWS.get(token)
    if session is None:
        return web.json_response(
            {"error": "Source preview expired. Queue Plan Studio once to refresh it."},
            status=410)
    record = session.get("records", {}).get("%d:%d" % (scene, slot))
    if record is None:
        return web.json_response(
            {"error": "No active motion-reference window exists for this scene."},
            status=404)
    try:
        record = _validated_plan_studio_preview_record(record)
        session["created"] = time.monotonic()
        path = await _ensure_plan_studio_source_preview(record)
    except asyncio.CancelledError:
        _LOG.info(
            "Plan Studio source preview request canceled for scene %d slot %d; "
            "shared cache build continues", scene, slot)
        raise
    except (OSError, RuntimeError, TypeError, ValueError) as exc:
        _LOG.warning("Plan Studio source preview failed: %s", exc)
        return web.json_response({"error": str(exc)}, status=500)
    return web.FileResponse(path, headers={
        "Cache-Control": "private, max-age=21600, immutable",
    })


async def _optimize_scene_prompt(request):
    try:
        body = await request.json()
    except (json.JSONDecodeError, TypeError):
        return web.json_response(
            {"error": "The prompt optimizer request must contain JSON."},
            status=400)
    try:
        payload = await optimize_prompt_payload(body)
    except ValueError as exc:
        return web.json_response({"error": str(exc)}, status=400)
    except RuntimeError as exc:
        return web.json_response({"error": str(exc)}, status=502)
    except Exception:
        _LOG.exception("Direct prompt optimization failed")
        return web.json_response(
            {"error": "Direct prompt optimization failed unexpectedly. "
             "Check the ComfyUI server log."}, status=500)
    return web.json_response(payload)


def _project_asset_store() -> ProjectAssetStore:
    return ProjectAssetStore(_input_root(), _output_root())


def _owned_project_mutation(
        run_name: Any, ownership_proof: Any, operation: str,
        callback: Any, *args: Any, **kwargs: Any) -> Any:
    """Fence one short catalog/history mutation through its durable write."""
    run = _strict_run_name(run_name)
    with project_write_guard(
            _output_root(), run, ownership_proof, operation):
        return callback(*args, **kwargs)


def _project_asset_error_response(exc: Exception):
    if isinstance(exc, ProjectOwnershipError):
        return web.json_response({
            "error": str(exc), "code": "h3_project_read_only",
        }, status=423)
    return web.json_response({
        "error": str(exc),
        **({"code": "h3_project_asset_conflict"}
           if isinstance(exc, ProjectAssetConflictError) else {}),
    }, status=409 if isinstance(exc, ProjectAssetConflictError) else 400)


