def _project_write_rejection(request: Any, run_name: Any,
                             operation: str) -> Any:
    # Let each route retain its established missing-run validation. Ownership
    # can only be resolved after the route has an actual project identity.
    if not str(run_name or "").strip():
        return None
    try:
        normalized = _strict_run_name(run_name)
        _require_project_write(
            normalized, _request_project_ownership(request), operation)
    except ValueError as exc:
        if not isinstance(exc, ProjectOwnershipError):
            return web.json_response({"error": str(exc)}, status=400)
        return web.json_response({
            "error": str(exc),
            "code": "h3_project_read_only",
            "run_name": normalized,
        }, status=423)
    return None


def _publish_project_ownership(payload: dict[str, Any]) -> None:
    if PromptServer is None or getattr(PromptServer, "instance", None) is None:
        return
    try:
        PromptServer.instance.send_sync(
            "minimax_h3_project_ownership", payload)
    except Exception as exc:
        _LOG.debug("Could not publish H3 project ownership: %s", exc)


def _fence_inflight_project_work(run_name: Any) -> None:
    """Wake live gates and discard candidate control state after takeover."""
    try:
        normalized = _strict_run_name(run_name)
    except ValueError:
        return
    for token, entry in list(_ACTIVE_CANDIDATE_BATCHES.items()):
        if str(entry.get("run_name") or "").strip() == normalized:
            _ACTIVE_CANDIDATE_BATCHES.pop(token, None)
    for token, pending in list(_PENDING_REVIEWS.items()):
        public = pending.get("public")
        if (not isinstance(public, dict) or
                str(public.get("run_name") or "").strip() != normalized):
            continue
        _PENDING_REVIEWS.pop(token, None)
        future = pending.get("future")
        loop = pending.get("loop")
        if future is None or future.done():
            continue

        def reject(waiter=future, run=normalized):
            if not waiter.done():
                waiter.set_exception(ProjectOwnershipError(
                    "Project %s was taken over by another workflow while "
                    "this review was waiting." % run))

        if loop is not None and hasattr(loop, "call_soon_threadsafe"):
            loop.call_soon_threadsafe(reject)
        else:
            reject()


async def _project_ownership_command(request):
    try:
        body = await request.json()
        if not isinstance(body, dict):
            raise ValueError(
                "Project ownership request must be a JSON object.")
        run_name = _strict_run_name(body.get("run_name"))
        action = str(body.get("action") or "status").strip().lower()
        owner_id = body.get("owner_id", "")
        if action == "status":
            payload = ownership_status(_output_root(), run_name, owner_id)
        elif action in ("claim", "force"):
            before = ownership_status(_output_root(), run_name, owner_id)
            payload = claim_project_ownership(
                _output_root(), run_name, owner_id,
                body.get("owner_label", "Workflow"),
                force=action == "force")
            if (action == "force" and payload.get("owned_by_requester")
                    and (not before.get("owned_by_requester") or int(
                        payload.get("epoch", -1)) != int(
                            before.get("epoch", -1)))):
                _fence_inflight_project_work(run_name)
        elif action == "heartbeat":
            payload = heartbeat_project_ownership(
                _output_root(), run_name, owner_id, body.get("epoch"),
                body.get("owner_label", "Workflow"))
        elif action == "release":
            payload = release_project_ownership(
                _output_root(), run_name, owner_id, body.get("epoch"))
        else:
            raise ValueError(
                "Project ownership action must be status, claim, heartbeat, "
                "force, or release.")
        # Status polling and heartbeats must not echo into another status
        # broadcast loop. Only ownership transitions need to wake other tabs.
        if action in ("claim", "force", "release"):
            _publish_project_ownership(payload)
        return web.json_response(payload, headers={"Cache-Control": "no-store"})
    except ProjectOwnershipError as exc:
        return web.json_response({
            "error": str(exc), "code": "h3_project_read_only",
        }, status=423)
    except (OSError, TypeError, ValueError, json.JSONDecodeError) as exc:
        return web.json_response({"error": str(exc)}, status=400)


def _capture_frame_video_path(filename: Any, subfolder: Any, kind: Any) -> str:
    """Resolve a ComfyUI /view (filename, subfolder, type) triple to a file."""
    directories = {
        "input": folder_paths.get_input_directory(),
        "output": folder_paths.get_output_directory(),
        "temp": folder_paths.get_temp_directory(),
    }
    root = directories.get(str(kind or "output").strip().lower())
    if root is None:
        raise ValueError("Video source type must be input, output, or temp.")
    name = str(filename or "").strip()
    if not name:
        raise ValueError("Video filename cannot be blank.")
    sub = str(subfolder or "").strip()
    if os.path.isabs(name) or os.path.isabs(sub):
        raise ValueError("Video source must be relative to its selected media directory.")
    candidate = os.path.join(root, sub, name) if sub else os.path.join(root, name)
    candidate = os.path.realpath(candidate)
    if os.path.commonpath((os.path.realpath(root), candidate)) != os.path.realpath(root):
        raise ValueError("Video source is outside its selected media directory.")
    if os.path.splitext(candidate)[1].lower() not in VIDEO_EXTENSIONS:
        raise ValueError("Frame capture requires a supported video file, not a playlist.")
    return _confined_media_path(candidate, "Video source")


def _capture_frame_time(value: Any) -> float:
    if isinstance(value, bool):
        raise ValueError("Frame time must be a finite, non-negative number.")
    try:
        offset = float(value)
    except (TypeError, ValueError, OverflowError) as exc:
        raise ValueError("Frame time must be a finite, non-negative number.") from exc
    if not math.isfinite(offset) or offset < 0:
        raise ValueError("Frame time must be a finite, non-negative number.")
    return offset


def _capture_video_frame(video_path: str, time_seconds: float, output_path: str) -> None:
    ffmpeg = _usable_ffmpeg()
    if ffmpeg is None:
        raise RuntimeError("Capturing a video frame requires a working ffmpeg.")
    offset = _capture_frame_time(time_seconds)
    temporary = "%s.%s.tmp.png" % (output_path, uuid.uuid4().hex)
    command = [
        ffmpeg, "-hide_banner", "-loglevel", "error", "-y",
        "-ss", "%.6f" % offset, "-protocol_whitelist", "file",
        # Do not let a renamed playlist/concat file dereference other paths.
        "-format_whitelist", "avi,mov,matroska,webm,mpeg,mpegvideo", "-i", video_path,
        "-map", "0:v:0", "-frames:v", "1", "-an", temporary,
    ]
    try:
        _run_ffmpeg(command, timeout_seconds=60.0)
        if not os.path.isfile(temporary) or os.path.getsize(temporary) < 1:
            raise RuntimeError("ffmpeg produced an empty captured frame.")
        os.replace(temporary, output_path)
    finally:
        _safe_unlink(temporary)


def _project_asset_capture_frame_sync(
        project: Any, video_path: Any, subfolder: Any, source_type: Any,
        time_seconds: Any, tag: Any, role: Any,
        folder_id: Any, ownership_proof: Any = None) -> dict[str, Any]:
    project = _strict_run_name(project)
    operation = "capture a project asset frame"
    _require_project_write(project, ownership_proof, operation)
    offset = _capture_frame_time(time_seconds)
    source = _capture_frame_video_path(video_path, subfolder, source_type)
    store = _project_asset_store()
    temporary = store.upload_path(project, "frame_capture.png")
    try:
        _capture_video_frame(source, offset, temporary)
        # Extraction may outlive an ownership takeover. Fence the actual
        # import again so a stale workflow cannot publish its captured frame.
        return _owned_project_mutation(
            project, ownership_proof, operation, store.import_file,
            project, temporary, role=role or "", tag=tag,
            original_name="frame_capture.png", source_kind="frame_capture",
            folder_id=folder_id)
    finally:
        _safe_unlink(temporary)


async def _project_asset_capture_frame(request):
    try:
        body = await request.json()
        if not isinstance(body, dict):
            raise ValueError("Frame capture request must be a JSON object.")
        result = await asyncio.to_thread(
            _project_asset_capture_frame_sync,
            body.get("project", ""), body.get("filename", ""),
            body.get("subfolder", ""), body.get("type", "output"),
            body.get("time_seconds", 0.0), body.get("tag", ""),
            body.get("role", ""),
            body.get("folder_id") if "folder_id" in body else None,
            _request_project_ownership(request))
        return web.json_response(result)
    except (OSError, RuntimeError, TypeError, ValueError,
            json.JSONDecodeError) as exc:
        return _project_asset_error_response(exc)


async def _project_asset_media(request):
    try:
        project = request.query.get("project", "")
        asset_id = request.query.get("asset", "")
        variant = str(request.query.get("variant", "original")).lower()
        store = _project_asset_store()
        entry, path = await asyncio.to_thread(store.asset, project, asset_id)
        if variant == "poster":
            path = await asyncio.to_thread(store.ensure_poster, project, asset_id)
        elif variant == "thumbnail":
            path = await asyncio.to_thread(
                store.ensure_thumbnail, project, asset_id)
        elif variant == "preview":
            path = await asyncio.to_thread(
                store.ensure_browser_media, project, asset_id)
        elif variant != "original":
            raise ValueError(
                "Asset media variant must be original, poster, thumbnail, "
                "or preview.")
        return web.FileResponse(path, headers={
            "Cache-Control": "private, max-age=3600",
            "Content-Disposition": "inline; filename=%s" % json.dumps(
                os.path.basename(path)),
            "X-H3-Asset-Kind": str(entry.get("kind") or ""),
        })
    except FileNotFoundError as exc:
        return web.json_response({"error": str(exc)}, status=404)
    except (OSError, RuntimeError, TypeError, ValueError) as exc:
        return web.json_response({"error": str(exc)}, status=400)


# ---------------------------------------------------------------------------
# Durable top-level handoff routes (top-level scene requeue).
#
# These are the ONLY backend surface for the separate run-local handoff
# state written by Chain Loop End in top_level_requeue mode. They read and
# mutate records under output/h3_chains/<run>/orchestration/ via the
# exactly-once HandoffStore primitives; they never accept filesystem paths
# and never touch the Plan JSON. The frontend coordinator calls them in the
# order: list -> claim -> (queue new top-level prompt) -> transition queued
# -> transition consumed; failures release the claim for manual recovery.
# ---------------------------------------------------------------------------


_HANDOFF_TRANSITION_STATUSES = ("queued", "consumed", "cancelled", "failed", "uncertain")


def _handoff_store() -> "_HandoffStore":
    return _HandoffStore(_output_root())


def _handoff_scene_count(run_name: str) -> int | None:
    """Scene count of the run's saved Plan, or None when unreadable."""
    plan_path = os.path.join(_run_dir({"run_name": _safe_name(run_name, "")}), "plan.json")
    try:
        with open(plan_path, "r", encoding="utf-8") as handle:
            plan = json.load(handle)
        shots = plan.get("shots")
        if isinstance(shots, list) and shots:
            return len(shots)
    except (OSError, TypeError, json.JSONDecodeError):
        pass
    return None


def _handoff_record_view(record: dict[str, Any]) -> dict[str, Any]:
    """Record plus a safe manual-resume hint (widgets only, no paths)."""
    view = dict(record)
    if record.get("action") != "next_scene":
        return view
    start = record.get("start_clip")
    end = record.get("end_clip")
    with branch_scope(record.get("run_name", ""), record.get("working_branch_id", "main")):
        total = _handoff_scene_count(record.get("run_name", ""))
    if not isinstance(start, int) or isinstance(start, bool) or start < 1:
        return view
    if total is None:
        total = max(start + 1, int(end) if isinstance(end, int) else start + 1)
    resolved_end = end if isinstance(end, int) and not isinstance(end, bool) else total
    if resolved_end < total:
        scene_range = str(start) if start == resolved_end \
            else "%d:%d" % (start, resolved_end)
    else:
        scene_range = ""
    view["resume"] = {
        "start_clip": start,
        "scene_range": scene_range,
        "end_clip": resolved_end,
        "total_scenes": total,
    }
    return view


async def _list_handoffs(request):
    run_name = _safe_name(request.query.get("run_name", ""), "")
    if not run_name:
        return web.json_response(
            {"error": "run_name is required."}, status=400)
    try:
        records = await asyncio.to_thread(
            _handoff_store().list, run_name)
        views = [_handoff_record_view(record) for record in records]
    except _HandoffError as exc:
        return web.json_response({"error": str(exc)}, status=400)
    return web.json_response({"run_name": run_name, "handoffs": views})


async def _claim_handoff(request):
    try:
        body = await request.json()
    except (json.JSONDecodeError, TypeError):
        return web.json_response(
            {"error": "H3 handoff claim requires JSON."}, status=400)
    run_name = _safe_name(str(body.get("run_name") or ""), "")
    handoff_id = str(body.get("handoff_id") or "").strip()
    source_prompt_id = str(body.get("source_prompt_id") or "").strip() or None
    if not run_name or not handoff_id:
        return web.json_response(
            {"error": "run_name and handoff_id are required."}, status=400)
    ownership_proof = _request_project_ownership(request)
    rejection = _project_write_rejection(request, run_name, "claim a scene handoff")
    if rejection is not None:
        return rejection
    try:
        record = await asyncio.to_thread(
            _owned_project_mutation, run_name, ownership_proof,
            "claim a scene handoff", _handoff_store().claim, run_name, handoff_id,
            "top_level_requeue", source_prompt_id)
    except ProjectOwnershipError as exc:
        return _project_asset_error_response(exc)
    except _HandoffNotFoundError as exc:
        return web.json_response({"error": str(exc)}, status=404)
    except _HandoffClaimError as exc:
        return web.json_response({"error": str(exc)}, status=409)
    except _HandoffError as exc:
        return web.json_response({"error": str(exc)}, status=400)
    return web.json_response({"handoff": _handoff_record_view(record)})


async def _transition_handoff(request):
    try:
        body = await request.json()
    except (json.JSONDecodeError, TypeError):
        return web.json_response(
            {"error": "H3 handoff transition requires JSON."}, status=400)
    run_name = _safe_name(str(body.get("run_name") or ""), "")
    handoff_id = str(body.get("handoff_id") or "").strip()
    status = str(body.get("status") or "").strip()
    accepted_prompt_id = str(body.get("accepted_prompt_id") or "").strip() or None
    if status not in _HANDOFF_TRANSITION_STATUSES:
        return web.json_response({
            "error": "status must be one of %s." %
                     (", ".join(_HANDOFF_TRANSITION_STATUSES),),
        }, status=400)
    if not run_name or not handoff_id:
        return web.json_response(
            {"error": "run_name and handoff_id are required."}, status=400)
    ownership_proof = _request_project_ownership(request)
    rejection = _project_write_rejection(request, run_name, "transition a scene handoff")
    if rejection is not None:
        return rejection
    try:
        record = await asyncio.to_thread(
            _owned_project_mutation, run_name, ownership_proof,
            "transition a scene handoff", _handoff_store().transition, run_name, handoff_id, status,
            accepted_prompt_id)
    except ProjectOwnershipError as exc:
        return _project_asset_error_response(exc)
    except _HandoffNotFoundError as exc:
        return web.json_response({"error": str(exc)}, status=404)
    except _IllegalHandoffTransitionError as exc:
        return web.json_response({"error": str(exc)}, status=409)
    except _HandoffError as exc:
        return web.json_response({"error": str(exc)}, status=400)
    return web.json_response({"handoff": _handoff_record_view(record)})


async def _release_handoff(request):
    try:
        body = await request.json()
    except (json.JSONDecodeError, TypeError):
        return web.json_response(
            {"error": "H3 handoff release requires JSON."}, status=400)
    run_name = _safe_name(str(body.get("run_name") or ""), "")
    handoff_id = str(body.get("handoff_id") or "").strip()
    reason = str(body.get("reason") or "").strip() or None
    if not run_name or not handoff_id:
        return web.json_response(
            {"error": "run_name and handoff_id are required."}, status=400)
    ownership_proof = _request_project_ownership(request)
    rejection = _project_write_rejection(request, run_name, "release a scene handoff")
    if rejection is not None:
        return rejection
    try:
        record = await asyncio.to_thread(
            _owned_project_mutation, run_name, ownership_proof,
            "release a scene handoff", _handoff_store().release, run_name, handoff_id, reason)
    except ProjectOwnershipError as exc:
        return _project_asset_error_response(exc)
    except _HandoffNotFoundError as exc:
        return web.json_response({"error": str(exc)}, status=404)
    except _IllegalHandoffTransitionError as exc:
        return web.json_response({"error": str(exc)}, status=409)
    except _HandoffError as exc:
        return web.json_response({"error": str(exc)}, status=400)
    return web.json_response({"handoff": _handoff_record_view(record)})


async def _working_branch_command(request):
    try:
        body = dict(request.query) if request.method == "GET" else await request.json()
        if not isinstance(body, dict):
            raise ValueError("Working branch request must be a JSON object.")
        run = _strict_run_name(body.get("run_name"))
        store = WorkingBranches(_output_root(), run)
        action = body.get("action", "list")
        selected = _working_branch_id(body.get("branch_id", "main"))
        if action == "list":
            return web.json_response(store.listing())
        if action == "load":
            return web.json_response(store.load(selected))
        if request.method != "POST":
            return web.json_response({"error": "Branch changes require POST."}, status=405)
        rejection = _project_write_rejection(request, run, "edit a working branch")
        if rejection is not None:
            return rejection
        with checkpoint_run_lock(_output_root(), run), project_write_guard(_output_root(), run,
                _request_project_ownership(request), "edit a working branch"):
            if action == "save":
                result = store.save(selected, body.get("authoring"), body.get("revision"),
                                    body.get("operation_id", ""))
            elif action == "create":
                through = body.get("through_scene", 0)
                recovered = store.retry_create(selected, body.get("name"), body.get("authoring"),
                                               through, body.get("operation_id", ""))
                if recovered is not None:
                    return web.json_response(recovered)
                with checkpoint_run_lock(_output_root(), run), branch_scope(run, selected):
                    active, stale = CheckpointGraphManager(_output_root()).active_selection(run)
                    if (type(through) is not int or through < 0 or through > MAX_SHOTS or
                            any(i not in active or i in stale for i in range(1, through + 1))):
                        raise ValueError("Fork requires a coherent saved prefix of the selected branch.")
                    for i in range(1, through + 1):
                        _load_checkpoint_revision(run, i, active[i])
                    result = store.create(selected, body.get("name"), body.get("authoring"), through,
                                          body.get("operation_id", ""))
            elif action == "default":
                result = store.make_default(selected)
            else:
                raise ValueError("Unknown working branch action.")
        return web.json_response(result)
    except ProjectOwnershipError as exc:
        return web.json_response({"error": str(exc), "code": "h3_project_read_only"}, status=423)
    except OSError as exc:
        # Includes uncertain post-rename durability failures; replay the same
        # operation id before deciding that the mutation did not commit.
        return web.json_response({"error": str(exc)}, status=500)
    except (ValueError, TypeError, KeyError) as exc:
        return web.json_response({"error": str(exc)}, status=400)


